/** 大規模工程スケジュール: sort_order 0-13（14行） */
export const WORK_LARGE_SCHEDULE_COUNT = 14
export const WORK_LARGE_SCHEDULE_ORDER_MAX = 13

export function emptyWorkLargeScheduleRows() {
  return Array.from({ length: WORK_LARGE_SCHEDULE_COUNT }, (_, sort_order) => ({
    sort_order,
    label: '',
    schedule_status_id: null,
    schedule_secondary_status_id: null,
    start_on: null,
    end_on: null,
    note: '',
  }))
}

export function padWorkLargeScheduleRows(rows) {
  const byOrder = new Map()
  for (const r of rows || []) {
    const o = Number(r?.sort_order)
    if (!Number.isFinite(o) || o < 0 || o > WORK_LARGE_SCHEDULE_ORDER_MAX) continue
    byOrder.set(o, normalizeScheduleRow(r, o))
  }
  return Array.from({ length: WORK_LARGE_SCHEDULE_COUNT }, (_, i) =>
    byOrder.get(i) ?? {
      sort_order: i,
      label: '',
      schedule_status_id: null,
      schedule_secondary_status_id: null,
      start_on: null,
      end_on: null,
      note: '',
    }
  )
}

export function buildWorkLargeScheduleRowsFromTemplate(templates) {
  const base = emptyWorkLargeScheduleRows()
  const sorted = [...(templates || [])].sort(
    (a, b) => Number(a.sort_order) - Number(b.sort_order)
  )
  for (const tpl of sorted) {
    const o = Number(tpl?.sort_order)
    if (!Number.isFinite(o) || o < 0 || o > WORK_LARGE_SCHEDULE_ORDER_MAX) continue
    base[o] = {
      ...base[o],
      label: String(tpl?.label ?? ''),
    }
  }
  return base
}

function normalizeScheduleRow(row, sort_order) {
  return {
    id: row?.id ?? null,
    sort_order,
    label: String(row?.label ?? ''),
    schedule_status_id: row?.schedule_status_id ?? null,
    schedule_secondary_status_id: row?.schedule_secondary_status_id ?? null,
    start_on: row?.start_on ?? null,
    end_on: row?.end_on ?? null,
    note: String(row?.note ?? ''),
    updated_at: row?.updated_at ?? null,
  }
}

export function validateScheduleRowsForSave(rows) {
  if (!Array.isArray(rows) || rows.length !== WORK_LARGE_SCHEDULE_COUNT) {
    return '14行すべて入力してください'
  }
  for (const row of rows) {
    const start = row?.start_on ? String(row.start_on) : ''
    const end = row?.end_on ? String(row.end_on) : ''
    if (start && end && end < start) {
      return `終了日は開始日以降にしてください（行 ${Number(row.sort_order) + 1}）`
    }
  }
  return null
}
