  /**
   * work の room_labels のみ取得し IndexedDB にキャッシュ（Edge: get_room_labels）
   */
  async getRoomLabelsForWork(workId, forceReload = false) {
    try {
      const { indexedDBService } = await import('../utils/indexedDB')
      if (!forceReload) {
        const labels = await indexedDBService.getRoomLabels(workId)
        return { room_labels: labels || [] }
      }

      const wid = workId != null ? String(workId) : ''
      if (!wid) return { room_labels: [] }

      const inflight = inFlightRoomLabelsByWorkId.get(wid)
      if (inflight) return inflight

      const requestPromise = (async () => {
        const response = await fetch(
          `${SUPABASE_URL}/functions/v1/get_room_labels`,
          {
            method: 'POST',
            headers: this.getHeaders(),
            body: JSON.stringify({ work_id: wid })
          }
        )

        if (!response.ok) {
          const errorText = await response.text()
          let errorMessage = `HTTP error! status: ${response.status}`
          try {
            const errorJson = JSON.parse(errorText)
            if (errorJson.error) errorMessage = errorJson.error
          } catch {}
          throw new Error(errorMessage)
        }

        const result = await response.json()
        if (Array.isArray(result.room_labels)) {
          await indexedDBService.cacheRoomLabels(wid, result.room_labels)
        }
        return result
      })().finally(() => {
        inFlightRoomLabelsByWorkId.delete(wid)
      })

      inFlightRoomLabelsByWorkId.set(wid, requestPromise)
      return requestPromise
    } catch (error) {
      console.error('Error getting room labels for work:', error)
      throw error
    }
  },

