  /**
   * IndexedDB の estimate_slots キャッシュとルームラベルのみ参照（get_estimate_slot Edge は廃止）。
   * mode: "slots" | "both" | "room_labels"
   */
  async getEstimateSlots(workId, forceReload = false, mode = "slots") {
    try {
      if (mode === "room_labels") {
        return this.getRoomLabelsForWork(workId, forceReload)
      }

      const { indexedDBService } = await import('../utils/indexedDB')
      const slots = (await indexedDBService.getEstimateSlots(workId)) || []

      if (mode === "both") {
        let room_labels
        if (forceReload) {
          const r = await this.getRoomLabelsForWork(workId, true)
          room_labels = r.room_labels || []
        } else {
          room_labels = (await indexedDBService.getRoomLabels(workId)) || []
        }
        return { slots, room_labels }
      }

      return { slots }
    } catch (error) {
      console.error('Error getting estimate slots:', error)
      throw error
    }
  },

