  // 請求項目を取得（IndexedDBキャッシュ対応）
  async getBillingItems(workId, options = {}) {
    const { forceRefresh = false, useCache = true } = options
    
    try {
      // IndexedDBキャッシュをインポート（動的インポートで循環参照を回避）
      const { indexedDBService } = await import('../utils/indexedDB.js')
      
      // キャッシュから取得を試みる
      if (useCache && !forceRefresh) {
        const cached = await indexedDBService.getBillingItems(workId)
        if (cached) {
          // バックグラウンドで更新チェック（非同期、結果を待たない）
          this._refreshWorkInfoInBackground(workId, cached.cached_at)
          
          return {
            billingItems: cached.items,
            kind: cached.kind,
            fromCache: true
          }
        }
      }
      
      // サーバーから取得
      const response = await fetch(
        `${SUPABASE_URL}/functions/v1/get_billing_item`,
        {
          method: 'POST',
          headers: this.getHeaders(),
          body: JSON.stringify({ work_id: workId })
        }
      )
      
      if (!response.ok) {
        // 400エラーの場合は請求項目がない可能性があるため、空配列を返す
        if (response.status === 400 || response.status === 404) {
          return {
            billingItems: [],
            kind: null
          }
        }
        
        const errorText = await response.text()
        let errorMessage = `HTTP error! status: ${response.status}`
        
        try {
          const errorJson = JSON.parse(errorText)
          if (errorJson.error) {
            errorMessage = errorJson.error
          } else if (errorJson.message) {
            errorMessage = errorJson.message
          }
        } catch {
          if (errorText) {
            errorMessage = errorText
          }
        }
        
        const error = new Error(errorMessage)
        error.status = response.status
        throw error
      }
      
      const data = await response.json()
      const result = {
        billingItems: data.billing_items || [],
        kind: data.kind
      }
      
      // IndexedDBにキャッシュ（空配列もキャッシュする）
      if (useCache) {
        await indexedDBService.cacheBillingItems(workId, result.billingItems, result.kind)
      }
      
      return result
    } catch (error) {
      console.error('Error fetching billing items:', error)
      // エラーが発生しても空配列を返す（請求項目がない場合のフォールバック）
      return {
        billingItems: [],
        kind: null
      }
    }
  },
  
  // work_info（billing + large schedule）をバックグラウンド更新
  async _refreshWorkInfoInBackground(workId, _cachedAt) {
    try {
      const { indexedDBService } = await import('../utils/indexedDB.js')

      const checkResponse = await fetch(
        `${SUPABASE_URL}/functions/v1/check_work_info_update`,
        {
          method: 'POST',
          headers: this.getHeaders(),
          body: JSON.stringify({ work_id: workId })
        }
      )

      if (!checkResponse.ok) {
        console.error('Failed to check work info update')
        return
      }

      const checkData = await checkResponse.json()
      const billingSummary = checkData.billing_items || {}
      const scheduleSummary = checkData.large_schedule

      const cachedBilling = await indexedDBService.getBillingItems(workId)
      const cachedItems = cachedBilling?.items || []

      let billingNeedsUpdate = false
      if ((billingSummary.count ?? 0) !== cachedItems.length) {
        billingNeedsUpdate = true
      } else if (billingSummary.max_updated_at && cachedItems.length > 0) {
        const cachedMaxUpdatedAt = Math.max(...cachedItems.map(item =>
          item.updated_at ? new Date(item.updated_at).getTime() : 0
        ))
        if (new Date(billingSummary.max_updated_at).getTime() > cachedMaxUpdatedAt) {
          billingNeedsUpdate = true
        }
      }

      if (billingNeedsUpdate) {
        const response = await fetch(
          `${SUPABASE_URL}/functions/v1/get_billing_item`,
          {
            method: 'POST',
            headers: this.getHeaders(),
            body: JSON.stringify({ work_id: workId })
          }
        )

        if (response.ok) {
          const data = await response.json()
          await indexedDBService.cacheBillingItems(
            workId,
            data.billing_items || [],
            data.kind,
            true
          )
        }
      }

      if (checkData.kind !== 'large' || !scheduleSummary) {
        return
      }

      const cachedSchedule = await indexedDBService.getWorkLargeSchedules(workId)
      const cachedRows = cachedSchedule?.rows || []

      let scheduleNeedsUpdate = false
      if ((scheduleSummary.count ?? 0) !== cachedRows.length) {
        scheduleNeedsUpdate = true
      } else if (scheduleSummary.max_updated_at && cachedRows.length > 0) {
        const cachedMaxUpdatedAt = Math.max(...cachedRows.map(row =>
          row.updated_at ? new Date(row.updated_at).getTime() : 0
        ))
        if (new Date(scheduleSummary.max_updated_at).getTime() > cachedMaxUpdatedAt) {
          scheduleNeedsUpdate = true
        }
      } else if ((scheduleSummary.count ?? 0) > 0 && cachedRows.length === 0) {
        scheduleNeedsUpdate = true
      }

      if (scheduleNeedsUpdate) {
        const result = await this.fetchWorkLargeSchedulesFromServer(workId)
        if (result?.rows) {
          await indexedDBService.cacheWorkLargeSchedules(workId, result.rows, true)
        }
      }
    } catch (error) {
      console.error('Background work info refresh failed:', error)
    }
  },

