  // ============================================================================
  // フォルダ API（manage_cloud_storage create_folder 使用）
  // ============================================================================

  // 案件フォルダを作成（manage_cloud_storage create_folder + commit）
  async addWorkFolder(workId, label, parentId = null) {
    const data = await this.manageCloudStorage({
      action: 'create_folder',
      scope: 'work',
      work_id: workId,
      name: label,
      parent_id: parentId
    })
    const folder = data.folder
    if (folder?.id) {
      await this.manageCloudStorage({
        action: 'commit',
        scope: 'work',
        work_id: workId,
        ids: [folder.id]
      })
    }
    return folder
  },

  // 新しいフォルダを作成（manage_cloud_storage create_folder + commit）
  async createWorkCategory(workId, label, isPhase = false, sortOrder = null) {
    return this.createWorkFolder(workId, label, null)
  },

  async createWorkFolder(workId, name, parentId = null) {
    try {
      const trimmed = String(name ?? '').trim()
      const data = await this.manageCloudStorage({
        action: 'create_folder',
        scope: 'work',
        work_id: workId,
        name: trimmed,
        parent_id: parentId ?? null
      })
      const folder = data.folder
      if (folder?.id) {
        await this.manageCloudStorage({
          action: 'commit',
          scope: 'work',
          work_id: workId,
          ids: [folder.id]
        })
      }
      return folder ? { ...folder, label: folder.name } : folder
    } catch (error) {
      console.error('Error creating work folder:', error)
      throw error
    }
  },

