  // プライスリスト一覧を取得
  async getPriceLists(fiscalYear, kind = 'large') {
    try {
      try {
        const { indexedDBService } = await import('../utils/indexedDB')
        const cached = await indexedDBService.getPriceLists()
        const filtered = (cached || []).filter((pl) => {
          if (kind && pl.kind !== kind) return false
          if (fiscalYear !== null && fiscalYear !== undefined && Number(pl.fiscal_year) !== Number(fiscalYear)) return false
          return true
        })
        if (filtered.length > 0) {
          return filtered
        }
      } catch (cacheError) {
        console.warn('Failed to get price lists from IndexedDB, falling back to server:', cacheError)
      }

      const requestBody = { resource: 'price_lists', kind }
      if (fiscalYear !== null && fiscalYear !== undefined) {
        requestBody.fiscal_year = fiscalYear
      }
      
      const response = await fetch(
        `${SUPABASE_URL}/functions/v1/get_static_data`,
        {
          method: 'POST',
          headers: this.getHeaders(),
          body: JSON.stringify(requestBody)
        }
      )
      
      if (!response.ok) {
        const errorText = await response.text()
        let errorMessage = `HTTP error! status: ${response.status}`
        try {
          const errorJson = JSON.parse(errorText)
          if (errorJson.error) errorMessage = errorJson.error
        } catch {}
        throw new Error(errorMessage)
      }
      
      const data = await response.json()
      return data.price_lists || []
    } catch (error) {
      console.error('Error getting price lists:', error)
      throw error
    }
  },

  // プライスリストアイテムを取得（IndexedDBから）
  async getPriceListItems(priceListId) {
    try {
      const { indexedDBService } = await import('../utils/indexedDB')
      
      // price_listsテーブルからprice_list_itemsを取得
      const items = await indexedDBService.price_lists
        .where('table_name')
        .equals('price_list_items')
        .and(item => 
          item.price_list_id === priceListId &&
          item.is_active === true
        )
        .toArray()
      
      // external_codeでソート
      const sorted = items.sort((a, b) => {
        const codeA = a.external_code || ''
        const codeB = b.external_code || ''
        return codeA.localeCompare(codeB)
      })
      
      return sorted
    } catch (error) {
      console.error('Error getting price list items:', error)
      throw error
    }
  },

