  // 見積スロットをアップサート
  async upsertEstimateSlot(slot) {
    try {
      const response = await fetch(
        `${SUPABASE_URL}/functions/v1/upsert_estimate_slot`,
        {
          method: 'POST',
          headers: this.getHeaders(),
          body: JSON.stringify({ slot })
        }
      )
      
      if (!response.ok) {
        const errorText = await response.text()
        let errorMessage = `HTTP error! status: ${response.status}`
        try {
          const errorJson = JSON.parse(errorText)
          if (errorJson.error) errorMessage = errorJson.error
        } catch {}
        throw new Error(errorMessage)
      }
      
      const result = await response.json()
      
      // 保存成功後、IndexedDBのキャッシュを更新
      if (result.success && result.slot && slot.work_id) {
        try {
          const { indexedDBService } = await import('../utils/indexedDB')
          const cachedSlots = await indexedDBService.getEstimateSlots(slot.work_id)
          
          // 既存スロットを更新または追加
          const slotIndex = cachedSlots.findIndex(s => s.id === result.slot.id)
          if (slotIndex >= 0) {
            cachedSlots[slotIndex] = result.slot
          } else {
            cachedSlots.push(result.slot)
          }
          
          // キャッシュを更新
          await indexedDBService.cacheEstimateSlots(slot.work_id, cachedSlots)
        } catch (cacheErr) {
          console.warn('Failed to update IndexedDB cache:', cacheErr)
        }
      }
      
      return result
    } catch (error) {
      console.error('Error upserting estimate slot:', error)
      throw error
    }
  },

  // 見積スロットを削除（ソフトデリート）
  async deleteEstimateSlot(slotId, workId) {
    try {
      const response = await fetch(
        `${SUPABASE_URL}/functions/v1/delete_estimate_slot`,
        {
          method: 'POST',
          headers: this.getHeaders(),
          body: JSON.stringify({ slot_id: slotId })
        }
      )
      
      if (!response.ok) {
        const errorText = await response.text()
        let errorMessage = `HTTP error! status: ${response.status}`
        try {
          const errorJson = JSON.parse(errorText)
          if (errorJson.error) errorMessage = errorJson.error
        } catch {}
        throw new Error(errorMessage)
      }
      
      const result = await response.json()
      
      // 削除成功後、IndexedDBのキャッシュを更新
      if (result.success && workId) {
        try {
          const { indexedDBService } = await import('../utils/indexedDB')
          const cachedSlots = await indexedDBService.getEstimateSlots(workId)
          
          // 削除されたスロットを除外
          const updatedSlots = cachedSlots.filter(s => s.id !== slotId)
          
          // キャッシュを更新
          await indexedDBService.cacheEstimateSlots(workId, updatedSlots)
        } catch (cacheErr) {
          console.warn('Failed to update IndexedDB cache:', cacheErr)
        }
      }
      
      return result
    } catch (error) {
      console.error('Error deleting estimate slot:', error)
      throw error
    }
  },

