<template>
  <div
    class="estimate-grid-editor"
    ref="rootEl"
    :style="rootStyle"
    :class="{
      'estimate-tablet-photo-chrome-visible': isTablet && showPhotoWorkTab,
      'estimate-tablet-original-view': isTabletOriginalDirectEditMode,
      'estimate-tablet-original-price-panel': isTabletOriginalPricePanelMode
    }"
  >
    <!-- Work ID未指定時、またはsmall案件の場合のメッセージ -->
    <div v-if="!props.workId || props.workKind === 'small'" class="no-work-message">
      <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="12" cy="12" r="10"></circle>
        <line x1="12" y1="8" x2="12" y2="12"></line>
        <line x1="12" y1="16" x2="12.01" y2="16"></line>
      </svg>
      <p v-if="!props.workId">検索から案件を選択して「見積」ボタンを押してください</p>
      <p v-else-if="props.workKind === 'small'">見積グリッド編集は小口案件では使用できません</p>
    </div>
    
    <!-- 全画面ローディングは App.vue Teleport に集約（useAppOverlay） -->
    
    <!-- メインコンテンツエリア -->
    <div v-if="props.workId && props.workKind !== 'small'" class="main-content">
      <!-- 左パネル：プライスリスト/比較切り替え（タブレット原本は単価ボタンで単価リストのみ） -->
      <div
        v-if="showLeftPanel"
        ref="leftPanelRef"
        class="left-panel"
        :class="{ 'left-panel--tablet-price-only': isTabletOriginalPricePanelMode }"
        @click.capture="handleLeftPanelClick"
      >
      <!-- パネル切り替えタブ -->
      <div v-if="isDesktop" class="left-panel-tabs">
        <button 
          class="panel-tab" 
          :class="{ active: leftPanelMode === 'pricelist' }"
          @click="leftPanelMode = 'pricelist'"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
            <polyline points="14 2 14 8 20 8"></polyline>
            <line x1="16" y1="13" x2="8" y2="13"></line>
            <line x1="16" y1="17" x2="8" y2="17"></line>
            <polyline points="10 9 9 9 8 9"></polyline>
          </svg>
          <span>プライスリスト</span>
        </button>
        <button 
          class="panel-tab" 
          :class="{ active: leftPanelMode === 'comparison' }"
          @click="leftPanelMode = 'comparison'"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <polyline points="16 18 22 12 16 6"></polyline>
            <polyline points="8 6 2 12 8 18"></polyline>
          </svg>
          <span>比較</span>
        </button>
      </div>

      <!-- プライスリストモード（グリッドタブ非表示中は DOM を外して仮想スクロールを停止） -->
      <div v-if="isPriceListPanelVisible" class="panel-content">
        <!-- フィルター行 -->
        <div class="filter-row" @click.stop>
          <select 
            v-model="selectedPriceListId" 
            @change="handlePriceListSelectChange" 
            @click.stop
            :disabled="priceLists.length === 0" 
            class="pricelist-select" 
            :class="{ 'placeholder': !selectedPriceListId }"
          >
            <option value="">プライスリスト</option>
            <option v-for="pl in priceLists" :key="pl.id" :value="pl.id">{{ pl.label }}</option>
          </select>
          <select 
            v-model="selectedBigCategory" 
            @change="handleBigCategoryChange" 
            @click.stop
            class="category-select" 
            :class="{ 'placeholder': !selectedBigCategory }"
          >
            <option value="">区分</option>
            <option v-for="cat in bigCategoryOptions" :key="cat.id" :value="cat.id">{{ cat.label }}</option>
          </select>
          <select 
            v-model="selectedSmallCategory" 
            @click.stop
            class="category-select" 
            :class="{ 'placeholder': !selectedSmallCategory }"
          >
            <option value="">大分類</option>
            <option v-for="cat in smallCategoryOptions" :key="cat.id" :value="cat.id">{{ cat.label }}</option>
          </select>
        </div>

        <!-- 検索 -->
        <div class="search-row" @click.stop>
          <input 
            type="text" 
            v-model="searchQuery" 
            placeholder="コード・説明で検索..."
            class="search-input"
            @click.stop
          />
          <button
            type="button"
            class="price-list-filter-reset-btn"
            title="区分・大分類・検索をクリア"
            @click.stop="resetPriceListFiltersOnly"
          >
            ✕
          </button>
        </div>

        <!-- アイテム一覧（仮想スクロール） -->
        <div ref="priceListScrollEl" class="items-list" @click.stop>
          <div v-if="priceListError" class="error-state">
            {{ priceListError }}
            <button @click="loadPriceListItems" class="retry-btn">再読み込み</button>
          </div>
          <template v-else>
            <div v-if="!selectedPriceListId" class="empty-state">
              プライスリストを選択してください
            </div>
            <div v-else-if="priceListItems.length === 0" class="empty-state">
              アイテムがありません
            </div>
            <template v-else>
              <div v-if="filteredItems.length === 0" class="empty-state">
                検索結果がありません
              </div>
              <div
                v-else
                class="price-list-virtual-viewport"
                :style="{
                  height: `${priceListVirtualizer.getTotalSize()}px`,
                  position: 'relative',
                  width: '100%',
                }"
              >
                <div
                  v-for="v in priceListVirtualizer.getVirtualItems()"
                  :key="v.key"
                  :ref="priceListVirtualizer.measureElement"
                  class="price-item-virtual-wrap"
                  :data-index="v.index"
                  :data-price-item-id="filteredItems[v.index]?.id"
                  :data-external-code="String(filteredItems[v.index]?.external_code ?? '')"
                  :style="{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    transform: `translateY(${v.start}px)`,
                  }"
                >
                  <div
                    v-if="filteredItems[v.index]"
                    class="price-item"
                    :class="{ expanded: expandedItemId === filteredItems[v.index].id }"
                    draggable="true"
                    @click="onPriceListItemClick(filteredItems[v.index])"
                    @dragstart="handlePriceItemDragStart($event, filteredItems[v.index])"
                    @dragend="handlePriceItemDragEnd"
                  >
                    <div class="item-row-1">
                      <div class="item-code">{{ filteredItems[v.index].external_code }}</div>
                      <div
                        class="item-description"
                        :class="{ truncated: expandedItemId !== filteredItems[v.index].id }"
                      >
                        {{ filteredItems[v.index].description }}
                      </div>
                    </div>
                    <div class="item-row-2">
                      <div
                        class="item-note"
                        :class="{ truncated: expandedItemId !== filteredItems[v.index].id }"
                      >
                        {{ filteredItems[v.index].additional_description || filteredItems[v.index].note || '-' }}
                      </div>
                      <div class="item-price">¥{{ formatPrice(filteredItems[v.index].unit_price) }}</div>
                      <div class="item-unit">{{ filteredItems[v.index].unit || '-' }}</div>
                    </div>
                  </div>
                </div>
              </div>
            </template>
          </template>
        </div>
      </div>

      <!-- 比較モード -->
      <div v-else-if="isDesktop && leftPanelMode === 'comparison'" class="panel-content">
        <div class="comparison-panel-toolbar">
        <div class="comparison-panel-header">
          <div class="comparison-panel-title-row">
            <span v-if="comparisonData.length > 0" class="comparison-calc-amount">
              ¥{{ formatPrice(comparisonCalculatedAmount) }}
            </span>
            <span v-else class="comparison-panel-title">請求比較</span>
          </div>
          <div class="comparison-actions">
            <button
              type="button"
              class="comparison-filter-toggle-btn comparison-search-toggle-btn"
              :class="{ active: comparisonSearchOpen }"
              title="比較を検索"
              aria-label="比較を検索"
              :aria-pressed="comparisonSearchOpen"
              @click="toggleComparisonSearch"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <circle cx="11" cy="11" r="7" />
                <path d="M16.5 16.5L21 21" />
              </svg>
            </button>
            <button
              type="button"
              class="comparison-filter-toggle-btn"
              :class="{ active: comparisonHideMatchedFilter }"
              :title="comparisonHideMatchedFilter ? '一致項目の非表示を解除' : '見=公・公=修正数量が一致する行を非表示'"
              aria-label="一致項目を非表示"
              :aria-pressed="comparisonHideMatchedFilter"
              @click="toggleComparisonHideMatchedFilter"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <path d="M4 6h16" />
                <path d="M7 12h10" />
                <path d="M10 18h4" />
                <path d="M12 3v2M12 19v2" opacity="0.4" />
              </svg>
            </button>
            <button
              class="comparison-btn compare-btn"
              @click="executeComparison"
              :disabled="!props.workId || comparisonSaving || comparisonLoading"
            >
              比較
            </button>
            <button 
              class="comparison-btn save-btn" 
              @click="saveComparison"
              :disabled="comparisonData.length === 0 || comparisonSaving"
            >
              保存
            </button>
            <button 
              class="comparison-btn clear-btn"
              @click="refreshComparison"
              :disabled="!props.workId || comparisonSaving"
              title="比較データを消去"
              aria-label="比較データを消去"
            >
              ✕
            </button>
          </div>
        </div>
        <div v-if="comparisonSearchOpen" class="comparison-search-bar">
          <input
            ref="comparisonSearchInputRef"
            v-model="comparisonSearchQuery"
            type="search"
            class="comparison-search-input"
            placeholder="コード・説明で検索"
            aria-label="比較検索"
          />
        </div>
        </div>
        
        <div ref="comparisonContentScrollRef" class="comparison-content">
          <div v-if="comparisonLoading" class="comparison-loading">
            比較データを読み込み中
          </div>
          <div v-else-if="comparisonData.length === 0" class="comparison-empty">
            <p>比較データがありません</p>
            <p class="hint">「比較」ボタンを押して比較を開始してください</p>
          </div>
          <div v-else-if="displayedComparisonData.length === 0" class="comparison-empty">
            <p>{{ comparisonDisplayedEmptyMessage() }}</p>
          </div>
          <div v-else class="comparison-list">
            <!-- 比較アイテム -->
            <div 
              v-for="item in displayedComparisonData" 
              :key="item.external_code"
              class="comparison-item"
              :data-external-code="item.external_code"
              :class="getComparisonItemClass(item)"
              draggable="false"
              @dragend="handleComparisonDragEnd"
              @click="handleComparisonItemClick(item, $event)"
            >
              <!-- 上段: コード　説明 -->
              <div
                class="comp-row-top"
                :class="{
                  'comp-row-top--reserved-code': isReservedNumericCode(item.external_code),
                  'comp-row-top--selected': comparisonPanelSelectedKey === String(item.external_code || '')
                }"
                draggable="true"
                @dragstart="handleComparisonDragStart($event, item)"
              >
                <button type="button" class="comp-move-btn" @click.stop="handleComparisonItemMoveButtonTap(item, $event)">Move</button>
                <span class="comp-code" :title="item.external_code">{{ item.external_code }}</span>
                <span class="comp-desc">
                  {{ getComparisonDescription(item) }}
                </span>
              </div>
              
              <!-- 下段: 見　請　C－修正数量＋＜ -->
              <div class="comp-row-bottom" @dragstart.stop.prevent>
                <div class="comp-quantities">
                  <span class="comp-label">見</span>
                  <span class="comp-value">{{ item.aggregated_quantity ?? '--' }}</span>
                  <span class="comp-label">公</span>
                  <span class="comp-value">{{ item.billing_quantity ?? '--' }}</span>
                </div>
                <div class="comp-request-group">
                  <button
                    type="button"
                    class="comp-qty-btn billing-btn"
                    :class="{
                      'billing-btn--no-billing': comparisonBillingQuantityMissing(item) || comparisonQuantitiesMatch(item)
                    }"
                    :disabled="comparisonBillingButtonDisabled(item)"
                    @click.stop="applyBillingQuantity(item)"
                    @contextmenu.prevent
                    title="公の数量を適用"
                  >＞</button><input
                    type="text"
                    class="comp-request-input"
                    :class="{
                      'comp-request-input--is-zero': comparisonRequestQuantityIsZero(item),
                      'comp-request-input--has-qty': comparisonRequestQuantityShowRed(item),
                      'comp-request-input--matches-estimate': comparisonRequestMatchesEstimate(item),
                      'comp-request-input--matches-billing': comparisonRequestMatchesBilling(item)
                    }"
                    v-model="item.request_quantity"
                    @input="handleComparisonRequestInput(item, $event)"
                    @keydown.enter="blurComparisonInputOnEnter"
                    @click.stop
                    placeholder=""
                  /><button
                    type="button"
                    class="comp-qty-btn estimate-btn"
                    :class="{
                      'estimate-btn--no-estimate': item.aggregated_quantity === null,
                      'estimate-btn--zero': comparisonEstimateQuantityIsZero(item),
                      'comp-qty-btn--match-locked': comparisonQuantitiesMatch(item)
                    }"
                    :disabled="comparisonEstimateButtonDisabled(item)"
                    @click.stop="handleComparisonEstimateTap(item)"
                    @contextmenu.prevent
                    :title="comparisonEstimateQuantityIsZero(item) ? '修正数量に0を入力' : '見積数量を適用'"
                  >{{ comparisonEstimateButtonLabel(item) }}</button><button
                    class="comp-qty-btn"
                    :class="{ 'comp-qty-btn--match-resolved': comparisonQuantitiesMatch(item) }"
                    @click.stop="handleComparisonPlusTap(item)"
                    @contextmenu.prevent
                    @mousedown.stop="startComparisonPlusLongPress(item)"
                    @mouseup.stop="cancelComparisonPlusLongPress"
                    @mouseleave.stop="cancelComparisonPlusLongPress"
                    @touchstart.passive="startComparisonPlusLongPress(item)"
                    @touchend.passive="cancelComparisonPlusLongPress"
                    @touchcancel.passive="cancelComparisonPlusLongPress"
                    title="数量を増やす。長押しで数量クリア"
                  >＋</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

      <!-- グリッド部分 -->
      <div
        class="grid-wrapper"
        :class="{ 'estimate-grid-wrapper--mobile-tabs': mobileLikePhotoMode && showPhotoWorkTab }"
      >
        <div class="grid-header">
          <div class="grid-header-left">
            <button 
              @click="handleToolbarSave" 
              :disabled="
                !hasUnsavedChangesForToolbar ||
                isSaving ||
                comparisonSaving ||
                isExporting ||
                (mobileLikePhotoMode && gridViewTab === 'originalGrid')
              "
              class="save-button"
              :class="{ 'has-changes': hasUnsavedChangesForToolbar && !(isSaving || comparisonSaving), 'is-saving': isSaving || comparisonSaving }"
              :aria-busy="isSaving || comparisonSaving"
              :title="(isSaving || comparisonSaving) ? '保存中' : toolbarSaveButtonTitle"
            >
              <span v-if="isSaving || comparisonSaving" class="save-button-spinner" aria-hidden="true"></span>
              <svg
                v-else-if="gridViewTab === 'originalGrid'"
                xmlns="http://www.w3.org/2000/svg"
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <path d="M15 21H6a3 3 0 0 1-3-3v-1h10v2a2 2 0 0 0 4 0V5a2 2 0 1 1 2 2h-2M17 3H6a3 3 0 0 0-3 3v11" />
                <path d="M9 7h4" />
                <path d="M9 11h4" />
              </svg>
              <svg v-else xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
                <polyline points="17 21 17 13 7 13 7 21"></polyline>
                <polyline points="7 3 7 8 15 8"></polyline>
              </svg>
            </button>
            <button 
              @click="handleUndo" 
              :disabled="!canUndoForCurrentTab || isSaving || comparisonSaving"
              class="undo-button"
              :title="undoButtonTitle"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M3 7v6h6"></path>
                <path d="M21 17a9 9 0 0 0-9-9 9 9 0 0 0-6 2.3L3 13"></path>
              </svg>
            </button>
            <button 
              @click="openRoomLabelModal" 
              :disabled="!props.workId"
              class="room-label-button"
              :class="{ 'no-labels': !hasPersistedRoomLabels }"
              title="ルームラベル編集"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path>
                <polyline points="9 22 9 12 15 12 15 22"></polyline>
              </svg>
            </button>
            <button 
              @click="handleToggleAll" 
              :disabled="toggleAllButtonDisabled"
              class="toggle-all-button"
              :title="toggleAllButtonTitle"
            >
              <span v-if="toggleAllButtonShowExpandedIcon">▼</span>
              <span v-else>▶</span>
            </button>
            <button
              v-if="showClockTemplateToggle"
              type="button"
              class="clock-template-toggle"
              :class="{ active: isTemporaryTemplatePreview }"
              @click="handleTemporaryTemplateViewToggle"
              :disabled="
                (!mobileLikePhotoMode && gridViewTab !== 'originalGrid') ||
                !props.workId ||
                isSaving ||
                comparisonSaving ||
                isLoading
              "
              :title="
                isTemporaryTemplatePreview
                  ? '一時テンプレート表示中（クリックで通常テンプレートに戻す）'
                  : '通常テンプレート表示中（クリックで一時テンプレートを表示）'
              "
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <circle cx="12" cy="12" r="10" />
                <polyline points="12 6 12 12 16 14" />
              </svg>
            </button>
            <button
              class="excel-export-button"
              @click="handlePdfExport"
              :disabled="!props.workId || isExporting || isSaving || comparisonSaving"
              :title="isExporting ? 'PDF出力中' : 'PDF出力'"
            >
              <svg v-if="!isExporting" xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
                <polyline points="14 2 14 8 20 8"></polyline>
                <line x1="16" y1="13" x2="8" y2="13"></line>
                <line x1="16" y1="17" x2="8" y2="17"></line>
              </svg>
              <span v-else class="spinner-small"></span>
            </button>
            <button
              v-if="!isMobile && props.workKind === 'large'"
              type="button"
              class="schedule-calendar-btn schedule-calendar-btn--grid-header"
              :class="{ 'schedule-calendar-btn--no-data': !workLargeScheduleHasData }"
              title="進捗状況"
              :disabled="!props.workId || isSaving || comparisonSaving || isLoading"
              @click="openWorkLargeScheduleModal"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
                <rect x="3" y="4" width="18" height="18" rx="2" ry="2" />
                <line x1="16" y1="2" x2="16" y2="6" />
                <line x1="8" y1="2" x2="8" y2="6" />
                <line x1="3" y1="10" x2="21" y2="10" />
              </svg>
            </button>
            <h2
              v-if="!isTabletOriginalPricePanelMode && !(isMobile && (gridViewTab === 'originalGrid' || gridViewTab === 'instructionMerged'))"
            >{{ getWorkTitle() || '見積グリッド編集' }}</h2>
          </div>
          <div v-if="props.workId" class="grid-header-right">
            <button
              v-if="!isMobile && gridViewTab === 'originalGrid'"
              type="button"
              class="master-template-reset-button"
              @click="handleApplyMasterTemplateFromProfileOne"
              :disabled="gridViewTab !== 'originalGrid' || !props.workId || isSaving || comparisonSaving || isLoading"
              title="user_profile_id=1 の見積テンプレ（時計表示の通常/一時に合わせる）で原本グリッドを上書き（原本タブでのみ有効）"
            >
              α
            </button>
            <button
              v-if="showComparisonClipboardHeaderButton"
              type="button"
              class="comparison-filter-toggle-btn comparison-copy-btn comparison-copy-header-btn"
              title="変更差分をクリップボードにコピー"
              aria-label="変更差分をクリップボードにコピー"
              :disabled="!comparisonHasClipboardDiff || comparisonSaving || comparisonLoading"
              @click="copyComparisonChangesToClipboard"
            >
              <ComparisonClipboardCopyIcon />
            </button>
            <button
              v-if="showPhotoWorkTab && !mobileLikePhotoMode && !isTablet && gridViewTab === 'photo'"
              type="button"
              class="pw-feature-from-header"
              :class="{ 'pw-feature-from-header--busy': photoFeatureGenerateLoading }"
              :disabled="
                !props.workId ||
                photoHeaderFeatureGenerateDisabled ||
                photoFeatureGenerateLoading ||
                isSaving ||
                comparisonSaving
              "
              :title="
                photoFeatureGenerateLoading && photoFeatureGenerateProgress.total > 0
                  ? formatFeatureGenerateProgressMessage(
                      photoFeatureGenerateProgress.current,
                      photoFeatureGenerateProgress.total
                    )
                  : photoHeaderFeatureGenerateDisabled
                    ? '特徴値未登録の画像がないか、一覧読込中です'
                    : '特徴値未生成の画像を一括生成'
              "
              @click="handleHeaderFeatureGenerate"
            >
              <span v-if="photoFeatureGenerateLoading" class="spinner-small" aria-hidden="true"></span>
              <template v-if="photoFeatureGenerateLoading && photoFeatureGenerateProgress.total > 0">
                生成中 ({{ photoFeatureGenerateProgress.current }}/{{ photoFeatureGenerateProgress.total }})
              </template>
              <template v-else-if="photoFeatureGenerateLoading">生成中</template>
              <template v-else>特徴値生成</template>
            </button>
            <div
              v-if="showPhotoWorkTab && gridViewTab === 'originalGrid'"
              class="original-grid-header-tools"
              @click.stop
            >
              <button
                v-if="isTablet"
