function syncPhotoSubViewMode(panel) {
  if (gridViewTab.value !== 'photo') return
  if (!mobileLikePhotoMode.value && !isTablet.value) return
  if (panel === 'input') {
    photoWorkPanelRef.value?.setMobilePhotoViewMode?.('input')
    mobilePhotoSubViewMode.value = 'input'
  } else if (panel === 'similar') {
    photoWorkPanelRef.value?.setMobilePhotoViewMode?.('similar')
    mobilePhotoSubViewMode.value = 'similar'
  } else if (panel === 'photo') {
    photoWorkPanelRef.value?.setMobilePhotoViewMode?.('photo')
    mobilePhotoSubViewMode.value = 'photo'
  }
}

function setMobileEstimateNav(panel) {
  if (panel === 'similar') photoThumbsExpandActive.value = false
  mobileEstimatePanel.value = panel
  if (!mobileLikePhotoMode.value) return
  if (panel === 'original') gridViewTab.value = 'originalGrid'
  else if (panel === 'instruction') gridViewTab.value = 'instructionMerged'
  else gridViewTab.value = 'photo'
  nextTick(() => {
    syncPhotoSubViewMode(panel)
  })
}

function setTabletEstimateNav(panel) {
  if (!isTablet.value) {
    setMobileEstimateNav(panel)
    return
  }
  if (panel === 'original') {
    gridViewTab.value = 'originalGrid'
    mobileEstimatePanel.value = 'photo'
    return
  }
  if (panel === 'instruction') {
    gridViewTab.value = 'instructionMerged'
    mobileEstimatePanel.value = 'photo'
    return
  }
  if (panel === 'list') {
    goPhotoListView()
    mobileEstimatePanel.value = 'photo'
    return
  }
  if (panel === 'photo') {
    goPhotoNormalView()
    mobileEstimatePanel.value = 'photo'
    nextTick(() => {
      syncPhotoSubViewMode('photo')
    })
    return
  }
  gridViewTab.value = 'photo'
  mobileEstimatePanel.value = panel
  nextTick(() => {
    syncPhotoSubViewMode(panel)
  })
}

