function moveMobileTab(delta) {
  const ix = activeMobilePanelIndex.value
  if (ix < 0) return
  const next = ix + delta
  if (next < 0 || next >= MOBILE_PANELS.length) return
  setMobileEstimateNav(MOBILE_PANELS[next])
}

