  if (tab === 'originalGrid') {
    nextTick(() => {
      const container = gridContainer.value
      if (!container) return
      const top = Number(tabScrollTopByView.originalGrid) || 0
      container.scrollTop = top
      scrollTop.value = top
      updateSelectionOverlay()
