// モバイルで「編集して良い列」(0-based)
const mobileEditableCols = [2, 3, 4, 5, 8]

function getPrevEditableCol(col) {
  if (!isMobile.value) return Math.max(0, col - 1)
  const sorted = mobileEditableCols
  const idx = sorted.indexOf(col)
  if (idx > 0) return sorted[idx - 1]
  // 不正な列（念のため）なら、左側に最も近い許可列へ
  const candidates = sorted.filter(c => c < col)
  return candidates.length ? candidates[candidates.length - 1] : sorted[0]
}

function getNextEditableCol(col) {
  if (!isMobile.value) return Math.min(columnCount - 1, col + 1)
  const sorted = mobileEditableCols
  const idx = sorted.indexOf(col)
  if (idx >= 0 && idx < sorted.length - 1) return sorted[idx + 1]
  const candidates = sorted.filter(c => c > col)
  return candidates.length ? candidates[0] : sorted[sorted.length - 1]
}

function getEditableColsInRange(minCol, maxCol) {
  if (!isMobile.value) {
    return Array.from({ length: maxCol - minCol + 1 }, (_, i) => minCol + i)
  }
  return mobileEditableCols.filter(c => c >= minCol && c <= maxCol)
}

// =========================
// 画面幅に応じたレイアウトスケール（固定幅の比率を維持したまま縮小）
// =========================
/** 左パネル幅（PC・タブレット共通。layout-scale の対象外で固定） */
const LEFT_PANEL_WIDTH = 350
/** index-tab と同じローカル scale（.index-tabs の --layout-scale: 0.9 と同期） */
const INDEX_TAB_LAYOUT_SCALE = 0.9
const INDEX_TAB_TABLET_WIDTH_FACTOR = 1.8
const ROW_HEADER_BASE_WIDTH = 40

const rootEl = ref(null)
const leftPanelRef = ref(null)
const layoutScale = ref(1)
const mobileToolbarLeft = ref(0)
let leftPanelResizeObserver = null

const rootStyle = computed(() => ({
  // CSSカスタムプロパティは文字列で渡す
  '--layout-scale': String(layoutScale.value),
  '--mobile-toolbar-left': `${mobileToolbarLeft.value}px`,
  '--left-panel-width': `${LEFT_PANEL_WIDTH}px`,
}))

function updateMobileToolbarLeft() {
  if (!isDesktop.value) {
    mobileToolbarLeft.value = 0
    return
  }
  const leftWidth = leftPanelRef.value?.getBoundingClientRect?.().width
  mobileToolbarLeft.value = Number.isFinite(leftWidth) ? leftWidth : 0
}

function getEstimateGridContentInnerWidth() {
  const gc = gridContainer.value
  if (!gc) return null
  try {
    const st = window.getComputedStyle(gc)
    const pl = parseFloat(st.paddingLeft) || 0
    const pr = parseFloat(st.paddingRight) || 0
    let w = gc.clientWidth - pl - pr
    // タブレット右端チップ列（grid-wrapper padding-right と同期）
    if (isTablet.value && showPhotoWorkTab.value) {
      w -= (7.35 * 16) / 2
    }
    return w > 0 ? w : null
  } catch {
    return null
  }
}

function updateLayoutScale() {
  const el = rootEl.value
  // NOTE: このコンポーネントは flex 子要素。縮小時は縮むが、flex-grow=0 だと拡大時に幅が増えず
  //       スケールが戻らないことがある。親コンテナ幅を優先して使う。
  let available = el?.parentElement?.clientWidth || el?.clientWidth || window.innerWidth
  const hasLeftPanel = showLeftPanel.value

  // 左パネルは 350px 固定（scale 対象外）。残り幅でグリッド列のみスケールする
  if (hasLeftPanel) {
    available -= LEFT_PANEL_WIDTH
    if (isTablet.value && showPhotoWorkTab.value) {
      available -= (7.35 * 16) / 2
    }
  } else if (isTablet.value) {
    // タブレット原本（左パネルなし）: 横スクロール抑制のためグリッド内側幅でスケール
    const inner = getEstimateGridContentInnerWidth()
    if (inner != null) available = inner
  }

  // デザイン上の固定幅（CSSで固定されているグリッド列の合計）
  const rowHeaderWidth = isMobile.value
    ? ROW_HEADER_BASE_WIDTH * INDEX_TAB_LAYOUT_SCALE
    : ROW_HEADER_BASE_WIDTH * INDEX_TAB_TABLET_WIDTH_FACTOR * INDEX_TAB_LAYOUT_SCALE
  // 付箋タブはオーバーレイ（PC・タブレット共通でレイアウト幅に含めない）
  const indexTabs = 0
  const col67 = 67
  const col67TabletNarrow = col67 * 9 / 10
  const colQtyTablet = 217 * 9 / 10
  const table = isTablet.value
    ? (
        isTabletOriginalPricePanelMode.value
          ? rowHeaderWidth + col67TabletNarrow + col67TabletNarrow * 2 + 180 + 200 * 0.9 + 500 + colQtyTablet
          : rowHeaderWidth + col67TabletNarrow * 2 + col67TabletNarrow * 2 + 100 + 200 + 500 + col67TabletNarrow * 2 + colQtyTablet + col67TabletNarrow
      )
    : rowHeaderWidth + (67 * 7 + 100 + 200 + 550 + 100)
  // タブレットは付箋をオーバーレイのため indexTabs を含めない
  const baseTotal = indexTabs + table

  // 少し余白を残す
  const padding = 16
  const next = Math.min(1, Math.max(0.4, (available - padding) / baseTotal))
  layoutScale.value = Number.isFinite(next) ? next : 1
  updateMobileToolbarLeft()
}

