function parseComparisonQuantity(value) {
  if (value === null || value === undefined || value === '') return null
  if (typeof value === 'number') return Number.isFinite(value) ? value : null
  const trimmed = String(value).trim()
  if (trimmed === '') return null
  const parsed = parseFloat(trimmed)
  return Number.isFinite(parsed) ? parsed : null
}

function comparisonQuantitiesEqual(a, b) {
  const left = parseComparisonQuantity(a)
  const right = parseComparisonQuantity(b)
  if (left === null || right === null) return false
  return left === right
}

/** 見=公、または公=修正数量（変更不要） */
function comparisonItemIsResolvedMatch(item) {
  if (comparisonQuantitiesEqual(item?.aggregated_quantity, item?.billing_quantity)) return true
  const rq = item?.request_quantity
  if (rq !== null && rq !== undefined && String(rq).trim() !== '') {
    if (comparisonQuantitiesEqual(item?.billing_quantity, rq)) return true
  }
  return false
}

function shouldClearComparisonRequestQuantity(item) {
  const rq = item?.request_quantity
  if (rq === null || rq === undefined || rq === '') return true
  // 見=公のときのみ修正数量欄を空にする（公=修正は入力値を残してグレー表示）
  return comparisonQuantitiesEqual(item?.aggregated_quantity, item?.billing_quantity)
}

function comparisonItemMatchesSearch(item, query) {
  const q = String(query || '').trim().toLowerCase()
  if (!q) return true
  const parts = [
    item?.external_code,
    item?.billing_description,
    item?.estimate_instruction,
    getComparisonDescription(item)
  ]
  return parts.some((p) => String(p ?? '').toLowerCase().includes(q))
}

function comparisonListAfterHideMatchedFilter(list) {
  if (!comparisonHideMatchedFilter.value) return list
  return list.filter((item) => {
    if (comparisonQuantitiesEqual(item.aggregated_quantity, item.billing_quantity)) return false
    if (comparisonQuantitiesEqual(item.billing_quantity, item.request_quantity)) return false
    return true
  })
}

