async function copyComparisonChangesToClipboard() {
  if (!comparisonHasClipboardDiff.value) return
  try {
    const cached = await indexedDBService.getBillingItems(props.workId)
    const billingItems = Array.isArray(cached?.items) ? cached.items : []
    const text = buildComparisonChangeClipboardText({
      comparisonData: comparisonData.value,
      billingItems,
      priceListItems: priceListItems.value,
      resolveCompDesc: getComparisonDescription
    })
    await navigator.clipboard.writeText(text)
    await dialog.alert('以下の内容をクリップボードにコピーしました', {
      title: '成功',
      bodyKind: 'preformattedText',
      preview: { text }
    })
  } catch (err) {
    console.error('比較差分のコピーに失敗しました:', err)
    await dialog.alert('クリップボードへのコピーに失敗しました: ' + err.message, { title: 'エラー' })
  }
}

