// UNDO履歴管理（最大30件）
const undoHistory = ref([])
const MAX_UNDO_HISTORY = 30

// UNDO実行中フラグ（UNDO中は履歴を追加しない）
let isUndoing = false
let isInitializing = false     // 初期化中（データ読み込み中）
let skipUndoHistory = false    // 汎用的な無効化フラグ

// バッチUNDO用（複数変更を1つのUNDOにまとめる）
let isBatchMode = false                    // バッチモード中
let batchChanges = []                      // バッチ中の変更を記録
let batchDescription = ''        

// UNDO履歴を記録すべきか判定
function shouldRecordUndoHistory() {
  return !isUndoing && !isInitializing && !skipUndoHistory && !isBatchMode
}

// バッチUNDO開始
function startBatchUndo(description = 'バッチ処理') {
  isBatchMode = true
  batchChanges = []
  batchDescription = description
}

// バッチUNDO終了（まとめて1つのUNDO履歴として保存）
function endBatchUndo() {
  if (!isBatchMode) return
  
  isBatchMode = false
  
  // 変更があった場合のみUNDO履歴に追加
  if (batchChanges.length > 0) {
    addToUndoHistory('batch_edit', {
      description: batchDescription,
      changes: [...batchChanges]
    })
  }
  
  batchChanges = []
  batchDescription = ''
}

// バッチモード中の変更を記録
function recordBatchChange(type, data) {
  if (isBatchMode) {
    batchChanges.push({ type, data })
  }
}

