// 単価コードから説明を取得するマップ（高速化）
const priceCodeToDescriptionMap = computed(() => {
  const map = new Map()
  
  // rowToSlotMapを逆引き用に整理（slotId -> row）
  const slotIdToRowMap = new Map()
  for (const [row, slotId] of Object.entries(rowToSlotMap.value)) {
    const rowNum = parseInt(row)
    // MOD12=1の行のみをマッピング
    if (getRowMod12(rowNum) === 1) {
      slotIdToRowMap.set(slotId, rowNum)
    }
  }
  
  // 各スロットを処理
  for (const slot of estimateSlots.value) {
    const slotBaseRow = slotIdToRowMap.get(slot.id)
    if (slotBaseRow === undefined) continue
    
    // MOD12=1の行の4列目（単価コード）、5列目、6列目を取得
    const mod1PriceCode = getCellValue(slotBaseRow, 3) // 4列目: price_code
    const mod1Col5 = getCellValue(slotBaseRow, 4) // 5列目: contractor_id（説明には使わない）
    const mod1Col6 = getCellValue(slotBaseRow, 5) // 6列目: instruction
    
    if (mod1PriceCode) {
      // MOD12=1の単価コードの場合：MOD12=1の6列目のみ
      map.set(mod1PriceCode, {
        mod1Col6,
        itemCol5: null,
        itemCol6: null
      })
    }
    
    // アイテム行を処理
    if (slot.items && slot.items.length > 0) {
      for (const slotItem of slot.items) {
        const itemSortOrder = slotItem.sort_order || 0
        const mod12Map = {
          0: 3, 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9, 7: 10, 8: 11, 9: 0
        }
        const targetMod = mod12Map[itemSortOrder]
        const itemRow = targetMod === 0 ? slotBaseRow + 11 : slotBaseRow + targetMod - 1
        
        // アイテム行の4列目（単価コード）、5列目、6列目を取得
        const itemPriceCode = getCellValue(itemRow, 3) // 4列目: price_code
        const itemCol5 = getCellValue(itemRow, 4) // 5列目: location_category
        const itemCol6 = getCellValue(itemRow, 5) // 6列目: instruction
        
        if (itemPriceCode) {
          // アイテム行の単価コードの場合：MOD12=1の5列目 + アイテム行の5列目 + アイテム行の6列目
          map.set(itemPriceCode, {
            mod1Col6: null,
            itemCol5,
            itemCol6
          })
        }
      }
    }
  }
  
  return map
})

