        // 付箋タブ表示文字：is_index の依頼先ラベルの先頭1文字（無ければ数字）
        // contractor_id は MOD12=1 の5列目（0-indexed: 4）に入っている
        const rawContractorLabel = getContractorLabel(row, 4) || ''
        const trimmedLabel = String(rawContractorLabel).replace(/^[\s\u3000]+/, '') // 半角/全角スペース除去
        const firstChar = trimmedLabel ? Array.from(trimmedLabel)[0] : ''
        const displayNumber = firstChar || String(slotNumber)

        slots.push({
          row,
          slotId,
          sortOrder,
          slotNumber,
          displayNumber
        })
      }
    }
  }
  // sort_orderでソート後、表示番号を再計算
  const sorted = slots.sort((a, b) => a.sortOrder - b.sortOrder)
  return sorted
})

