// スロット（12行）単位のベース行（0-indexed）
// rowCount=6000想定 → 500スロット
const slotBaseRows = Array.from({ length: Math.ceil(rowCount / 12) }, (_, i) => i * 12)
function normalizeOriginalGridSearchText(value) {
  let text = String(value ?? '').trim()
  if (typeof text.normalize === 'function') {
    text = text.normalize('NFKC')
  }
  return text.toLowerCase()
}

const normalizedOriginalGridSearchQuery = computed(() => normalizeOriginalGridSearchText(originalGridSearchQuery.value))

function analyzeOriginalGridSearchHit(baseRow0, query) {
  if (!query) {
    return { matches: true, itemHit: false }
  }
  const headerContent = normalizeOriginalGridSearchText(getCellValue(baseRow0, 5))
  if (headerContent.includes(query)) {
    return { matches: true, itemHit: false }
  }
  for (let offset = 2; offset < 12; offset++) {
    const row = baseRow0 + offset
    if (row >= rowCount) break
    const itemContent = normalizeOriginalGridSearchText(getCellValue(row, 5))
    if (itemContent.includes(query)) {
      return { matches: true, itemHit: true }
    }
  }
  return { matches: false, itemHit: false }
}

const originalGridSearchHitByBaseRow = computed(() => {
  const query = normalizedOriginalGridSearchQuery.value
  const hitMap = new Map()
  for (const baseRow0 of slotBaseRows) {
    if (baseRow0 >= rowCount) break
    hitMap.set(baseRow0, analyzeOriginalGridSearchHit(baseRow0, query))
  }
  return hitMap
})

// 表示する行のリスト（折りたたみとマルチボタンを考慮）
const visibleRows = computed(() => {
  // 6000行を毎回舐めない：12行ブロック（スロット）単位で構築する
  const rows = []
  const query = normalizedOriginalGridSearchQuery.value
  const hitMap = originalGridSearchHitByBaseRow.value

  for (const baseRow0 of slotBaseRows) {
    if (baseRow0 >= rowCount) break

    // MOD12=1（常に表示） ※template側は1-basedなので +1
    const row1 = baseRow0 + 1
    // 9列目フィルターが有効な場合、9列目がnullでない行のみ表示
    if (isQuantityFilterActive.value) {
      const quantityValue = getCellValue(baseRow0, 8) // 9列目（0-indexed: 8）
      if (!quantityValue || quantityValue === '' || quantityValue === null) {
        continue // このスロットをスキップ
      }
    }
    const hit = hitMap.get(baseRow0) || { matches: !query, itemHit: false }
    if (!hit.matches) {
      continue
    }
    rows.push(row1)

    // MOD12=1の▼（=展開中）のときだけ MOD12=2 を表示
    const isExpanded = hit.itemHit ? true : !collapsedRows.value.has(baseRow0)
    if (!isExpanded) continue

    // MOD12=2
    if (baseRow0 + 1 < rowCount) {
      rows.push(baseRow0 + 2)
    }

    // MOD12=2 の3列目（0-indexed:2）がONなら、MOD12=3～11,0 を表示
    const isMultiOn = getCheckboxValue(baseRow0 + 1, 2) // MOD12=2（0-indexed）
    if (!isMultiOn) continue

    for (let offset = 2; offset < 12; offset++) {
      const r0 = baseRow0 + offset
      if (r0 >= rowCount) break
      rows.push(r0 + 1) // 1-based
    }
  }

  return rows
})

// =========================
// 仮想スクロール
// =========================
const DEFAULT_ROW_HEIGHT = 32
const rowHeight = ref(DEFAULT_ROW_HEIGHT) // 行の高さ（px）
const scrollTop = ref(0) // スクロール位置
const containerHeight = ref(0) // コンテナの高さ

function updateGridRowHeight() {
  // 仮想スクロールは CSS の固定行高（.cell height:32px）前提。実測で 33～40px になると
  // scrollTop 境界（スロット35付近など）でパディングと実高がずれ、上下にかたかたちらつく。
  rowHeight.value = DEFAULT_ROW_HEIGHT
}

// 表示範囲を計算（2ページ分 = コンテナの高さ × 2）
const virtualVisibleRows = computed(() => {
  if (!containerHeight.value) return visibleRows.value

  const overscan = Math.ceil(containerHeight.value / rowHeight.value) // 1ページ分
  const startIndex = Math.max(0, Math.floor(scrollTop.value / rowHeight.value) - overscan)
  const endIndex = Math.min(
    visibleRows.value.length,
    Math.ceil((scrollTop.value + containerHeight.value) / rowHeight.value) + overscan
  )

  return visibleRows.value.slice(startIndex, endIndex)
})

// スクロール位置の上パディング
const topPadding = computed(() => {
  if (!containerHeight.value) return 0
  const startIndex = Math.max(0, Math.floor(scrollTop.value / rowHeight.value) - Math.ceil(containerHeight.value / rowHeight.value))
  return startIndex * rowHeight.value
})

// スクロール位置の下パディング
const bottomPadding = computed(() => {
  if (!containerHeight.value) return 0
  const overscan = Math.ceil(containerHeight.value / rowHeight.value)
  const endIndex = Math.min(
    visibleRows.value.length,
    Math.ceil((scrollTop.value + containerHeight.value) / rowHeight.value) + overscan
  )
  const remainingRows = visibleRows.value.length - endIndex
  return remainingRows * rowHeight.value
})

// スクロールイベントハンドラー
let scrollRafId = null
function handleScroll(event) {
  scrollTop.value = event.target.scrollTop
  
  // スクロール時に選択範囲オーバーレイを更新（スロットリング）
  if (scrollRafId) {
    cancelAnimationFrame(scrollRafId)
  }
  scrollRafId = requestAnimationFrame(() => {
    updateSelectionOverlay()
    scrollRafId = null
  })
}

// コンテナサイズの更新
function updateContainerSize() {
  if (gridContainer.value) {
    containerHeight.value = gridContainer.value.clientHeight
    updateGridRowHeight()
  }
}

function detachGridContainerObservers(container = gridContainer.value) {
  if (!container) return
  container.removeEventListener('scroll', handleScroll)
  if (container._resizeObserver) {
    container._resizeObserver.disconnect()
    container._resizeObserver = null
  }
}

function attachGridContainerObservers() {
  const container = gridContainer.value
  if (!container) return

  // タブ切替で同一コンポーネント内のDOMが再生成されるため、毎回再接続
  detachGridContainerObservers(container)
  updateContainerSize()
  // 仮想スクロールの計算基準を、実DOMの現在位置に即時同期
  scrollTop.value = container.scrollTop || 0

  container.addEventListener('scroll', handleScroll)

  // モバイルでは描画が遅れる場合があるため、少し遅延させて再度サイズ取得
  setTimeout(() => {
    if (gridViewTab.value === 'originalGrid') {
      updateContainerSize()
    }
  }, 100)

  const resizeObserver = new ResizeObserver(() => {
    updateContainerSize()
  })
  resizeObserver.observe(container)
  container._resizeObserver = resizeObserver
}

// セルの値を取得
function getCellValue(row, col) {
  const key = `${row},${col}`
  return cellData.value[key] || ''
}

// セルの値を設定
function setCellValue(row, col, value) {
  const oldValue = getCellValue(row, col)
  const slotId = rowToSlotMap.value[row]
  
  // 値が変わる場合のみ記録
  if (oldValue !== value && slotId) {
    if (isBatchMode) {
      // バッチモード中は一時保存
      recordBatchChange('cell_edit', {
        slotId,
        row,
        col,
        oldValue,
        newValue: value
      })
    } else if (shouldRecordUndoHistory()) {
      // 通常モードではそのままUNDO履歴に追加
      addToUndoHistory('cell_edit', {
        slotId,
        row,
        col,
        oldValue,
        newValue: value
      })
    }
  }
  
  const key = `${row},${col}`
  if (value === '') {
    delete cellData.value[key]
  } else {
    cellData.value[key] = value
  }
}
// セルの値を設定してダーティフラグを立てる
function setCellValueWithDirty(row, col, value) {
  const oldValue = getCellValue(row, col)
  
  if (oldValue === value) return

  setCellValue(row, col, value)
  markSlotAsDirty(row)
  
  // アイテムの数量（MOD12=0, 3～11の9列目）が変更された場合
  const mod = getRowMod12(row)
  if (col === 8 && (mod === 0 || (mod >= 3 && mod <= 11))) {
    // 対応するMOD12=1の行を計算
    let baseRow
    if (mod === 0) {
      baseRow = row - 11
    } else {
      baseRow = row - mod + 1
    }
    
    if (slotAggregatesItemQuantities(baseRow)) {
      updateSlotQuantityFromSum(baseRow)
    }
  }
}

// 行が属するスロットをダーティとしてマーク
function markSlotAsDirty(row) {
  // MOD12=1の行番号を取得（12行ブロックの先頭）
  const mod = getRowMod12(row)
  let baseRow
  if (mod === 0) {
    baseRow = row - 11
  } else {
    baseRow = row - mod + 1
  }
  
  const slotId = rowToSlotMap.value[baseRow]
  
  // 新規スロットかどうかをチェック（new_で始まるか、newSlotsに含まれているか）
  const isNewSlot = !slotId || slotId.startsWith('new_') || newSlots.value.has(baseRow)
  
  if (isNewSlot) {
    // 新規スロット: newSlots に追加（baseRowで管理）
    newSlots.value.add(baseRow)
    
    // rowToSlotMapに新規スロットIDを設定（折りたたみ管理用）
    if (!slotId) {
      const newSlotId = `new_${baseRow}`
      for (let i = 0; i < 12; i++) {
        rowToSlotMap.value[baseRow + i] = newSlotId
      }
    }
  } else {
    // 既存スロット: dirtySlots に追加
    dirtySlots.value.add(slotId)
  }
}
// UNDO履歴に変更を追加（同一スロット・同一列の連続編集は統合）
function addToUndoHistory(type, data) {
  const entry = {
    type, // 'cell_edit', 'checkbox_edit', 'row_insert', 'row_delete_toggle'
    data,
    timestamp: Date.now()
  }
  
  // 同一スロット・同一列の最新変更があれば統合
  if (type === 'cell_edit' || type === 'checkbox_edit') {
    const lastEntry = undoHistory.value[undoHistory.value.length - 1]
    
    if (lastEntry && 
        lastEntry.type === type && 
        lastEntry.data.slotId === data.slotId && 
        lastEntry.data.row === data.row &&      
        lastEntry.data.col === data.col) {
      // 統合: oldValueは最初のまま、newValueのみ更新
      lastEntry.data.newValue = data.newValue
      lastEntry.timestamp = Date.now()
      saveDirtyState()
      return
    }
  }
  
  // 新規追加
  undoHistory.value.push(entry)
  
  // 最大件数を超えたら最も古いものを削除
  if (undoHistory.value.length > MAX_UNDO_HISTORY) {
    undoHistory.value.shift()
  }
  
  saveDirtyState()
}

// チェックボックスの値を取得
function getCheckboxValue(row, col) {
  const key = `${row},${col}`
  return checkboxData.value[key] || false
