}

// チェックボックスの値を設定してダーティフラグを立てる
function setCheckboxValueWithDirty(row, col, value) {
  const oldValue = getCheckboxValue(row, col)
  // 値が変わらない場合はスキップ
  if (oldValue === value) return
  
  setCheckboxValue(row, col, value)
  
  const mod = getRowMod12(row)
  
  // MOD12=1の2列目（0-indexed: 1）は行選択用なのでダーティ管理しない
  if (mod === 1 && col === 1) {
    return
  }
  
  markSlotAsDirty(row)
}

// セルの表示値を取得（計算値を含む）
// MOD12=2の6列目にプライスリストの説明を表示するか
function shouldShowPriceDescription(row, col) {
  return getRowMod12(row) === 2 && col === 5 // 6列目（0-indexed: 5）
}

// プライスリストの説明を取得
function getPriceDescription(row, col) {
  // MOD12=1の4列目（0-indexed: 3）からプライスコードを取得
  const mod = getRowMod12(row)
  let baseRow
  if (mod === 0) {
    baseRow = row - 11
  } else {
    baseRow = row - mod + 1
  }
  
  const priceCode = getCellValue(baseRow, 3)
  
  if (!priceCode || !selectedPriceListId.value) {
    return ''
  }
  
  // プライスリストアイテムから該当するアイテムを検索
  const item = priceListItems.value.find(item => item.external_code === priceCode)
  
  if (!item) {
    return ''
  }
  
  // ディスクリプション / アディショナルディスクリプション の形式で返す
  const description = item.description || ''
  const additionalDescription = item.additional_description || item.note || ''
  
  if (description && additionalDescription) {
    return `${description} / ${additionalDescription}`
  } else if (description) {
    return description
  } else if (additionalDescription) {
    return additionalDescription
  }
  
  return ''
}

function getDisplayValue(row, col) {
  const mod = getRowMod12(row)
  
  // MOD12=3の2列目（0-indexed: 1）: ソートオーダーを表示
  if (mod === 3 && col === 1) {
    const baseRow = row - 2 // MOD12=1の行
    const sortOrder = sortOrders.value[baseRow]
    return sortOrder ? sortOrder.toString() : ''
  }
  
  // 9列目（0-indexed: 8）の特別な処理
  if (col === 8) {
    // MOD12=1の9列目: is_item なら明細の合計を表示
    if (mod === 1) {
      if (slotAggregatesItemQuantities(row)) {
        let sum = 0
        for (let offset = 2; offset <= 11; offset++) {
          const targetRow = row + offset
          const value = parseFloat(getCellValue(targetRow, 8)) || 0
          sum += value
        }
        return sum === 0 ? '' : sum.toString()
      }
    }
  }
  
  // 通常の値を返す
  return getCellValue(row, col)
}

// 行番号のMOD12を取得 (0-indexed row → 1-indexed → MOD12)
function getRowMod12(row) {
  return (row + 1) % 12
}

// 列ラベルを取得
function getColumnLabel(col) {
  const labels = {
    1: ' ',
    2: ' ',
    3: ' ',
    4: 'コード',
    5: '業者/場所',
    6: '内容',
    7: ' ',
    8: ' ',
    9: '数量',
    10: ' ',
    11: ' '
  }
  return labels[col] || col
}

// Workタイトルを取得
function getWorkTitle() {
  const work = workData.value || currentWork.value
  if (!work) {
    return ''
  }

  const parts = []

  // kind（日本語に変換）
  // NOTE: 表示上「あき家-」が不要なので large はプレフィックスを付けない
  if (work.kind && work.kind !== 'large') {
    const kindMap = {
      'small': '小口'
    }
    parts.push(kindMap[work.kind] || work.kind)
  }

  // housing_details.name
  if (work.housing_details?.name) {
    parts.push(work.housing_details.name)
  }

  // housing_details.building
  if (work.housing_details?.building) {
    parts.push(work.housing_details.building)
  }

  // room
  if (work.room) {
    parts.push(work.room)
  }

  const title = parts.length > 0 ? parts.join('-') : ''
  return title
}

