  isQuantityFilterActive.value = !isQuantityFilterActive.value
}

// 折りたたまれているかどうか
function isCollapsed(row) {
  const query = normalizedOriginalGridSearchQuery.value
  if (query) {
    const hit = originalGridSearchHitByBaseRow.value.get(row)
    if (hit?.itemHit) return false
  }
  return collapsedRows.value.has(row)
}

// ドラッグハンドルを表示すべきか (MOD12=1, 列1)
function shouldShowDragHandle(row, col) {
  return getRowMod12(row) === 1 && col === 0
}

// コピーボタンを表示するか（MOD12=2, 1列目）
function shouldShowCopyButton(row, col) {
  return getRowMod12(row) === 2 && col === 0
}

// 新規スロットかどうか（スロットIDがない）
function isNewSlot(row) {
  const mod = getRowMod12(row)
  let baseRow
  if (mod === 0) {
    baseRow = row - 11
  } else {
    baseRow = row - mod + 1
  }
  
  return !rowToSlotMap.value[baseRow]
}

// is_indexがオンのスロットかどうか (MOD12=2, 列2)
function isIndexSlot(row) {
  const mod = getRowMod12(row)
  let baseRow
  if (mod === 0) {
    baseRow = row - 11
  } else {
    baseRow = row - mod + 1
  }
  
  // MOD12=2の2列目のチェックボックス値を取得
  const isIndexRow = baseRow + 1
  const isIndexValue = getCheckboxValue(isIndexRow, 1) // 列2は col=1
  
  return isIndexValue === true
}

/** 明細行の数量を親数量に集計するか（旧・合計トグル相当 → is_item） */
function slotAggregatesItemQuantities(baseRow) {
  return isItemSlot(baseRow)
}

/** 原本タブ: is_item ON かつ親行にコードがある MOD12=1 行を薄い黄色で強調 */
function shouldHighlightItemParentRow(row) {
  if (gridViewTab.value !== 'originalGrid') return false
  if (getRowMod12(row) !== 1) return false
  if (isDeletedRow(row)) return false
  if (!slotAggregatesItemQuantities(row)) return false
  return String(getCellValue(row, 3) || '').trim() !== ''
}

function isEstimateGridPriceCodeRow(row) {
  const mod = getRowMod12(row)
  return mod === 1 || mod === 0 || (mod >= 3 && mod <= 11)
}

/** 原本タブ: 単価コード（親行・アイテム行）がグリッド内で2回以上出現する正規化コード */
const duplicatePriceNormCodeSet = computed(() => {
  void cellData.value
  void deletedSlots.value
  void rowToSlotMap.value
  const counts = new Map()
  for (let row = 0; row < rowCount; row++) {
    if (!isEstimateGridPriceCodeRow(row)) continue
    if (isDeletedRow(row)) continue
    const nk = normalizeExternalCode(getCellValue(row, 3))
    if (!nk) continue
    counts.set(nk, (counts.get(nk) || 0) + 1)
  }
  const dup = new Set()
  for (const [nk, c] of counts) {
    if (c > 1) dup.add(nk)
  }
  return dup
})

/** 原本タブ: 同一単価コードが複数ある行をオレンジで強調 */
function shouldHighlightDuplicateCodeRow(row) {
  if (gridViewTab.value !== 'originalGrid') return false
  if (!isEstimateGridPriceCodeRow(row)) return false
  if (isDeletedRow(row)) return false
  const nk = normalizeExternalCode(getCellValue(row, 3))
  if (!nk) return false
  return duplicatePriceNormCodeSet.value.has(nk)
}

// is_itemがtrueのスロットかどうか (MOD12=2, 列3)
function isItemSlot(row) {
  const mod = getRowMod12(row)
  let baseRow
  if (mod === 0) {
    baseRow = row - 11
  } else {
    baseRow = row - mod + 1
  }
  
  // MOD12=2の3列目のチェックボックス値を取得
  const isItemRow = baseRow + 1
  const isItemValue = getCheckboxValue(isItemRow, 2) // 列3は col=2
  
  return isItemValue === true
}

// 削除対象の行かどうか
function isDeletedRow(row) {
  const mod = getRowMod12(row)
  let baseRow
  if (mod === 0) {
    baseRow = row - 11
  } else {
    baseRow = row - mod + 1
  }
  
  const slotId = rowToSlotMap.value[baseRow]
  
  // 既存スロットの場合
  if (slotId) {
    return deletedSlots.value.has(slotId)
  }
  
  // 新規スロットの場合
  const deleteKey = `new_${baseRow}`
  return deletedSlots.value.has(deleteKey)
}

// トグルボタンを表示すべきか (MOD12=1, 列3)
function shouldShowToggleButton(row, col) {
  return getRowMod12(row) === 1 && col === 2
}

// 削除ボタンを表示すべきか (MOD12=1, 列11)
function shouldShowDeleteButton(row, col) {
  return getRowMod12(row) === 1 && col === 10
}

// チェックボックス（ボタン表示）を表示すべきか
function shouldShowCheckbox(row, col) {
  if (isMobileOriginalReadonlyMode.value) return false
  const mod = getRowMod12(row)
  
  if (mod === 1) {
    return col === 1
  } else if (mod === 2) {
    return col === 1 || col === 2
  } else if (mod === 4 || mod === 5 || mod === 6) {
    return col === 2
  }
  return false
}

// 単位・数量トグル（MOD12=1 の列6・7のみ）
function shouldShowQuantityButton(row, col) {
  if (isMobileOriginalReadonlyMode.value) return false
  const mod = getRowMod12(row)
  return mod === 1 && (col === 6 || col === 7)
}

// 数量操作ボタンをdisableにするか（合計ONでも単位・数量・合計トグルは操作可）
function isQuantityButtonDisabled() {
  return false
}

// チェックボックスボタンのラベルを取得
function getCheckboxButtonLabel(row, col) {
  const mod = getRowMod12(row)
  if (col === 1 && mod === 2) {
    return 'bookmark'
  }
  if (col === 2 && mod === 2) {
    return 'multiple'
  }
  if (col === 2 && mod === 4) {
    return 'IL'
  }
  if (col === 2 && mod === 5) {
    return 'II'
  }
  if (col === 2 && mod === 6) {
    return 'IN'
  }
  return '✓'
}

// セレクトボックスを表示すべきか (MOD12=1, 列5)
function shouldShowSelect(row, col) {
  if (isMobileOriginalReadonlyMode.value) return false
  return getRowMod12(row) === 1 && col === 4
}

/** 原本タブ: MOD12=1 の数量セル（列9 / 0-indexed 8）に「→」ボタンを出す */
function shouldShowOriginalQtyArrow(row, col) {
  if (gridViewTab.value !== 'originalGrid' || col !== 8) return false
  const mod = getRowMod12(row)
  return mod === 1 || mod === 0 || (mod >= 3 && mod <= 11)
}

/** DISABLE: コード未入力 */
function isOriginalQtyArrowDisabled(row) {
  const mod = getRowMod12(row)
  if (!(mod === 1 || mod === 0 || (mod >= 3 && mod <= 11))) return true
  const code = String(getCellValue(row, 3) || '').trim()
  return !code
}

/** 原本タブの数量列「→」: 写真タブで現在選択画像へドロップ相当で追加して移動 */
async function handleOriginalQtyArrowClick(row) {
  if (isOriginalQtyArrowDisabled(row) || !showPhotoWorkTab.value) return
  const code = String(getCellValue(row, 3) || '').trim()
  if (!code) return
  const description = ''
  gridViewTab.value = 'photo'
  if (mobileLikePhotoMode.value) mobileEstimatePanel.value = 'photo'
  await nextTick()
  await nextTick()
  photoWorkPanelRef.value?.applyExternalCodeFromPricelist?.(code, description, null)
  if (mobileLikePhotoMode.value) {
    photoWorkPanelRef.value?.activateMobileInputView?.()
  }
}

// セル結合の列数を取得
function getColspan(row, col) {
  // セル結合なし
  return 1
}

// セル結合で非表示にすべきか
function isColspanHidden(row, col) {
  // セル結合なし
  return false
}

// セルが入力不可かどうか
function isReadOnlyCell(row, col) {
  if (isMobileOriginalReadonlyMode.value) {
    return true
  }
  const mod = getRowMod12(row)
  
  // MOD12=1: 4, 6, 9列目（0-indexed: 3, 5, 8）は入力可、他は不可
  if (mod === 1) {
    if (col !== 3 && col !== 5 && col !== 8) {
      return true
    }
    if (col === 8 && slotAggregatesItemQuantities(row)) {
      return true
    }
    return false
  }
  
  // MOD12=2: 4, 8列目（0-indexed: 3, 7）は入力可、他は不可
  if (mod === 2) {
    return col !== 3 && col !== 7
  }
  
  if (mod === 0 || (mod >= 3 && mod <= 11)) {
    if (col !== 3 && col !== 4 && col !== 5 && col !== 8) {
      return true
    }
    return false
  }
  
  return false
}

// セルが編集中かどうか
function isEditing(row, col) {
  // 編集中でない場合は早期リターン（最も頻繁なケース）
  if (!editingCell.value || editingCell.value.row !== row || editingCell.value.col !== col) {
    return false
  }
  // 編集中のセルでも、入力不可セルは編集できない
  if (isReadOnlyCell(row, col)) {
    return false
  }
  return true
}

// セルが選択されているかどうか
function isSelected(row, col) {
  if (!selectionStart.value || !selectionEnd.value) {
    return selectedCell.value && selectedCell.value.row === row && selectedCell.value.col === col
  }
  
  const minRow = Math.min(selectionStart.value.row, selectionEnd.value.row)
  const maxRow = Math.max(selectionStart.value.row, selectionEnd.value.row)
  const minCol = Math.min(selectionStart.value.col, selectionEnd.value.col)
  const maxCol = Math.max(selectionStart.value.col, selectionEnd.value.col)
  
  return row >= minRow && row <= maxRow && col >= minCol && col <= maxCol
}

/** コードが純粋な数値ならその数値、そうでなければ null（帯判定用） */
function parseEstimateGridCodeBandNumber(norm) {
  if (!norm || !/^-?\d+(\.\d+)?$/.test(norm)) return null
  const n = Number(norm)
  return Number.isFinite(n) ? n : null
}

// セルのクラスを取得
function getCellClass(row, col) {
  const mod = getRowMod12(row)
  const baseRow = Math.floor(row / 12) * 12 // スロットのベース行（MOD12=1の行）
  
  // checkboxData.valueを直接参照してリアクティビティを確保
  const checkboxState = checkboxData.value
  
  // 背景色の判定
  let bgClass = null
  
  // 1. 数量（N）がオンの場合、MOD12=1の数量セルを薄い緑に（is_item 集計時は入力不可の見た目）
  if (mod === 1 && col === 8) {
    const quantityKey = `${baseRow},7`
    const isQuantityOn = checkboxState[quantityKey] || false
    if (isQuantityOn) {
      bgClass = slotAggregatesItemQuantities(baseRow) ? 'bg-green-disabled' : 'bg-green'
    }
  }
  
  // 2. 単位（U）がオンの場合、MOD12=2の単位テキスト列を薄い緑に
  if (mod === 2 && col === 7) {
    const unitKey = `${baseRow},6`
    const isUnitOn = checkboxState[unitKey] || false
    if (isUnitOn) {
      bgClass = 'bg-green'
    }
  }
  
  // 3. ILボタン（MOD12=4, 列3）がオンの場合、MOD12=3～11,0の列5を薄い緑に
  if ((mod >= 3 && mod <= 11) || mod === 0) {
    if (col === 4) { // 列5（0-indexed: 4）
      const ilButtonRow = baseRow + 3 // MOD12=4
      const ilKey = `${ilButtonRow},2`
      const isILOn = checkboxState[ilKey] || false
      if (isILOn) {
        bgClass = 'bg-green'
      }
    }
  }
  
  // 4. IIボタン（MOD12=5, 列3）がオンの場合、MOD12=3～11,0の列6を薄い緑に
  if ((mod >= 3 && mod <= 11) || mod === 0) {
    if (col === 5) { // 列6（0-indexed: 5）
      const iiButtonRow = baseRow + 4 // MOD12=5
      const iiKey = `${iiButtonRow},2`
      const isIIOn = checkboxState[iiKey] || false
      if (isIIOn) {
        bgClass = 'bg-green'
      }
    }
  }
  
  // 5. INボタン（MOD12=6, 列3）がオンの場合、MOD12=3～11,0の列9を薄い緑に
  if ((mod >= 3 && mod <= 11) || mod === 0) {
    if (col === 8) { // 列9（0-indexed: 8）
      const inButtonRow = baseRow + 5 // MOD12=6
      const inKey = `${inButtonRow},2`
      const isINOn = checkboxState[inKey] || false
      if (isINOn) {
        bgClass = 'bg-green'
      }
    }
  }

  // 6. 原本タブ: 内容列が空でない行のコード列（数値帯・プライスリスト・空白ルール）
  if (gridViewTab.value === 'originalGrid' && col === 3) {
    const contentText = String(getCellValue(row, 5) ?? '').trim()
    if (contentText !== '') {
      const codeRaw = String(getCellValue(row, 3) ?? '').trim()
      const normCode = normalizeExternalCode(codeRaw)
      const mod12 = getRowMod12(row)
      const isItemDetailRow = mod12 === 0 || (mod12 >= 3 && mod12 <= 11)
      const slotIsItem = isItemSlot(row)

      if (!normCode) {
        if (!isItemDetailRow && !slotIsItem) {
          bgClass = 'bg-code-rose'
        }
      } else {
        const n = parseEstimateGridCodeBandNumber(normCode)
        const onList = priceListNormCodeSet.value.has(normCode)
        if (n !== null) {
          // 0～500 未満＝薄い赤、500～1000＝薄い青（500 は青に含める）
          if (n >= 0 && n < 500) {
            bgClass = 'bg-code-rose'
          } else if (n >= 500 && n <= 1000) {
            bgClass = 'bg-code-sky'
          } else if ((n < 0 || n > 1000) && !onList) {
            bgClass = 'bg-code-rose'
          }
        } else if (!onList) {
          bgClass = 'bg-code-rose'
        }
      }
    }
  }

  // 7. 原本タブ: is_item ON かつ親にコードがある行（MOD12=1）を薄い黄色（他の帯色より優先度低）
  if (bgClass === null && shouldHighlightItemParentRow(row)) {
    bgClass = 'bg-item-parent-code'
  }

  // 8. 原本タブ: 同一単価コードが複数ある行をオレンジ（帯色・薄黄より優先）
  if (shouldHighlightDuplicateCodeRow(row)) {
    bgClass = 'bg-duplicate-code'
  }
  
  return {
    'cell': true,
    'editing': isEditing(row, col),
    'readonly': isReadOnlyCell(row, col),
    // MOD12=1, 0, 3～11の9列目（0-indexed: 8）は右揃え
    'align-right': (mod === 1 || mod === 0 || (mod >= 3 && mod <= 11)) && col === 8,
    // 背景色クラス
    [bgClass]: bgClass !== null
  }
}

// =========================
// 選択範囲オーバーレイ（セルごとのselected計算を廃止）
// =========================
const selectionOverlayStyle = ref({ display: 'none' })

function updateSelectionOverlay() {
  const contentEl = gridContent.value
  if (!contentEl) {
    selectionOverlayStyle.value = { display: 'none' }
    return
  }

  // 範囲選択がある場合はそれを優先。なければ単一セル選択をハイライトする
  const start = selectionStart.value || selectedCell.value
  const end = selectionEnd.value || selectedCell.value
  if (!start || !end) {
    selectionOverlayStyle.value = { display: 'none' }
    return
  }

  const startEl = contentEl.querySelector(`td.cell[data-r="${start.row}"][data-c="${start.col}"]`)
  const endEl = contentEl.querySelector(`td.cell[data-r="${end.row}"][data-c="${end.col}"]`)
  if (!startEl || !endEl) {
    selectionOverlayStyle.value = { display: 'none' }
    return
  }

  const contentRect = contentEl.getBoundingClientRect()
  const r1 = startEl.getBoundingClientRect()
  const r2 = endEl.getBoundingClientRect()

  const left = Math.min(r1.left, r2.left) - contentRect.left
  const top = Math.min(r1.top, r2.top) - contentRect.top
  const right = Math.max(r1.right, r2.right) - contentRect.left
  const bottom = Math.max(r1.bottom, r2.bottom) - contentRect.top

  selectionOverlayStyle.value = {
    display: 'block',
    left: `${left}px`,
    top: `${top}px`,
    width: `${right - left}px`,
    height: `${bottom - top}px`,
  }
}

// セルクリック（選択のみ）
function handleCellClick(row, col) {
  if (editingCell.value) {
    return
  }
  // セレクトボックスのセルはクリックしても編集モードに入らない
  if (shouldShowSelect(row, col)) {
    return
  }
  // 入力不可セルはクリックしても編集モードに入らない
  if (isReadOnlyCell(row, col)) {
    return
  }
  selectedCell.value = { row, col }
  // 単一セルクリックでも選択範囲を設定（コピー・切り取りのため）
  selectionStart.value = { row, col }
  selectionEnd.value = { row, col }

  // モバイル/タブレット原本は「タップ＝即編集」にする（セル選択→もう一回タップを不要にする）
  if (isMobile.value || isTabletOriginalDirectEditMode.value) {
    // ボタンやチェックボックスのセルは編集しない（従来挙動）
    if (shouldShowDragHandle(row, col) ||
        shouldShowToggleButton(row, col) ||
        shouldShowDeleteButton(row, col) ||
        shouldShowQuantityButton(row, col) ||
        shouldShowCheckbox(row, col)) {
      return
    }
    
    // 通常の編集モード
    startEditing(row, col)
  } else {
    // PC版: セル選択後にhiddenInputにフォーカス（IME入力とキーボードショートカット両対応）
    nextTick(() => {
      focusHiddenInput()
    })
  }
}

// セルダブルクリック（編集開始）
function handleCellDoubleClick(row, col) {
  if (editingCell.value) {
    return
  }
  // セレクトボックスのセルはダブルクリックしても編集モードに入らない
  if (shouldShowSelect(row, col)) {
    return
  }
  // 入力不可セルはダブルクリックしても編集モードに入らない
  if (isReadOnlyCell(row, col)) {
    return
  }
  // ボタンやチェックボックスのセルは編集しない
  if (shouldShowDragHandle(row, col) || 
      shouldShowToggleButton(row, col) || 
      shouldShowDeleteButton(row, col) ||
      shouldShowQuantityButton(row, col) ||
      shouldShowCheckbox(row, col)) {
    return
  }
  
  // 編集開始
  startEditing(row, col)
}

// マウスダウン（範囲選択開始）
function handleMouseDown(row, col, event) {
  // PC版のみ：右クリック・右ドラッグ時の選択挙動
  if (event && event.button === 2) {
    if (isMobile.value) {
      return // スマホは従来どおり選択を変更しない
    }
    // 選択範囲内で右クリック／右ドラッグ → そのまま（選択変更しない）
    if (selectionStart.value && selectionEnd.value && isSelected(row, col)) {
      return
    }
    // 選択範囲外で右クリック／右ドラッグ → 通常の左ドラッグと同じように選択開始
  }

  if (editingCell.value) {
    return
  }
  // セレクトボックスのセルはマウスダウンしても範囲選択を開始しない
  if (shouldShowSelect(row, col)) {
    return
  }
  // 入力不可セルはマウスダウンしても範囲選択を開始しない（ただし選択は可能）
  isSelecting.value = true
  selectionStart.value = { row, col }
  selectionEnd.value = { row, col }
  selectedCell.value = { row, col }
}

// マウスエンター（範囲選択中）
function setSelectionEndThrottled(row, col) {
  pendingSelectionEnd = { row, col }
  if (selectionRafId) return
  selectionRafId = requestAnimationFrame(() => {
    selectionRafId = 0
    if (!pendingSelectionEnd) return
    selectionEnd.value = pendingSelectionEnd
    pendingSelectionEnd = null
  })
}

function handleMouseEnter(row, col) {
  if (!isSelecting.value || !selectionStart.value) return
  // mouseenterは高頻度なので、1フレーム1回だけselectionEndを更新する
  setSelectionEndThrottled(row, col)
}

// グローバルマウスアップ（範囲選択終了） - onMountedで登録
const onDocMouseUpSelection = () => {
  isSelecting.value = false
  pendingSelectionEnd = null
  selectionPointer = null
  stopAutoScroll()
  if (selectionRafId) {
    cancelAnimationFrame(selectionRafId)
    selectionRafId = 0
  }
}

// チェックボックストグル（ボタン版）
function handleCheckboxToggle(row, col) {
  const currentValue = getCheckboxValue(row, col)
  const newValue = !currentValue
  setCheckboxValueWithDirty(row, col, newValue)
  const mod = getRowMod12(row)
  if (mod === 2 && col === 2 && newValue) {
    updateSlotQuantityFromSum(row - 1)
  }
}

// スロットのquantityをアイテムの合計から更新
function updateSlotQuantityFromSum(baseRow) {
  // 合計の自動計算中はUNDO履歴を記録しない
  skipUndoHistory = true
  
  try {
    // MOD12=0, 3～11の9列目の合計を計算
    let sum = 0
    for (let offset = 2; offset <= 11; offset++) {
      const targetRow = baseRow + offset
      const value = parseFloat(getCellValue(targetRow, 8)) || 0
      sum += value
    }
    
    // MOD12=1の9列目に合計を設定
    setCellValueWithDirty(baseRow, 8, sum === 0 ? '' : String(sum))
  } finally {
    // 必ずフラグをOFFに戻す
    skipUndoHistory = false
  }
}

/** 保存直前: is_item のスロットについて cellData を表示（getDisplayValue）と一致させる */
function recalculateAllSumQuantitiesBeforeSave() {
  for (let baseRow = 0; baseRow < rowCount; baseRow += 12) {
    if (baseRow >= rowCount) break
    if (slotAggregatesItemQuantities(baseRow)) {
      updateSlotQuantityFromSum(baseRow)
    }
  }
}

// MOD12=1 列6・7: 単位・数量トグル
function handleQuantityButtonClick(row, col, action) {
  if (action !== 'toggle') return
  const mod = getRowMod12(row)
  if (mod !== 1 || (col !== 6 && col !== 7)) return
  const wasOn = getCheckboxValue(row, col)
  setCheckboxValueWithDirty(row, col, !wasOn)
}

function getQuantityButtonLabel(row, col) {
  if (getRowMod12(row) !== 1) return ''
  if (col === 6) return '単位'
  if (col === 7) return '数量'
  return ''
}

function getQuantityButtonAction(row, col) {
  return getRowMod12(row) === 1 && (col === 6 || col === 7) ? 'toggle' : ''
}

function isQuantityButtonToggle(row, col) {
  return getRowMod12(row) === 1 && (col === 6 || col === 7)
}

function isEstimateSlotQuantityToggle(row, col) {
  return getRowMod12(row) === 1 && (col === 6 || col === 7)
}

// Contractorのラベルを取得（IDから）— 選択肢に無くてもラベル表示
function getContractorLabel(row, col) {
  const contractorId = getCellValue(row, col)
  if (!contractorId) return ''
  
  const contractor = allContractors.value.find(c => String(c.id) === String(contractorId))
  return contractor ? contractor.label : contractorId
}

function getHiddenContractorForCell(row, col) {
  if (!shouldShowSelect(row, col)) return null
  return getHiddenSelectedContractor(
    allContractors.value,
    contractorSelectionIds.value,
    getCellValue(row, col)
  )
}

// セレクトボックス変更
function handleSelectChange(event, row, col) {
  setCellValueWithDirty(row, col, event.target.value)
}

// セレクトボックスのクリック/フォーカス制御
// - セル選択状態を維持（コピー等のため）
// - blur時は不可視inputへ戻してキーボード操作/IME維持
function handleSelectClick(event, row, col, phase) {
  // 編集中セルがある場合は崩さない（select自体は編集扱いではない）
  selectedCell.value = { row, col }
  selectionStart.value = { row, col }
  selectionEnd.value = { row, col }

  // セレクトの操作が終わったら不可視inputに戻す
  if (phase === 'blur') {
    nextTick(() => {
      focusHiddenInput()
    })
  }
}

// トグルボタン押下
function handleToggle(row) {
  if (collapsedRows.value.has(row)) {
    collapsedRows.value.delete(row)
  } else {
    collapsedRows.value.add(row)
  }
}

// 全体トグル（一つでも開いていたら全て閉じる、全て閉じていたら全て開く）
function handleToggleAll() {
  if (hasAnyExpanded.value) {
    // 一つでも開いている → 全て閉じる
    for (let row = 0; row < rowCount; row += 12) {
      collapsedRows.value.add(row)
    }
  } else {
    // is_item が true のスロットだけ展開。false のスロットは折りたたみのまま
    for (let row = 0; row < rowCount; row += 12) {
      const mod2Row = row + 1
      if (getCheckboxValue(mod2Row, 2)) {
        collapsedRows.value.delete(row)
      } else {
        collapsedRows.value.add(row)
      }
    }
  }
}

function handleDelete(row) {
  const slotId = rowToSlotMap.value[row]
  const baseRow = Math.floor(row / 12) * 12
  
  if (!slotId) {
    // 新規スロットの場合
    const deleteKey = `new_${baseRow}`
    const wasDeleted = deletedSlots.value.has(deleteKey)
    
    if (wasDeleted) {
      deletedSlots.value.delete(deleteKey)
    } else {
      deletedSlots.value.add(deleteKey)
      newSlots.value.delete(baseRow)
    }
    
    // UNDO履歴に追加
    addToUndoHistory('row_delete_toggle', {
      slotId: deleteKey,
      row: baseRow,
      wasDeleted,
      isDeleted: !wasDeleted
    })
    return
  }
  
  // 既存スロットの削除状態を記録
  const wasDeleted = deletedSlots.value.has(slotId)
  
  // トグル: 削除リストに含まれているかチェック
  if (wasDeleted) {
    deletedSlots.value.delete(slotId)
  } else {
    deletedSlots.value.add(slotId)
  }
  
  // UNDO履歴に追加
  addToUndoHistory('row_delete_toggle', {
    slotId,
    row: baseRow,
    wasDeleted,
    isDeleted: !wasDeleted
  })
}

// 全削除ボタン押下: 既存スロット + 新規スロットをすべて削除扱いにする
async function handleDeleteAll(options = {}) {
  const skipConfirm = !!options.skipConfirm
  if (!skipConfirm) {
    const ok = await dialog.confirm('既存のセル／新しいセル（未保存）をすべて削除扱いにします。\nよろしいですか？', { title: '確認' })
    if (!ok) {
      return
    }
  }

  // 既存スロット（rowToSlotMapがあるもの）を削除扱い
  for (let baseRow = 0; baseRow < rowCount; baseRow += 12) {
    const slotId = rowToSlotMap.value[baseRow]
    if (slotId) {
      deletedSlots.value.add(slotId)
      // 削除が優先なので、更新対象からは外す
      dirtySlots.value.delete(slotId)
    }
  }

  // 新規スロット（newSlots）を削除扱い（save時にinsert対象から除外される）
  // handleDelete と同様に deleteKey を使う
  newSlots.value.forEach((baseRow) => {
    const deleteKey = `new_${baseRow}`
    deletedSlots.value.add(deleteKey)
  })
  // 削除が優先なので newSlots を空にする
  newSlots.value.clear()

  // 選択オーバーレイ更新
  nextTick(() => updateSelectionOverlay())
}

// 指定位置に空の行を挿入（既存の行を後ろにシフト）
function insertRowsAt(insertRow, count) {
  // 新しいデータ構造を作成
  const newCellData = {}
  const newCheckboxData = {}
  const newCollapsedRows = new Set()
  const newRowToSlotMap = {}
  const newSortOrders = {}
  
  // 挿入位置より前のデータはそのままコピー
  for (let r = 0; r < insertRow; r++) {
    for (let c = 0; c < columnCount; c++) {
      const key = `${r}-${c}`
      if (cellData.value[key] !== undefined) {
        newCellData[key] = cellData.value[key]
      }
      if (checkboxData.value[key] !== undefined) {
        newCheckboxData[key] = checkboxData.value[key]
      }
    }
    if (collapsedRows.value.has(r)) {
      newCollapsedRows.add(r)
    }
    if (rowToSlotMap.value[r]) {
      newRowToSlotMap[r] = rowToSlotMap.value[r]
    }
    if (sortOrders.value[r] !== undefined) {
      newSortOrders[r] = sortOrders.value[r]
    }
  }
  
  // 挿入位置以降のデータは count 行分後ろにシフト
  for (let r = insertRow; r < rowCount; r++) {
    const newRow = r + count
    
    for (let c = 0; c < columnCount; c++) {
      const key = `${r}-${c}`
      const newKey = `${newRow}-${c}`
      if (cellData.value[key] !== undefined) {
        newCellData[newKey] = cellData.value[key]
      }
      if (checkboxData.value[key] !== undefined) {
        newCheckboxData[newKey] = checkboxData.value[key]
      }
    }
    if (collapsedRows.value.has(r)) {
      newCollapsedRows.add(newRow)
    }
    if (rowToSlotMap.value[r]) {
      newRowToSlotMap[newRow] = rowToSlotMap.value[r]
    }
    if (sortOrders.value[r] !== undefined) {
      newSortOrders[newRow] = sortOrders.value[r]
    }
  }
  
  // データを置き換え
  cellData.value = newCellData
  checkboxData.value = newCheckboxData
  collapsedRows.value = newCollapsedRows
  rowToSlotMap.value = newRowToSlotMap
  sortOrders.value = newSortOrders
  
  // newSlots, dirtySlots, deletedSlots の行番号も更新
  const newNewSlots = new Set()
  newSlots.value.forEach(row => {
    if (row >= insertRow) {
      newNewSlots.add(row + count)
    } else {
      newNewSlots.add(row)
    }
  })
  newSlots.value = newNewSlots
  
  const newDirtySlots = new Set()
  dirtySlots.value.forEach(row => {
    if (row >= insertRow) {
      newDirtySlots.add(row + count)
    } else {
      newDirtySlots.add(row)
    }
  })
  dirtySlots.value = newDirtySlots
}

// スロットをコピー（MOD12=2の1列目のコピーボタン）
function handleCopySlot(row) {
  // MOD12=1の行（ベース行）を計算
  const baseRow = row - 1
  
  // 次のスロットの行番号
  const nextSlotRow = baseRow + 12
  
  // 現在のソートオーダーと次のソートオーダーを取得
  const currentSortOrder = sortOrders.value[baseRow] || 0
  const nextSortOrder = sortOrders.value[nextSlotRow] || (currentSortOrder + 10000)
  
  // 間隔をチェック
  const gap = nextSortOrder - currentSortOrder
  
  // 間隔が100以下の場合はリバランスが必要
  if (gap <= 100) {
    rebalanceSortOrders()
  }
  
  // リバランス後の値を再取得
  const rebalancedCurrentOrder = sortOrders.value[baseRow] || 0
  const rebalancedNextOrder = sortOrders.value[nextSlotRow] || (rebalancedCurrentOrder + 10000)
  const newSortOrder = Math.floor((rebalancedCurrentOrder + rebalancedNextOrder) / 2)
  
  // コピー元の12行のデータを先に保存
  const copiedData = []
  for (let offset = 0; offset < 12; offset++) {
    const srcRow = baseRow + offset
    const rowData = {
      cells: {},
      checkboxes: {}
    }
    
    // セルデータを保存
    for (let col = 0; col < columnCount; col++) {
      rowData.cells[col] = getCellValue(srcRow, col)
    }
    
    // チェックボックスデータを保存
    for (let col = 0; col < columnCount; col++) {
      rowData.checkboxes[col] = getCheckboxValue(srcRow, col)
    }
    
    copiedData.push(rowData)
  }
  
  // nextSlotRow以降の既存データを12行後ろにシフト（後ろから処理）
  for (let r = rowCount - 1; r >= nextSlotRow; r--) {
    const targetRow = r + 12
    if (targetRow >= rowCount) continue // 範囲外は無視
    
    // セルデータをシフト
    for (let col = 0; col < columnCount; col++) {
      const value = getCellValue(r, col)
      setCellValue(targetRow, col, value)
    }
    
    // チェックボックスデータをシフト
    for (let col = 0; col < columnCount; col++) {
      const value = getCheckboxValue(r, col)
      setCheckboxValue(targetRow, col, value)
    }
    
    // rowToSlotMapをシフト
    if (rowToSlotMap.value[r]) {
      rowToSlotMap.value[targetRow] = rowToSlotMap.value[r]
      delete rowToSlotMap.value[r]
    }
    
    // sortOrdersをシフト
    if (sortOrders.value[r] !== undefined) {
      sortOrders.value[targetRow] = sortOrders.value[r]
      delete sortOrders.value[r]
    }
    
    // collapsedRowsをシフト
    if (collapsedRows.value.has(r)) {
      collapsedRows.value.delete(r)
      collapsedRows.value.add(targetRow)
    }
  }
  
  // newSlots, dirtySlots の行番号も更新
  const newNewSlots = new Set()
  newSlots.value.forEach(row => {
    if (row >= nextSlotRow) {
      newNewSlots.add(row + 12)
    } else {
      newNewSlots.add(row)
    }
  })
  newSlots.value = newNewSlots
  
  // 挿入位置をクリア（12行分）
  for (let offset = 0; offset < 12; offset++) {
    const destRow = nextSlotRow + offset
    
    // セルをクリア
    for (let col = 0; col < columnCount; col++) {
      setCellValue(destRow, col, '')
      setCheckboxValue(destRow, col, false)
    }
  }
  
  // 保存したデータを新しい位置にコピー
  for (let offset = 0; offset < 12; offset++) {
    const destRow = nextSlotRow + offset
    const rowData = copiedData[offset]
    
    // セルデータをコピー
    for (let col = 0; col < columnCount; col++) {
      setCellValue(destRow, col, rowData.cells[col])
    }
    
    // チェックボックスデータをコピー
    for (let col = 0; col < columnCount; col++) {
      setCheckboxValue(destRow, col, rowData.checkboxes[col])
    }
  }
  
  // 新しいスロットIDを生成
  const newSlotId = `new_slot_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
  
  // rowToSlotMapに新しいスロットを登録
  rowToSlotMap.value[nextSlotRow] = newSlotId
  
  // ソートオーダーを設定
  sortOrders.value[nextSlotRow] = newSortOrder
  
  // newSlotsに追加（保存時に新規として扱う）
  newSlots.value.add(nextSlotRow)
  
  // UNDO履歴に追加
  addToUndoHistory('row_insert', {
    slotId: newSlotId,
    row: nextSlotRow,
    sortOrder: newSortOrder
  })
}

// ドラッグ開始（ドラッグハンドル）
function handleDragStart(row) {
  isDragging.value = true
  dragSourceRow.value = row
  
  // 列2のチェックボックスを確認して、ドラッグする行グループを決定
  const rowsToMove = []
  
  // 列2にチェックが入っている行を探す
  for (let r = 0; r < rowCount; r++) {
    const mod = getRowMod12(r)
    if (mod === 1 && getCheckboxValue(r, 1)) {
      // チェックが入っているMOD12=1の行とその後の11行を追加
      for (let offset = 0; offset < 12; offset++) {
        if (r + offset < rowCount) {
          rowsToMove.push(r + offset)
        }
      }
    }
  }
  
  // チェックが入っている行がない場合は、クリックした行のみ
  if (rowsToMove.length === 0) {
    for (let offset = 0; offset < 12; offset++) {
      if (row + offset < rowCount) {
        rowsToMove.push(row + offset)
      }
    }
  }
  
  draggedRows.value = rowsToMove
  
  const slotCount = rowsToMove.length / 12
  
  // マウスカーソルを変更
  document.body.style.cursor = 'grabbing'
}

// ドラッグ中の行ホバー
function handleDragOver(row) {
  if (!isDragging.value) return
  
  // 実際の行番号を取得（visibleRowsから）
  const actualRow = row
  
  // MOD12=1の行のみをドロップ先として許可
  const mod = getRowMod12(actualRow)
  if (mod === 1) {
    // hover更新も高頻度なので、1フレーム1回だけ更新する
    pendingDragTargetRow = actualRow
    if (dragHoverRafId) return
    dragHoverRafId = requestAnimationFrame(() => {
      dragHoverRafId = 0
      if (pendingDragTargetRow === null || pendingDragTargetRow === undefined) return
      dragTargetRow.value = pendingDragTargetRow
      pendingDragTargetRow = null
    })
  }
}

// ドラッグ中のマウス移動（自動スクロール用）
function handleDragMouseMove(event) {
  if (!isDragging.value && !isSelecting.value) return
  
  // 範囲選択中はマウス座標を保持（スクロール中も範囲更新するため）
  if (isSelecting.value) {
    selectionPointer = { x: event.clientX, y: event.clientY }
  }
  
  const containerEl = gridContainer.value || document.querySelector('.estimate-grid-container')
  if (!containerEl) return
  
  const rect = containerEl.getBoundingClientRect()
  const mouseY = event.clientY - rect.top

  // コンテナ外なら停止
  if (mouseY <= 0 || mouseY >= rect.height) {
    stopAutoScroll()
    return
  }
  
  // 上部スクロールゾーン
  if (mouseY < SCROLL_ZONE_HEIGHT && mouseY > 0) {
    startAutoScroll('up')
  }
  // 下部スクロールゾーン
  else if (mouseY > rect.height - SCROLL_ZONE_HEIGHT && mouseY < rect.height) {
    startAutoScroll('down')
  }
  // スクロールゾーン外
  else {
    stopAutoScroll()
  }
}

function findCellFromPoint(x, y) {
  const els = document.elementsFromPoint ? document.elementsFromPoint(x, y) : [document.elementFromPoint(x, y)]
  for (const el of els) {
    if (!el) continue
    const cell = el.closest?.('td.cell')
    if (cell) return cell
  }
  return null
}

function updateSelectionEndFromPointer() {
  if (!isSelecting.value || !selectionPointer) return
  const cell = findCellFromPoint(selectionPointer.x, selectionPointer.y)
  if (!cell) return
  const r = Number(cell.dataset.r)
  const c = Number(cell.dataset.c)
  if (!Number.isFinite(r) || !Number.isFinite(c)) return
  setSelectionEndThrottled(r, c)
}

// 自動スクロール開始
function startAutoScroll(direction) {
  const containerEl = gridContainer.value || document.querySelector('.estimate-grid-container')
  if (!containerEl) return

  autoScrollDirection.value = direction
  if (autoScrollInterval.value) return
  
  autoScrollInterval.value = setInterval(() => {
    const el = gridContainer.value || containerEl
    if (!el) return
    if (autoScrollDirection.value === 'up') {
      el.scrollTop -= SCROLL_SPEED
    } else {
      el.scrollTop += SCROLL_SPEED
    }

    // 範囲選択中は、スクロールでDOMが動くのでポインタ位置から選択終点を更新
    updateSelectionEndFromPointer()
  }, 16) // 約60fps
}

// 自動スクロール停止
function stopAutoScroll() {
  if (autoScrollInterval.value) {
    clearInterval(autoScrollInterval.value)
    autoScrollInterval.value = null
  }
  autoScrollDirection.value = null
}

// ドラッグ終了
function handleDragEnd() {
  if (!isDragging.value) return
  
  // 自動スクロールを停止
  stopAutoScroll()
  
  // ドロップ先が有効な場合、行を移動
  if (dragTargetRow.value !== null && dragSourceRow.value !== dragTargetRow.value) {
    // 移動前の状態を保存（UNDO用）
    const beforeState = {
      cellData: JSON.parse(JSON.stringify(cellData.value)),
      checkboxData: JSON.parse(JSON.stringify(checkboxData.value)),
      collapsedRows: new Set(collapsedRows.value),
      rowToSlotMap: { ...rowToSlotMap.value },
      sortOrders: { ...sortOrders.value },
      newSlots: new Set(newSlots.value),
      dirtySlots: new Set(dirtySlots.value)
    }
    
    moveRowGroups(draggedRows.value, dragTargetRow.value)
    
    // 移動後の状態を保存（UNDO用）
    const afterState = {
      cellData: JSON.parse(JSON.stringify(cellData.value)),
      checkboxData: JSON.parse(JSON.stringify(checkboxData.value)),
      collapsedRows: new Set(collapsedRows.value),
      rowToSlotMap: { ...rowToSlotMap.value },
      sortOrders: { ...sortOrders.value },
      newSlots: new Set(newSlots.value),
      dirtySlots: new Set(dirtySlots.value)
    }
    
    // UNDO履歴に追加
    addToUndoHistory('row_drag', {
      sourceRows: [...draggedRows.value],
      targetRow: dragTargetRow.value,
      sourceRow: dragSourceRow.value,
      beforeState,
      afterState
    })
    
    // ドラッグ並び替え後、全ての2列目（1列目、0-indexed）のチェックボックスを解除
    // チェックボックス解除もUNDO対象にするため、skipUndoHistoryを使用
    skipUndoHistory = true
    try {
      for (let r = 0; r < rowCount; r++) {
        const mod = getRowMod12(r)
        if (mod === 1) {
          setCheckboxValue(r, 1, false) // 2列目（0-indexed: 1）のチェックを解除
        }
      }
    } finally {
      skipUndoHistory = false
    }
  }
  
  // ドラッグ状態をリセット
  isDragging.value = false
  dragSourceRow.value = null
  dragTargetRow.value = null
  draggedRows.value = []
  document.body.style.cursor = ''
}

// 行グループを移動
function moveRowGroups(sourceRows, targetRow) {
  // ソートオーダー計算用に移動前の状態を保存
  const oldSortOrders = { ...sortOrders.value }
  
  // 新しいデータ構造を作成
  const newCellData = {}
  const newCheckboxData = {}
  const newCollapsedRows = new Set()
  const newRowToSlotMap = {}
  const newSortOrders = {}
  const newNewSlots = new Set() // 新規スロットの新しいセット
  
  // 移動元の行を除いた行リストを作成
  const remainingRows = []
  for (let r = 0; r < rowCount; r++) {
    if (!sourceRows.includes(r)) {
      remainingRows.push(r)
    }
  }
  
  // ターゲット行のスロット番号を計算（0-indexed行 → スロット番号）
  const targetSlotNum = Math.floor(targetRow / 12)
  
  // 移動方向を判定
  const isMovingDown = dragSourceRow.value < targetRow // 上から下へ移動
  
  // 新しい行順序を作成（12行ブロック単位で考える）
  const newRowOrder = []
  
  // 常にtargetスロットの「前」に挿入（罫線の位置に統一）
  // targetスロット開始位置 = targetSlotNum * 12
  const insertPosition = targetSlotNum * 12
  
  // insertPosition までの行を追加
  for (let i = 0; i < remainingRows.length && remainingRows[i] < insertPosition; i++) {
    newRowOrder.push(remainingRows[i])
  }
  
  // 移動する行を挿入
  sourceRows.forEach(row => {
    newRowOrder.push(row)
  })
  
  // 残りの行を追加
  for (let i = 0; i < remainingRows.length; i++) {
    if (remainingRows[i] >= insertPosition) {
      newRowOrder.push(remainingRows[i])
    }
  }
  
  // データを新しい位置にマッピング
  for (let newRow = 0; newRow < newRowOrder.length; newRow++) {
    const oldRow = newRowOrder[newRow]
    
    for (let col = 0; col < columnCount; col++) {
      const oldKey = `${oldRow},${col}`
      const newKey = `${newRow},${col}`
      
      if (cellData.value[oldKey]) {
        newCellData[newKey] = cellData.value[oldKey]
      }
      if (checkboxData.value[oldKey]) {
        newCheckboxData[newKey] = checkboxData.value[oldKey]
      }
    }
    
    if (collapsedRows.value.has(oldRow)) {
      newCollapsedRows.add(newRow)
    }
    
    // スロットIDとソートオーダーもマッピング
    if (rowToSlotMap.value[oldRow]) {
      newRowToSlotMap[newRow] = rowToSlotMap.value[oldRow]
    }
    if (sortOrders.value[oldRow] !== undefined) {
      newSortOrders[newRow] = sortOrders.value[oldRow]
    }
    
    // 新規スロットマーカーも移行
    if (newSlots.value.has(oldRow)) {
      newNewSlots.add(newRow)
    }
  }
  
  // データを更新
  cellData.value = newCellData
  checkboxData.value = newCheckboxData
  collapsedRows.value = newCollapsedRows
  rowToSlotMap.value = newRowToSlotMap
  sortOrders.value = newSortOrders
  newSlots.value = newNewSlots // 新規スロットマーカーを更新
  
  // ソートオーダーを再計算（移動後の新しい行番号で）
  const movedSlotBaseRows = sourceRows.filter(r => getRowMod12(r) === 1)
  const newMovedRows = []
  
  // 移動後の新しい行番号を見つける
  for (let newRow = 0; newRow < newRowOrder.length; newRow++) {
    const oldRow = newRowOrder[newRow]
    if (movedSlotBaseRows.includes(oldRow)) {
      newMovedRows.push(newRow)
    }
  }
  
  // rowToSlotMapの整合性チェック
  const slotIdCounts = {}
  for (let r = 0; r < rowCount; r++) {
    const mod = getRowMod12(r)
    if (mod === 1) {
      const slotId = rowToSlotMap.value[r]
      if (slotId) {
        slotIdCounts[slotId] = (slotIdCounts[slotId] || 0) + 1
      }
    }
  }
  const duplicates = Object.entries(slotIdCounts).filter(([_, count]) => count > 1)
  if (duplicates.length > 0) {
    console.error('❌ [DRAG] 重複したslotIdが検出されました:', duplicates)
  }
  
  recalculateSortOrders(newMovedRows, targetRow, oldSortOrders)
}

// ソートオーダーを再計算
function recalculateSortOrders(movedRows, targetRow, oldSortOrders) {
  // 移動した行のMOD12=1の行番号を取得（12行ブロック単位で処理）
  const movedSlotBaseRows = movedRows.filter(r => getRowMod12(r) === 1)

  // 移動元のソートオーダーを取得（デバッグ用）- 移動前の値を使用
  const sourceSortOrder = oldSortOrders[dragSourceRow.value]
  
  // 移動方向を判定（上から下へ or 下から上へ）
  const isMovingDown = dragSourceRow.value < targetRow // 下に移動
  
  let prevSortOrder, nextSortOrder, prevRow, nextRow
  
  // 常にtargetRowの「前」に挿入（罫線の位置に統一）
  // targetRowの一つ前の行とtargetRowの間
  prevRow = targetRow - 12 // 一つ前の12行ブロック
  nextRow = targetRow
  // 移動前のsort_orderを使用
  prevSortOrder = (prevRow >= 0) ? (oldSortOrders[prevRow] || 0) : 0
  nextSortOrder = oldSortOrders[nextRow] || 0
  
  // ソートオーダーの間隔を計算
  const gap = nextSortOrder - prevSortOrder
  const numSlots = movedSlotBaseRows.length
  const increment = Math.floor(gap / (numSlots + 1))
  
  // 新しいソートオーダーを割り当て
  movedSlotBaseRows.forEach((baseRow, index) => {
    const newSortOrder = prevSortOrder + increment * (index + 1)
    
    // 12行ブロック全体に新しいソートオーダーを設定
    for (let i = 0; i < 12; i++) {
      sortOrders.value[baseRow + i] = newSortOrder
    }
    
    const slotNum = Math.floor(baseRow / 12) + 1
    
    // スロットIDがある場合のみダーティとしてマーク
    const slotId = rowToSlotMap.value[baseRow]
    if (slotId && !slotId.startsWith('new_')) {
      dirtySlots.value.add(slotId)
    }
  })
  
  // ソートオーダーの間隔が100未満になった場合、リバランスを実行
  if (increment < 100) {
    rebalanceSortOrders()
  }
}

// ソートオーダーをリバランス（間隔を均等に再配置）
function rebalanceSortOrders() {
  skipUndoHistory = true
  try {
    // すべてのMOD12=1の行を取得してソートオーダーでソート
    const slotRows = []
    for (let row = 0; row < rowCount; row++) {
      if (getRowMod12(row) === 1) {
        const sortOrder = sortOrders.value[row] || 0
        const slotId = rowToSlotMap.value[row]
        slotRows.push({ row, sortOrder, slotId })
      }
    }
    
    // ソートオーダーでソート
    slotRows.sort((a, b) => a.sortOrder - b.sortOrder)
    
    // 新しいソートオーダーを10000刻みで割り当て
    slotRows.forEach((slot, index) => {
      const newSortOrder = (index + 1) * 10000
      
      // 12行ブロック全体に新しいソートオーダーを設定
      for (let i = 0; i < 12; i++) {
        sortOrders.value[slot.row + i] = newSortOrder
      }
      
      // スロットIDがある場合のみダーティとしてマーク（新規スロットは除外）
      if (slot.slotId) {
        dirtySlots.value.add(slot.slotId)
      }
    })
  } finally {
    // リバランス完了後はUNDO履歴記録を再開
    skipUndoHistory = false
  }
}

// グローバルマウスアップ（ドラッグ終了） - onMountedで登録
const onDocMouseUpDrag = () => {
  if (isDragging.value) {
    handleDragEnd()
  }
  pendingDragTargetRow = null
  if (dragHoverRafId) {
    cancelAnimationFrame(dragHoverRafId)
    dragHoverRafId = 0
  }
}

