// estimate_slotsをグリッドにマッピング
function mapSlotsToGrid(slots) {
  // グリッドデータをクリア
  cellData.value = {}
  checkboxData.value = {}
  rowToSlotMap.value = {}
  sortOrders.value = {}
  
  // スロットデータを保存
  estimateSlots.value = slots
  
  // ダーティフラグをクリア
  dirtySlots.value.clear()
  newSlots.value.clear()
  deletedSlots.value.clear()
  
  let currentRow = 0 // 0-indexed
  let lastSortOrder = 0 // 最後のソートオーダーを追跡
  
  slots.forEach((slot, slotIndex) => {
    // ソートオーダーを記録
    lastSortOrder = slot.sort_order || 0
    // MOD12=1の行（0-indexed: 0, 12, 24, ...）
    const baseRow = currentRow
    
    // この12行ブロックのすべての行にスロットIDとソートオーダーをマッピング
    for (let i = 0; i < 12; i++) {
      rowToSlotMap.value[baseRow + i] = slot.id
      sortOrders.value[baseRow + i] = slot.sort_order || 0
    }
    
    // MOD12=1: スロットの基本情報
    setCellValue(baseRow, 3, slot.price_code || '') // 4列目: price_code
    // 5列目: contractor_id (セレクトボックスなのでそのまま設定)
    if (slot.contractor_id) {
      setCellValue(baseRow, 4, slot.contractor_id)
    }
    setCellValue(baseRow, 5, slot.instruction || '') // 6列目: instruction
    // 9列目: quantity（0は"0"として表示）
    setCellValue(baseRow, 8, slot.quantity !== null && slot.quantity !== undefined ? String(slot.quantity) : '')
    setCheckboxValue(baseRow, 6, slot.is_unit || false)
    setCheckboxValue(baseRow, 7, slot.is_quantity || false)
    
    // MOD12=2: スロットのフラグと詳細
    const mod2Row = baseRow + 1
    setCheckboxValue(mod2Row, 1, slot.is_index || false) // 2列目: is_index（付箋）
    setCheckboxValue(mod2Row, 2, slot.is_item || false) // 3列目: is_item
    setCellValue(mod2Row, 3, slot.key || '') // 4列目: key
    setCellValue(mod2Row, 7, slot.unit || '') // 8列目: unit
    
    // MOD12=3～6: 親スロットのフラグ（items 件数に依存しない。getSlotDataFromGrid と対）
    setCheckboxValue(baseRow + 3, 2, slot.is_item_location_category || false)
    setCheckboxValue(baseRow + 4, 2, slot.is_item_instruction || false)
    setCheckboxValue(baseRow + 5, 2, slot.is_item_quantity || false)
    
    // MOD12=3～11, 0: アイテム情報
    if (slot.items && slot.items.length > 0) {
      // アイテムをsort_orderでソート
      const sortedItems = [...slot.items].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
      
      sortedItems.forEach((item, itemIndex) => {
        // MOD12=3から開始（baseRow + 2）
        const itemRow = baseRow + 2 + itemIndex
        
        // 4列目: price_code
        setCellValue(itemRow, 3, item.price_code || '')
        // 5列目: location_category
        setCellValue(itemRow, 4, item.location_category || '')
        // 6列目: instruction
        setCellValue(itemRow, 5, item.instruction || '')
        // 9列目: quantity（0は"0"として表示）
        setCellValue(itemRow, 8, item.quantity !== null && item.quantity !== undefined ? String(item.quantity) : '')
      })
    }
    
    // 次のスロットは12行後
    currentRow += 12
  })
  
  // 新規スロット用のソートオーダーを初期化（最後のソートオーダー + 10000から開始）
  let nextNewSlotSortOrder = lastSortOrder + 10000
  
  // 空の行（新規スロット候補）にソートオーダーを割り当て
  for (let row = currentRow; row < rowCount; row++) {
    const mod = getRowMod12(row)
    if (mod === 1) {
      // MOD12=1の行にのみソートオーダーを割り当て
      for (let i = 0; i < 12; i++) {
        sortOrders.value[row + i] = nextNewSlotSortOrder
      }
      nextNewSlotSortOrder += 10000
      row += 11 // 次のMOD12=1までスキップ
    }
  }
}

/**
 * IndexedDB の permanent テンプレートから estimate_slots 互換オブジェクトを生成する。
 * 行 ID は `new_${baseRow}`（baseRow=0,12,…）とし、原本グリッド表示用の一時 ID。
 */
function buildSlotObjectsFromTemplateRows(allTemplates, templateItems, workId, templateMode = 'permanent') {
  const templates = (allTemplates || [])
    .filter((t) => (t.template_mode || 'permanent') === templateMode)
    .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))

  return templates.map((template, i) => {
    const baseRow = i * 12
    const slotId = `new_${baseRow}`
    const items = (templateItems || []).filter((it) => it.estimate_slot_template_id === template.id)
    const templateSortOrder = Number(template.sort_order)
    return {
      id: slotId,
      work_id: workId,
      price_code: template.price_code || '',
      instruction: template.instruction || '',
      contractor_id: template.contractor_id || null,
      quantity: template.quantity ?? null,
      // テンプレート反映時は、グリッド上の sort_order を (10000倍 + 10000) で展開する
      sort_order: Number.isFinite(templateSortOrder) ? (templateSortOrder * 10000) + 10000 : (i + 1) * 10000,
      key: template.key || null,
      is_item: template.is_item || false,
      is_index: template.is_index || false,
      is_quantity: template.is_quantity || false,
      is_unit: template.is_unit || false,
      is_item_location_category: template.is_item_location_category || false,
      is_item_instruction: template.is_item_instruction || false,
      is_item_quantity: template.is_item_quantity || false,
      unit: template.unit || null,
      deleted_at: null,
      items: items.length
        ? [...items]
            .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
            .map((item, idx) => ({
              id: `new_item_${baseRow}_${idx}`,
              estimate_slot_id: slotId,
              price_code: item.price_code || '',
              location_category: item.location_category || '',
              instruction: item.instruction || '',
              quantity: item.quantity ?? null,
              sort_order: item.sort_order
            }))
        : []
    }
  })
}

// estimate_slotsを読み込み（IndexedDB のテンプレートのみ。estimate_slots キャッシュは使わない）
async function loadEstimateSlots(restoreBaseRow = null, forceReload = false) {
  if (!props.workId) {
    console.warn('⚠️ [loadEstimateSlots] workId is not provided')
    return
  }
  
  // 既に同じworkIdで読み込み済みで、強制再読み込みでない場合はスキップ
  if (estimateSlotsLoadedWorkId === props.workId && !forceReload) {
    return
  }
  
  // 初期表示ローディング開始
  isLoading.value = true
  // 初期化中フラグをON（UNDO履歴を記録しない）
  isInitializing = true
  
  try {
    await loadRoomLabels()

    const templateRows = await indexedDBService.templates
      .where('table_name')
      .equals('estimate_slot_templates')
      .toArray()
    const templateItems = await indexedDBService.templates
      .where('table_name')
      .equals('estimate_slot_template_items')
      .toArray()

    const templateMode = isTemporaryTemplatePreview.value ? 'temporary' : 'permanent'
    const slots = buildSlotObjectsFromTemplateRows(
      templateRows,
      templateItems,
      props.workId,
      templateMode
    )
    mapSlotsToGrid(slots)
    // テンプレ表示直後はダーティなし。IndexedDB に残った旧ダーティは破棄（復元しない）
    await clearDirtyState()

    // 全てのスロットを閉じた状態にする
    const newCollapsedRows = new Set()
    for (let row = 0; row < rowCount; row++) {
      if (getRowMod12(row) === 1) {
        newCollapsedRows.add(row)
      }
    }
    collapsedRows.value = newCollapsedRows
    // スクロール位置を復元（restoreBaseRowが指定されている場合）
    if (restoreBaseRow !== null) {
      await nextTick() // DOM更新を待つ
      if (gridContainer.value && visibleRows.value.length > 0) {
        // restoreBaseRowが表示されている行のインデックスを探す
        const targetRow1Indexed = restoreBaseRow + 1 // 1-indexed
        const visibleIndex = visibleRows.value.indexOf(targetRow1Indexed)
        if (visibleIndex >= 0) {
          // その行が表示される位置にスクロール
          const scrollPosition = visibleIndex * rowHeight.value
          gridContainer.value.scrollTop = scrollPosition
        }
      }
    }
    
    // 読み込み完了フラグを設定
    estimateSlotsLoadedWorkId = props.workId
  } catch (err) {
    console.error('❌ [loadEstimateSlots] Failed to load estimate_slots:', err)
  } finally {
    // 初期化中フラグをOFF
    isInitializing = false
    // 初期表示ローディング完了
    isLoading.value = false
  }
}

// ルームラベルを読み込み
async function loadRoomLabels() {
  if (!props.workId) return

  const labelsLookUsable = (arr) =>
    Array.isArray(arr) &&
    arr.some((r) => String(r?.label ?? '').trim().length > 0)

  try {
    let result = await supabaseService.getRoomLabelsForWork(props.workId, false)
    if (!labelsLookUsable(result?.room_labels)) {
      result = await supabaseService.getRoomLabelsForWork(props.workId, true)
    }

    if (result && result.room_labels && result.room_labels.length > 0) {
      roomLabels.value = padRoomLabelSlots(result.room_labels)
      originalRoomLabels.value = JSON.parse(JSON.stringify(result.room_labels))
      hasPersistedRoomLabels.value = labelsLookUsable(result.room_labels)
      if (!hasPersistedRoomLabels.value) {
        await loadRoomLabelTemplate()
      }
    } else {
      hasPersistedRoomLabels.value = false
      await loadRoomLabelTemplate()
    }
  } catch (err) {
    console.error('❌ [loadRoomLabels] Failed to load room labels:', err)
    hasPersistedRoomLabels.value = false
    await loadRoomLabelTemplate()
  }
}

// ルームラベルテンプレートを読み込み
async function loadRoomLabelTemplate() {
  try {
    // テンプレートを取得（company_idが必要な場合は追加）
    const template = await supabaseService.getRoomLabelTemplate()
    
    if (template && template.length > 0) {
      roomLabels.value = padRoomLabelSlots(
        template.map((t) => ({
          sort_order: t.sort_order,
          label: t.label || ''
        }))
      )
      originalRoomLabels.value = []
    } else {
      roomLabels.value = emptyRoomLabelSlots()
      originalRoomLabels.value = []
    }
  } catch (err) {
    console.error('❌ [loadRoomLabelTemplate] Failed to load template:', err)
    roomLabels.value = emptyRoomLabelSlots()
    originalRoomLabels.value = []
  }
}

// ダーティ情報をIndexedDBに保存
async function saveDirtyState() {
  if (!props.workId) return
  
  try {
    const dirtyState = {
      workId: props.workId,
      dirtySlots: Array.from(dirtySlots.value),
      newSlots: Array.from(newSlots.value),
      deletedSlots: Array.from(deletedSlots.value),
      undoHistory: undoHistory.value, // UNDO履歴を追加
      cellData: {}, // セルデータを保存
      checkboxData: {}, // チェックボックスデータを保存
      sortOrders: JSON.parse(JSON.stringify(sortOrders.value)),
      rowToSlotMap: JSON.parse(JSON.stringify(rowToSlotMap.value))
    }
    
    // グリッドデータを保存（変更があった行のみ）
    const allAffectedRows = new Set()
    
    // dirtySlots の行を収集
    dirtySlots.value.forEach(slotId => {
      for (const [row, id] of Object.entries(rowToSlotMap.value)) {
        if (id === slotId) {
          const baseRow = parseInt(row)
          for (let i = 0; i < 11; i++) {
            allAffectedRows.add(baseRow + i)
          }
        }
      }
    })
    
    // newSlots の行を収集
    newSlots.value.forEach(baseRow => {
      for (let i = 0; i < 11; i++) {
        allAffectedRows.add(baseRow + i)
      }
    })
    
    // deletedSlots の行を収集
    deletedSlots.value.forEach(slotId => {
      if (slotId.startsWith('new_')) {
        const baseRow = parseInt(slotId.replace('new_', ''))
        for (let i = 0; i < 11; i++) {
          allAffectedRows.add(baseRow + i)
        }
      } else {
        for (const [row, id] of Object.entries(rowToSlotMap.value)) {
          if (id === slotId) {
            const baseRow = parseInt(row)
            for (let i = 0; i < 11; i++) {
              allAffectedRows.add(baseRow + i)
            }
          }
        }
      }
    })
    
    // 影響を受けた行のセルデータとチェックボックスデータを保存
    allAffectedRows.forEach(row => {
      for (let col = 0; col < columnCount; col++) {
        const key = `${row},${col}`
        if (cellData.value[key] !== undefined) {
          dirtyState.cellData[key] = cellData.value[key]
        }
        if (checkboxData.value[key] !== undefined) {
          dirtyState.checkboxData[key] = checkboxData.value[key]
        }
      }
    })
    
    const stateKey = `grid_dirty_${props.workId}`
    await indexedDBService.saveAppState(stateKey, dirtyState)
  } catch (err) {
    console.error('❌ [DirtyState] Failed to save:', err)
  }
}

// ダーティ情報をクリア（保存成功時に呼ばれる）
async function clearDirtyState() {
  if (!props.workId) return
  
  undoHistory.value = []

  try {
    const stateKey = `grid_dirty_${props.workId}`
    await indexedDBService.deleteAppState(stateKey)
  } catch (err) {
    console.error('❌ [DirtyState] Failed to clear:', err)
  }
}

