// Work情報を読み込み
async function loadWorkData(options = {}) {
  const { forceDefaultPriceList = false } = options
  if (!props.workId) {
    console.warn('[EstimateGridEditor] loadWorkData: No workId')
    return
  }
  
  try {
    // IndexedDBから取得
    const work = await indexedDBService.getWorkById(props.workId)
    
    if (work) {
      workData.value = work
      currentWork.value = work
    } else {
      console.warn('[EstimateGridEditor] loadWorkData: No work data in IndexedDB')
      // フォールバック: worksテーブルから直接取得
      const workFromTable = await indexedDBService.works.get(props.workId)
      if (workFromTable) {
        workData.value = workFromTable
        currentWork.value = workFromTable
      }
    }
    
    // workのkindとcompany_idに基づいてプライスリストを絞り込み
    await loadPriceLists({ forceDefaultPick: forceDefaultPriceList })
  } catch (err) {
    console.error('[EstimateGridEditor] loadWorkData: Failed to load work data:', err)
  }
}

// プライスリスト一覧をIndexedDBから読み込み
async function loadPriceLists(options = {}) {
  const { forceDefaultPick = false } = options
  try {
    if (!currentWork.value) {
      priceLists.value = []
      selectedPriceListId.value = ''
      priceListItems.value = []
      return
    }

    // price_lists: kind / company に加え、mc_id が null（共通）または work.mc_id と一致するもののみ
    const workMcId = currentWork.value.mc_id
    const lists = (await indexedDBService.price_lists
      .where('table_name')
      .equals('price_lists')
      .and(item =>
        item.is_active === true &&
        item.kind === currentWork.value.kind &&
        item.company_id === currentWork.value.company_id
      )
      .toArray()).filter((item) => {
        const plMc = item.mc_id
        if (plMc == null || plMc === '') return true
        if (workMcId == null || workMcId === '') return false
        return String(plMc) === String(workMcId)
      })

    priceLists.value = lists
      .map((item) => ({
        id: item.id,
        label: item.label,
        fiscal_year: item.fiscal_year,
        revision_no: item.revision_no,
        kind: item.kind,
        mc_id: item.mc_id
      }))
      .sort(comparePriceListsByFiscalThenRevision)

    const idSet = new Set(priceLists.value.map((p) => String(p.id)))
    const cur = String(selectedPriceListId.value ?? '')
    const needPick = priceLists.value.length > 0 && (!cur || !idSet.has(cur))

    if (priceLists.value.length === 0) {
      selectedPriceListId.value = ''
      priceListItems.value = []
    } else if (needPick || forceDefaultPick) {
      const picked = pickDefaultPriceList(priceLists.value, currentWork.value?.ordered_on)
      selectedPriceListId.value = picked?.id ?? priceLists.value[0].id
      await loadPriceListItems()
    }
  } catch (err) {
    console.error('Failed to load price lists from IndexedDB:', err)
  }
}

