// フィルター済みアイテム
const filteredItems = computed(() => {
  let items = priceListItems.value

  // カテゴリーでフィルター
  if (selectedSmallCategory.value) {
    items = items.filter(item => item.price_small_category_id === selectedSmallCategory.value)
  } else if (selectedBigCategory.value) {
    items = items.filter(item => item.price_big_category_id === selectedBigCategory.value)
  }

  // 検索クエリでフィルター（複数条件対応：全角・半角スペース区切り）
  if (searchQuery.value) {
    // 全角・半角スペースで分割してトリム
    const keywords = searchQuery.value
      .split(/[\s　]+/)
      .map(k => k.trim().toLowerCase())
      .filter(k => k.length > 0)
    
    if (keywords.length > 0) {
      items = items.filter(item => {
        // アイテムの検索対象テキストを結合
        const searchText = [
          item.external_code || '',
          item.description || '',
          item.note || ''
        ].join(' ').toLowerCase()
        
        // すべてのキーワードが含まれているかチェック（AND条件）
        return keywords.every(keyword => searchText.includes(keyword))
      })
    }
  }

  // 単価コード（external_code）で昇順にソート
  items = items.sort((a, b) => {
    const codeA = (a.external_code || '').toString()
    const codeB = (b.external_code || '').toString()
    return codeA.localeCompare(codeB, 'ja', { numeric: true })
  })

  return items
})

