// ドロップ先セル（data-r 付き）を解決。行番号列・パディング行の td には data-r が無いため、座標から拾う。
function resolveDropTargetCell(event) {
  const direct = event.target?.closest?.('td')
  if (direct?.dataset?.r != null && direct.dataset.r !== '') {
    const r = parseInt(direct.dataset.r, 10)
    if (!Number.isNaN(r)) return direct
  }
  if (typeof document.elementsFromPoint !== 'function') return null
  for (const el of document.elementsFromPoint(event.clientX, event.clientY)) {
    if (el.tagName !== 'TD') continue
    if (el.dataset?.r == null || el.dataset.r === '') continue
    const r = parseInt(el.dataset.r, 10)
    if (!Number.isNaN(r)) return el
  }
  return null
}

// dataTransfer からドロップペイロードを復元（dragend が drop より先に走る環境向け）
function parseDropPayloadFromDataTransfer(event) {
  let raw = ''
  try {
    raw = event.dataTransfer?.getData('text/plain') || ''
  } catch {
    return { item: null, isComparisonItem: false }
  }
  if (!raw || !raw.trim()) return { item: null, isComparisonItem: false }
  try {
    const o = JSON.parse(raw)
    if (o?.type === 'comparison-item') {
      const billQ = o.billing_quantity != null ? o.billing_quantity : o.quantity
      return {
        item: {
          external_code: o.external_code,
          quantity: billQ,
          billing_quantity: billQ,
          billing_description: o.billing_description,
          estimate_instruction: o.estimate_instruction,
          unit: o.unit || ''
        },
        isComparisonItem: true
      }
    }
    if (o?.type === 'photo-similar-candidate') {
      const full = priceListItems.value.find((x) => x.external_code === o.external_code)
      return {
        item: full || {
          external_code: o.external_code,
          description: o.description || '',
          additional_description: '',
          unit: o.unit || '',
          note: ''
        },
        isComparisonItem: false
      }
    }
    if (o?.type === 'price-item') {
      const full = priceListItems.value.find((x) => x.external_code === o.external_code)
      return {
        item: full || {
          external_code: o.external_code,
          description: o.description || '',
          additional_description: o.additional_description || '',
          unit: o.unit || '',
          note: o.note || ''
        },
        isComparisonItem: false
      }
    }
  } catch {
    /* 従来: 単価コードのみの文字列 */
  }
  const code = raw.trim()
  if (!code) return { item: null, isComparisonItem: false }
  const full = priceListItems.value.find((x) => x.external_code === code)
  return {
    item: full || { external_code: code, description: '', unit: '' },
    isComparisonItem: false
  }
}

// グリッド上でのドラッグオーバー
function handleGridDragOver(event) {
  if (draggedPriceItem.value || draggingComparisonItem.value) {
    event.dataTransfer.dropEffect = 'copy'
