  }
  try {
    const dt = event.dataTransfer
    if (dt?.types?.contains?.('text/plain')) {
      dt.dropEffect = 'copy'
    }
  } catch {
    /* ignore */
  }
}

// グリッド上でのドロップ

// 付箋タブクリック時のスクロール
function handleIndexTabClick(slot, index) {
  // アクティブ表示を設定（一時的）
  activeIndexTab.value = index
  
  // 既存のタイマーをクリア
  if (activeIndexTabTimer) {
    clearTimeout(activeIndexTabTimer)
  }
  
  // 1秒後にアクティブ表示を消す
  activeIndexTabTimer = setTimeout(() => {
    activeIndexTab.value = null
  }, 1000)
  
  // スクロール後に編集しやすいよう、MOD12=1の6列目（instruction列）を選択
  const targetRow = slot.row // 0-indexed（MOD12=1の行）
  const targetCol = 5 // 6列目（0-indexed）
  selectedCell.value = { row: targetRow, col: targetCol }
  selectionStart.value = { row: targetRow, col: targetCol }
  selectionEnd.value = { row: targetRow, col: targetCol }
  
  // グリッドコンテナをスクロール（仮想スクロール対応）
  nextTick(() => {
    const container = gridContainer.value
    if (!container) return
    
    // visibleRowsの中で該当行のインデックスを探す（1-indexed）
    const targetRow1Indexed = slot.row + 1
    const visibleIndex = visibleRows.value.indexOf(targetRow1Indexed)
    
    if (visibleIndex < 0) {
      console.warn('⚠️ [IndexTabClick] Row not visible:', targetRow1Indexed)
      return
    }
    
    // 一番上の方にある場合（3行上が存在しない）はTOPに移動
    if (visibleIndex < 3) {
      container.scrollTo({
        top: 0,
        behavior: 'auto'
      })
      nextTick(() => updateSelectionOverlay())
      return
    }
    
    // まず目標位置までスクロールして、DOM要素が描画されるのを待つ
    const scrollTargetIndex = Math.max(0, visibleIndex - 3)
    const scrollTargetPosition = scrollTargetIndex * rowHeight.value
    
    container.scrollTo({
      top: scrollTargetPosition,
      behavior: 'auto'
    })

    // スクロール完了後、DOM更新を待って微調整
    // nextTick → requestAnimationFrame の順で待つことで確実にDOMが更新される
    nextTick(() => {
      requestAnimationFrame(() => {
        // さらにもう一度待つ（仮想スクロールのDOM更新を確実に待つ）
        requestAnimationFrame(() => {
          // visibleRowsから目標の3行上を探す
          const targetRow1Indexed = slot.row + 1
          const targetIndex = visibleRows.value.indexOf(targetRow1Indexed)
          
          if (targetIndex < 0) {
            // 見つからない場合はTOPに移動
            container.scrollTo({ top: 0, behavior: 'auto' })
            updateSelectionOverlay()
            return
          }
          
          // 3行上のインデックス
          const scrollTargetIdx = Math.max(0, targetIndex - 3)
          const scrollTargetRow1Indexed = visibleRows.value[scrollTargetIdx]
          
          if (!scrollTargetRow1Indexed) {
            // 見つからない場合はTOPに移動
            container.scrollTo({ top: 0, behavior: 'auto' })
            updateSelectionOverlay()
            return
          }
          
          // 3行上の行番号（0-indexed）
          const scrollTargetRow0Indexed = scrollTargetRow1Indexed - 1
          
          // DOM要素を探す
          const targetCell = container.querySelector(`td.cell[data-r="${scrollTargetRow0Indexed}"]`)
          
          if (targetCell) {
            const containerRect = container.getBoundingClientRect()
            const targetRect = targetCell.getBoundingClientRect()
            const offset = targetRect.top - containerRect.top
            
            // 現在のスクロール位置に相対的なオフセットを追加
            container.scrollTo({
              top: container.scrollTop + offset,
              behavior: 'auto'
            })
          } else {
            // 見つからない場合はTOPに移動
            container.scrollTo({
              top: 0,
              behavior: 'auto'
            })
          }
          
          updateSelectionOverlay()
        })
      })
    })
  })
}

function handleGridDrop(event) {
  let item = draggedPriceItem.value || draggingComparisonItem.value
  let isComparisonItem = !!draggingComparisonItem.value

  if (!item) {
    const parsed = parseDropPayloadFromDataTransfer(event)
    item = parsed.item
    isComparisonItem = parsed.isComparisonItem
  }
  if (!item) return

  const target = resolveDropTargetCell(event)
  if (!target) return

  const actualRow = parseInt(target.dataset.r, 10)
  if (Number.isNaN(actualRow)) return

  const mod = getRowMod12(actualRow)
  
  // MOD12=2の行にはドロップ不可
  if (mod === 2) {
    draggedPriceItem.value = null
    draggingComparisonItem.value = null
    return
  }
  
  // 1. 列4（0-indexed: 3）に単価コードを必ず設定
  setCellValue(actualRow, 3, item.external_code || '')
  
  // 2. 列6（0-indexed: 5）が空白の場合のみデスクリプションを設定
  const currentInstruction = getCellValue(actualRow, 5)
  if (!currentInstruction || currentInstruction.trim() === '') {
    // デスクリプションを取得
    let description = ''
    if (isComparisonItem) {
      description = item.billing_description || item.estimate_instruction || ''
    } else {
      description = item.description || ''
    }
    
    if (description) {
      setCellValue(actualRow, 5, description)
    }
  }
  
  // 3. ドロップ先がMOD12=1の場合、MOD12=2の列8（0-indexed: 7）にユニットを設定
  if (mod === 1) {
    const unit = item.unit || ''
    if (unit) {
      const mod2Row = actualRow + 1
      setCellValue(mod2Row, 7, unit)
    }
  }
  
  // MOD12=1の行を見つけてダーティとしてマーク
  let baseRow
  if (mod === 0) {
    baseRow = actualRow - 11
  } else {
    baseRow = actualRow - mod + 1
  }

  // 比較/プライスリストからのドロップでは数量を自動入力しない

  markSlotAsDirty(baseRow)

  draggedPriceItem.value = null
  draggingComparisonItem.value = null
}

// 価格のフォーマット
function formatPrice(price) {
  if (price === null || price === undefined) return '0'
  return price.toLocaleString()
}

// ========================================
// 比較機能
// ========================================

// 比較実行（請求アイテム＋指示タブ結合行でローカル組み立て。既存行は get のみ）
function applyComparisonBuildResult(comparisons) {
  comparisonData.value = (comparisons || []).map((item) => {
    let requestQty = item.request_quantity
    if (shouldClearComparisonRequestQuantity(item)) {
      requestQty = ''
    }

    return {
      ...item,
      request_quantity: requestQty
    }
  })
}

async function executeComparison() {
  if (!props.workId) {
    await dialog.alert('Work IDが必要です', { title: 'エラー' })
    return
  }

  const savedScrollTops = captureComparisonScrollTops()
  comparisonLoading.value = true
  // 実行のたびに一旦空にする。請求ゼロで return した場合など、前回の行が残るのを防ぐ
  comparisonData.value = []
  draggingComparisonItem.value = null
  try {
    const requestWorkId = props.workId
    const cached = await indexedDBService.getBillingItems(requestWorkId)
    if (requestWorkId !== props.workId) return

    let billing = Array.isArray(cached?.items) ? [...cached.items] : []
    billingItemNormCodes.value = buildBillingNormCodeSet(billing)
    if (!billing.length) {
      const ok = await dialog.confirm('指示書データがありませんが、\n見積算出しますか？', { title: '確認' })
      if (!ok) return
      billing = []
    }

    const existingRes = await supabaseService.getBillingComparisons(props.workId)
    const existingComparisons = existingRes?.comparisons || []

    const result = buildLocalBillingComparisonResults({
      billingItems: billing,
      instructionMergeRows: instructionMergeRows.value,
      existingComparisons
    })

    applyComparisonBuildResult(result.comparisons)
    restoreComparisonScrollTops(savedScrollTops)
  } catch (err) {
    console.error('比較実行エラー:', err)
    await dialog.alert('比較の実行に失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    comparisonLoading.value = false
  }
}

// 比較データ保存
async function saveComparison() {
  if (!props.workId || comparisonData.value.length === 0) return

  comparisonSaving.value = true
  try {
    const items = comparisonData.value
      .filter((item) => !shouldSkipComparisonCodeForSave(item.external_code))
      .map(item => {
      // request_quantityが空文字列の場合はnullに変換
      let requestQty = item.request_quantity
      
      // 空文字列、null、undefinedの場合はnullに統一
      if (requestQty === '' || requestQty === null || requestQty === undefined) {
        requestQty = null
      } else if (typeof requestQty === 'string') {
        // 文字列の場合、空白を除去してから数値に変換
        const trimmed = requestQty.trim()
        if (trimmed === '') {
          requestQty = null
        } else {
          const parsed = parseFloat(trimmed)
          requestQty = isNaN(parsed) ? null : parsed
        }
      } else if (typeof requestQty === 'number') {
        // 既に数値の場合はそのまま
        requestQty = isNaN(requestQty) ? null : requestQty
      } else {
        // その他の型はnull
        requestQty = null
      }
      
      // aggregated_quantityとbilling_quantityも同様に処理
      let aggQty = item.aggregated_quantity
      if (aggQty === '' || aggQty === undefined) aggQty = null
      else if (typeof aggQty === 'string') {
        const parsed = parseFloat(aggQty.trim())
        aggQty = isNaN(parsed) ? null : parsed
      }
      
      let billQty = item.billing_quantity
      if (billQty === '' || billQty === undefined) billQty = null
      else if (typeof billQty === 'string') {
        const parsed = parseFloat(billQty.trim())
        billQty = isNaN(parsed) ? null : parsed
      }
      
      let billSort = item.billing_sort_order
      if (billSort === '' || billSort === undefined) billSort = null
      else if (typeof billSort === 'string') {
        const parsed = parseInt(billSort.trim())
        billSort = isNaN(parsed) ? null : parsed
      }
      
      return {
        external_code: item.external_code,
        aggregated_quantity: aggQty,
        billing_quantity: billQty,
        billing_sort_order: billSort,
        request_quantity: requestQty,
        status: item.status
      }
    })
    await supabaseService.saveBillingComparisons(props.workId, items)
    for (const item of comparisonData.value) {
      if (comparisonQuantitiesEqual(item.aggregated_quantity, item.billing_quantity)) {
        item.request_quantity = ''
      }
    }
  } catch (err) {
    console.error('比較データ保存エラー:', err)
    await dialog.alert('保存に失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    comparisonSaving.value = false
  }
}

// 比較データリフレッシュ
async function refreshComparison() {
  if (!props.workId) return
  
  const ok = await dialog.confirm('比較データをリセットしますか？\n保存されていないデータは失われます。', { title: '確認' })
  if (!ok) {
    return
  }
  
  try {
    await supabaseService.refreshBillingComparisons(props.workId)
    comparisonData.value = []
    mobileComparisonModalScrollTop.value = 0
    await dialog.alert('比較データをリセットしました', { title: '成功' })
  } catch (err) {
    console.error('比較データリフレッシュエラー:', err)
    await dialog.alert('リセットに失敗しました: ' + err.message, { title: 'エラー' })
  }
}

/** 修正数量欄に数字が入っているとき（薄い赤背景用） */
function comparisonRequestQuantityHasNumber(item) {
  const v = item?.request_quantity
  if (v === null || v === undefined) return false
  return /[0-9]/.test(String(v))
}

function comparisonRequestQuantityIsZero(item) {
  return parseComparisonQuantity(item?.request_quantity) === 0
}

/** 修正数量が見積数量（見）と一致するとき（薄い青背景用） */
function comparisonRequestMatchesEstimate(item) {
  return comparisonQuantitiesEqual(item?.aggregated_quantity, item?.request_quantity)
}

/** 修正数量が公と一致し見と異なるとき（＞ボタンと同系の黄背景用。0は除く） */
function comparisonRequestMatchesBilling(item) {
  const rq = item?.request_quantity
  if (rq === null || rq === undefined || String(rq).trim() === '') return false
  if (comparisonRequestQuantityIsZero(item)) return false
  if (comparisonQuantitiesEqual(item?.aggregated_quantity, rq)) return false
  return comparisonQuantitiesEqual(item?.billing_quantity, rq)
}

/** 修正数量欄を赤くする条件（公一致・見一致以外で数字あり。0は別クラス） */
function comparisonRequestQuantityShowRed(item) {
  if (comparisonRequestQuantityIsZero(item)) return false
  if (comparisonRequestMatchesEstimate(item)) return false
  if (comparisonRequestMatchesBilling(item)) return false
  return comparisonRequestQuantityHasNumber(item)
}

function formatComparisonRequestQuantity(value) {
  const rounded = roundComparisonEstimateQuantity(value)
  if (rounded === null) return ''
  return String(rounded)
}

function parseComparisonRequestQuantityForMath(item) {
  return parseComparisonQuantity(item?.request_quantity) ?? 0
}

// 比較アイテムの修正数量入力（半角数字とドットのみ許可）
function handleComparisonRequestInput(item, event) {
  let value = event.target.value
  value = value.replace(/[^0-9.]/g, '')
  event.target.value = value
  item.request_quantity = value
}

function blurComparisonInputOnEnter(event) {
  if (!event) return
  if (event.isComposing || event.keyCode === 229) return
  const native = event.nativeEvent
  if (native?.isComposing) return
  event.preventDefault()
  const target = event.target
  if (target && typeof target.blur === 'function') target.blur()
}

let comparisonPlusLongPressTimer = null
let comparisonPlusLongPressTriggered = false
let comparisonPlusLongPressAt = 0

function startComparisonPlusLongPress(item) {
  cancelComparisonPlusLongPress()
  comparisonPlusLongPressTriggered = false
  comparisonPlusLongPressTimer = setTimeout(() => {
    comparisonPlusLongPressTriggered = true
    comparisonPlusLongPressAt = Date.now()
    clearComparisonRequest(item)
  }, 500)
}

function cancelComparisonPlusLongPress() {
  if (!comparisonPlusLongPressTimer) return
  clearTimeout(comparisonPlusLongPressTimer)
  comparisonPlusLongPressTimer = null
}

function handleComparisonPlusTap(item) {
  if (Date.now() - comparisonPlusLongPressAt < 700) return
  if (comparisonPlusLongPressTriggered) {
    comparisonPlusLongPressTriggered = false
    return
  }
  incrementComparisonRequest(item)
}

function comparisonQuantitiesMatch(item) {
  return comparisonQuantitiesEqual(item?.aggregated_quantity, item?.billing_quantity)
}

function comparisonBillingQuantityMissing(item) {
  const q = item?.billing_quantity
  return q === null || q === undefined || q === ''
}

function comparisonBillingButtonDisabled(item) {
  if (comparisonQuantitiesMatch(item)) return true
  return comparisonBillingQuantityMissing(item)
}

function comparisonEstimateButtonDisabled(item) {
  return comparisonQuantitiesMatch(item)
}

function comparisonEstimateQuantityIsZero(item) {
  const q = item?.aggregated_quantity
  if (q === null || q === undefined) return true
  const n = Number(q)
  return Number.isFinite(n) && n === 0
}

function comparisonEstimateButtonLabel(item) {
  return comparisonEstimateQuantityIsZero(item) ? '０' : '＜'
}

function handleComparisonEstimateTap(item) {
  if (comparisonEstimateButtonDisabled(item)) return
  if (comparisonEstimateQuantityIsZero(item)) {
    setComparisonRequestToZero(item)
    return
  }
  applyEstimateQuantity(item)
}

function setComparisonRequestToZero(item) {
  item.request_quantity = '0'
}

// 比較アイテムの修正数量をクリア
function clearComparisonRequest(item) {
  item.request_quantity = ''
}

// 比較アイテムの修正数量を減らす
function decrementComparisonRequest(item) {
  const next = Math.max(0, parseComparisonRequestQuantityForMath(item) - 1)
  item.request_quantity = formatComparisonRequestQuantity(next)
}

// 比較アイテムの修正数量を増やす
function incrementComparisonRequest(item) {
  const next = parseComparisonRequestQuantityForMath(item) + 1
  item.request_quantity = formatComparisonRequestQuantity(next)
}

function roundComparisonEstimateQuantity(value) {
  const n = Number(value)
  if (!Number.isFinite(n)) return null
  const abs = Math.abs(n)
  if (abs < 1) return Math.round((n + Number.EPSILON) * 100) / 100
  if (abs < 100) return Math.round((n + Number.EPSILON) * 10) / 10
  return Math.round(n)
}

// 見積数量を修正数量に適用
function applyEstimateQuantity(item) {
  if (item.aggregated_quantity !== null) {
    const rounded = roundComparisonEstimateQuantity(item.aggregated_quantity)
    if (rounded !== null) {
      item.request_quantity = rounded
    }
  }
}

// 公の数量を修正数量に適用
function applyBillingQuantity(item) {
  if (comparisonBillingButtonDisabled(item)) return
  if (item.billing_quantity !== null && item.billing_quantity !== undefined && item.billing_quantity !== '') {
    const rounded = roundComparisonEstimateQuantity(item.billing_quantity)
    if (rounded !== null) {
      item.request_quantity = rounded
    }
  }
}

/** 写真指示・比較で共通: 数値コードが 0～1000 のときの強調用 */
function isReservedNumericCode(code) {
  const s = String(code ?? '').trim()
  if (s === '') return false
  const n = Number(s)
  return Number.isFinite(n) && n >= 0 && n <= 1000
}

// 比較アイテムのクラスを取得
function getComparisonItemClass(item) {
  // 見=公、または公=修正数量（変更不要）
  if (comparisonItemIsResolvedMatch(item)) {
    return 'is-match'
  }
  
  // 数量が入っているが一致していない
  if (item.aggregated_quantity !== null && 
      item.billing_quantity !== null) {
    return 'is-mismatch'
  }
  
  // 請求側にのみ存在（新規）
  if (item.aggregated_quantity === null && item.billing_quantity !== null) {
    return 'is-new'
  }
  
  // 見積側にのみ存在（追加候補）
  if (item.aggregated_quantity !== null && item.billing_quantity === null) {
    return 'is-pending'
  }
  
  return ''
}

/** 比較 comp-desc: 選択中プライスリストの description（note ありなら description-note） */
function formatPriceListDescriptionForComparison(priceListItem) {
  if (!priceListItem) return ''
  const description = String(priceListItem.description ?? '').trim()
  const noteRaw = priceListItem.note
  const hasNote = noteRaw !== null && noteRaw !== undefined && String(noteRaw).trim() !== ''
  if (hasNote) {
    const note = String(noteRaw).trim()
    return description ? `${description}-${note}` : note
  }
  return description
}

/** billing_description / estimate_instruction が両方空のときの comp-desc フォールバック */
function getComparisonDescriptionWhenBillingEstimateEmpty(item) {
  const nk = normalizeExternalCode(item.external_code)
  const firstInstructionText = firstInstructionPlusContentByNormCode.value.get(nk)
  if (firstInstructionText) return firstInstructionText

  if (selectedPriceListId.value) {
    const plItem = priceListItems.value.find(
      (it) => normalizeExternalCode(it.external_code) === nk
    )
    const plText = formatPriceListDescriptionForComparison(plItem)
    if (plText) return plText
  }

  return '--'
}

function getComparisonDescription(item) {
  const fallbackText = item.billing_description || item.estimate_instruction || '--'
  if (!item.external_code) {
    return fallbackText
  }

  // 単価コードから説明を取得（見積グリッドのセル）
  const descData = priceCodeToDescriptionMap.value.get(item.external_code)
  if (descData) {
    const parts = []
    if (descData.mod1Col6) parts.push(descData.mod1Col6)
    if (descData.itemCol5) parts.push(descData.itemCol5)
    if (descData.itemCol6) parts.push(descData.itemCol6)
    if (parts.length > 0) return parts.join('')
  }

  if (fallbackText !== '--') return fallbackText

  return getComparisonDescriptionWhenBillingEstimateEmpty(item)
}

/** PC左パネル比較: 1回目で選択・説明全文、2回目で applyExternalCodeFromPricelist */
async function handleComparisonItemClick(item, event) {
  const target = event?.target
  if (
    target?.tagName === 'BUTTON' ||
    target?.tagName === 'INPUT' ||
    target?.classList?.contains?.('comp-drag-handle')
  ) {
    return
  }
  const key = String(item?.external_code || '').trim()
  if (!key) return
  if (comparisonPanelSelectedKey.value !== key) {
    comparisonPanelSelectedKey.value = key
    return
  }
  comparisonPanelSelectedKey.value = null
  await handleComparisonItemApplyLikeSimilar(item, event)
}

/** 比較行ダブルクリック: 履歴・類似と同様に写真入力へコード適用 */
async function handleComparisonItemApplyLikeSimilar(item, event) {
  if (event) {
    event.preventDefault()
    event.stopPropagation?.()
  }
  const target = event?.target
  if (target?.tagName === 'BUTTON' || target?.tagName === 'INPUT') return
  if (!item?.external_code) return
  const code = String(item.external_code || '').trim()
  if (!code || !showPhotoWorkTab.value) return

