}

/** 比較パネル Move ボタン: 写真タブへ移してから同一コードへ順送り移動 */
async function handleComparisonItemMoveButtonTap(item, event) {
  event?.stopPropagation?.()
  if (!item?.external_code || !showPhotoWorkTab.value) return

  if (gridViewTab.value !== 'photo') {
    gridViewTab.value = 'photo'
    await nextTick()
  }

