    else setMobileEstimateNav('input')
  }
}

/** 写真グリッドの比較移動ボタン: 左比較パネルで該当コードへスクロール */
function scrollContainerToElementCenter(container, element) {
  if (!container || !element) return
  const containerRect = container.getBoundingClientRect()
  const elementRect = element.getBoundingClientRect()
  const delta =
    elementRect.top + elementRect.height / 2 - (containerRect.top + containerRect.height / 2)
  const maxScrollTop = Math.max(0, container.scrollHeight - container.clientHeight)
  container.scrollTop = Math.max(0, Math.min(container.scrollTop + delta, maxScrollTop))
}

async function scrollComparisonPanelToExternalCode(externalCode) {
  const code = String(externalCode ?? '').trim()
  if (!code || !isDesktop.value) return false

  leftPanelMode.value = 'comparison'
  await nextTick()

  const root = comparisonContentScrollRef.value
  if (!root) return false

  const esc = typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(code) : code.replace(/"/g, '\\"')
  const nodes = Array.from(root.querySelectorAll(`.comparison-item[data-external-code="${esc}"]`))
  if (!nodes.length) return false

  scrollContainerToElementCenter(root, nodes[0])
  comparisonPanelSelectedKey.value = code
  return true
}

