  }))
}

// 比較アイテムのドラッグ終了
function handleComparisonDragEnd() {
  draggingComparisonItem.value = null
}

/** get（crud_billing_comparison）の comparisons を比較タブ表示用に整形（保存後の再読込と共用） */
function mapComparisonsFromGetApi(comparisons) {
  if (!comparisons || !comparisons.length) return []
  return comparisons.map((item) => {
    const isMatch = comparisonQuantitiesEqual(item.aggregated_quantity, item.billing_quantity)

    let requestQty = item.request_quantity
    if (shouldClearComparisonRequestQuantity(item)) {
      requestQty = ''
    }

    return {
      ...item,
      request_quantity: requestQty,
      is_match: isMatch,
      slots: []
    }
  })
}

