  }
}

// 保存処理
// グリッドデータからスロットデータを抽出
function getSlotDataFromGrid(baseRow) {
  // MOD12=1の行データ
  const priceCode = getCellValue(baseRow, 3) // 4列目: price_code
  const contractorId = getCellValue(baseRow, 4) // 5列目
  const instruction = getCellValue(baseRow, 5) // 6列目
  const quantity = getCellValue(baseRow, 8) // 9列目
  
  // MOD12=2の行データ
  const mod2Row = baseRow + 1
  const isIndex = getCheckboxValue(mod2Row, 1) // 2列目: is_index（付箋）
  const isItem = getCheckboxValue(mod2Row, 2) // 3列目
  const key = getCellValue(mod2Row, 3) // 4列目: key
  const isUnit = getCheckboxValue(baseRow, 6)
  const unit = getCellValue(mod2Row, 7) // 8列目
  const isQuantity = getCheckboxValue(baseRow, 7)
  
  const isItemLocationCategory = getCheckboxValue(baseRow + 3, 2) // MOD12=4
  const isItemInstruction = getCheckboxValue(baseRow + 4, 2) // MOD12=5
  const isItemQuantity = getCheckboxValue(baseRow + 5, 2) // MOD12=6
  
  // 数量を数値に変換（空文字列はnull、"0"は0として保持）
  let quantityValue = null
  if (quantity !== '' && quantity !== null && quantity !== undefined) {
    const parsed = parseFloat(quantity)
    quantityValue = isNaN(parsed) ? null : parsed
  }
  
  return {
    key: key || null,
    contractor_id: contractorId || null,
    instruction: instruction || null,
    quantity: quantityValue,
    price_code: priceCode || null,
    unit: unit || null,
    sort_order: sortOrders.value[baseRow] || 0,
    is_index: isIndex || false,
    is_item: isItem || false,
    is_unit: isUnit || false,
    is_quantity: isQuantity || false,
    is_item_location_category: isItemLocationCategory || false,
    is_item_instruction: isItemInstruction || false,
    is_item_quantity: isItemQuantity || false,
  }
}

// グリッドデータからアイテムデータを抽出（0～9の10行）
function getItemsDataFromGrid(baseRow) {
  const items = []
  
  // MOD12=3～11, 0 の10行分（sort_order 0～9）
  for (let i = 0; i < 10; i++) {
    const itemRow = baseRow + 2 + i // MOD12=3から開始
    const sortOrder = i
    
    const priceCode = getCellValue(itemRow, 3) // 4列目
    const locationCategory = getCellValue(itemRow, 4) // 5列目
    const instruction = getCellValue(itemRow, 5) // 6列目
    const quantity = getCellValue(itemRow, 8) // 9列目
    
    // 既存アイテムのIDを取得（estimateSlotsから）
    const slotId = rowToSlotMap.value[baseRow]
    let itemId = null
    
    if (slotId) {
      const slot = estimateSlots.value.find(s => s.id === slotId)
      if (slot && slot.items && slot.items[i]) {
        itemId = slot.items[i].id
      }
    }
    
    // 数量を数値に変換（空文字列はnull、"0"は0として保持）
    let quantityValue = null
    if (quantity !== '' && quantity !== null && quantity !== undefined) {
      const parsed = parseFloat(quantity)
      quantityValue = isNaN(parsed) ? null : parsed
    }
    
    items.push({
      id: itemId || undefined,
      price_code: priceCode || null,
      location_category: locationCategory || null,
      instruction: instruction || null,
      quantity: quantityValue,
      sort_order: sortOrder,
    })
  }
  
  return items
}

function hasMeaningfulEstimateItem(item) {
  if (!item) return false
  return (
    String(item.price_code || '').trim() !== '' ||
    String(item.location_category || '').trim() !== '' ||
    String(item.instruction || '').trim() !== '' ||
    item.quantity !== null
  )
}

function hasMeaningfulEstimateSlot(slotData, items = []) {
  if (!slotData) return false
  if (String(slotData.price_code || '').trim() !== '') return true
  if (String(slotData.contractor_id || '').trim() !== '') return true
  if (String(slotData.instruction || '').trim() !== '') return true
  if (slotData.quantity !== null) return true
  if (String(slotData.key || '').trim() !== '') return true
  if (String(slotData.unit || '').trim() !== '') return true
  if (
    slotData.is_index ||
    slotData.is_item ||
    slotData.is_unit ||
    slotData.is_quantity ||
    slotData.is_item_location_category ||
    slotData.is_item_instruction ||
    slotData.is_item_quantity
  ) return true
  return items.some(hasMeaningfulEstimateItem)
}

function collectOrderedBaseRowsFromGrid() {
  const seen = new Set()
  const candidates = []
  for (let r = 0; r < rowCount; r++) {
    if (getRowMod12(r) !== 1) continue
    const sid = rowToSlotMap.value[r]
    if (!sid || seen.has(sid)) continue
    seen.add(sid)
    candidates.push({ r, so: sortOrders.value[r] || 0 })
  }
  candidates.sort((a, b) => a.so - b.so)
  return candidates.map((c) => c.r)
}

/** テンプレート保存 API 用: 原本グリッド現在値 → JSON 配列 */
function buildSlotsPayloadForTemplateSave() {
  recalculateAllSumQuantitiesBeforeSave()
  const baseRows = collectOrderedBaseRowsFromGrid()
  const slots = []
  let idx = 0
  for (const br of baseRows) {
    // 削除トグル済みスロットはテンプレート保存対象から除外
    if (isDeletedRow(br)) continue
    const d = getSlotDataFromGrid(br)
    const rawItems = d.is_item ? getItemsDataFromGrid(br) : []
    const items = rawItems.filter(hasMeaningfulEstimateItem)
    slots.push({
      sort_order: idx++,
      price_code: d.price_code,
      instruction: d.instruction,
      contractor_id: d.contractor_id,
      quantity: d.quantity,
      key: d.key,
      is_item: !!d.is_item,
      is_index: !!d.is_index,
      is_quantity: !!d.is_quantity,
      is_unit: !!d.is_unit,
      is_item_location_category: !!d.is_item_location_category,
      is_item_instruction: !!d.is_item_instruction,
      is_item_quantity: !!d.is_item_quantity,
      unit: d.unit,
      items: items.map((it) => ({
        sort_order: it.sort_order,
        price_code: it.price_code,
        location_category: it.location_category,
        instruction: it.instruction,
        quantity: it.quantity
      }))
    })
  }
  return slots
}

async function reloadOriginalGridFromIndexedDbTemplate(templateMode, options = {}) {
  const { restoreBaseRow = null } = options
  if (!props.workId) return
  isLoading.value = true
  isInitializing = true
  try {
    const templateRows = await indexedDBService.templates
      .where('table_name')
      .equals('estimate_slot_templates')
      .toArray()
    const templateItems = await indexedDBService.templates
      .where('table_name')
      .equals('estimate_slot_template_items')
      .toArray()
    const slots = buildSlotObjectsFromTemplateRows(
      templateRows,
      templateItems,
      props.workId,
      templateMode
    )
    mapSlotsToGrid(slots)
    await clearDirtyState()
    const newCollapsedRows = new Set()
    for (let row = 0; row < rowCount; row++) {
      if (getRowMod12(row) === 1) {
        newCollapsedRows.add(row)
      }
    }
    collapsedRows.value = newCollapsedRows
    if (restoreBaseRow !== null && restoreBaseRow !== undefined) {
      await nextTick()
      if (gridContainer.value && visibleRows.value.length > 0) {
        const targetRow1Indexed = restoreBaseRow + 1
        const visibleIndex = visibleRows.value.indexOf(targetRow1Indexed)
        if (visibleIndex >= 0) {
          gridContainer.value.scrollTop = visibleIndex * rowHeight.value
        }
      }
    }
  } finally {
    isInitializing = false
    isLoading.value = false
  }
}

async function handleTemporaryTemplateViewToggle() {
  if (!props.workId) return
  const next = !isTemporaryTemplatePreview.value
  const mode = next ? 'temporary' : 'permanent'
  const templateRows = await indexedDBService.templates
    .where('table_name')
    .equals('estimate_slot_templates')
    .toArray()
  const count = templateRows.filter((t) => (t.template_mode || 'permanent') === mode).length
  if (count === 0) {
    await dialog.alert(
      next
        ? '一時テンプレートがありません。保存モーダルの「一時」で登録できます。'
        : '通常テンプレートがありません。',
      { title: '中断' }
    )
    return
  }
  if (hasGridSlotDirty.value) {
    const ok = await dialog.confirm('原本グリッドの未保存の変更は破棄されます。続行しますか？', { title: '確認' })
    if (!ok) {
      return
    }
  }
  await clearOriginalGridSlotDirty()
  isTemporaryTemplatePreview.value = next
  await reloadOriginalGridFromIndexedDbTemplate(mode)
}

/** user_profile_id=1 のサーバーテンプレで原本グリッドを上書き（template_mode は時計表示に追従） */
async function handleApplyMasterTemplateFromProfileOne() {
  if (!props.workId) return
