      templateMode
    )
    mapSlotsToGrid(slots)
    // マスタ適用後は未保存として扱う（mapSlotsToGrid 内で newSlots がクリアされるためここで付与）
    newSlots.value = new Set(slots.map((_, i) => i * 12))
    await saveDirtyState()
    const newCollapsedRows = new Set()
    for (let row = 0; row < rowCount; row++) {
      if (getRowMod12(row) === 1) {
        newCollapsedRows.add(row)
      }
    }
    collapsedRows.value = newCollapsedRows
  } catch (e) {
    console.error(e)
    await dialog.alert(e?.message || 'テンプレートの取得に失敗しました', { title: 'エラー' })
  } finally {
    isInitializing = false
    isLoading.value = false
  }
}

