function toNumberOrZero(v) {
  const n = parseFloat(String(v ?? '').trim())
  return Number.isFinite(n) ? n : 0
}

function normalizeQuantityNumber(v) {
  if (!Number.isFinite(v)) return 0
  const rounded = Math.round(v * 1_000_000) / 1_000_000
  return Object.is(rounded, -0) ? 0 : rounded
}

function addQuantities(a, b) {
  return normalizeQuantityNumber(toNumberOrZero(a) + toNumberOrZero(b))
}

/** PhotoWorkLinksPanel の description 連結子と同じ（概要 / 備考） */
const PHOTO_DESC_COMBINE_SEP = ' / '

function splitPhotoWorkDescription(stored) {
  const t = String(stored ?? '').trim()
  if (!t) return { main: '', add: '' }
  const ix = t.indexOf(PHOTO_DESC_COMBINE_SEP)
  if (ix >= 0) {
    return {
      main: t.slice(0, ix).trim(),
      add: t.slice(ix + PHOTO_DESC_COMBINE_SEP.length).trim()
    }
  }
  return { main: t, add: '' }
}

function mergeInstructionContentAppend(existing, toAppend) {
  const e = String(existing ?? '').trim()
  const a = String(toAppend ?? '').trim()
  if (!a) return e
  if (!e) return a
  return `${e} ${a}`
}

function uniqueContentSnippets(snippets) {
  const seen = new Set()
  const out = []
  for (const s of snippets) {
    const t = String(s ?? '').trim()
    if (!t || seen.has(t)) continue
    seen.add(t)
    out.push(t)
  }
  return out.join(' ')
}

function formatPhotoQtyText(qty) {
  const n = toNumberOrZero(qty)
  if (!Number.isFinite(n)) return ''
  const rounded = Math.round(n * 1_000_000) / 1_000_000
  return Number.isInteger(rounded) ? String(rounded) : String(rounded)
}

function getFirstCodeRowFromTop(externalCode) {
  const code = String(externalCode || '').trim()
  if (!code) return -1
  for (let row = 0; row < rowCount; row++) {
    const mod = getRowMod12(row)
    if (mod === 2) continue
    if (String(getCellValue(row, 3) || '').trim() === code) return row
  }
  return -1
}

function getLastMappedBaseRow() {
  let maxBase = -1
  for (let row = 0; row < rowCount; row++) {
    if (getRowMod12(row) !== 1) continue
    const slotId = rowToSlotMap.value[row]
    if (!slotId) continue
    maxBase = row
  }
  return maxBase
}

