// UNDO実行
function handleUndo() {
  if (gridViewTab.value === 'photo' || gridViewTab.value === 'instructionMerged') {
    photoWorkPanelRef.value?.undoLastAction?.()
    return
  }
  if (undoHistory.value.length === 0) {
    return
  }
  
  const lastChange = undoHistory.value.pop()
  
  // UNDO実行中フラグをON
  isUndoing = true
  try {
    switch (lastChange.type) {
      case 'cell_edit':
        setCellValueWithDirty(lastChange.data.row, lastChange.data.col, lastChange.data.oldValue)
        break
        
      case 'checkbox_edit':
        setCheckboxValueWithDirty(lastChange.data.row, lastChange.data.col, lastChange.data.oldValue)
        break
        
      case 'batch_edit':
        // バッチ処理を逆順で戻す
        console.log('🔙 UNDO バッチ処理:', lastChange.data.description, `(${lastChange.data.changes.length}件)`)
        for (let i = lastChange.data.changes.length - 1; i >= 0; i--) {
          const change = lastChange.data.changes[i]
          if (change.type === 'cell_edit') {
            setCellValue(change.data.row, change.data.col, change.data.oldValue)
            markSlotAsDirty(change.data.row)
          } else if (change.type === 'checkbox_edit') {
            setCheckboxValue(change.data.row, change.data.col, change.data.oldValue)
            markSlotAsDirty(change.data.row)
          }
        }
        break
        
      case 'row_insert':
        // 行挿入を戻す（削除）
        const insertedSlotId = lastChange.data.slotId
        const insertedRow = lastChange.data.row
        
        // newSlotsから削除
        newSlots.value.delete(insertedRow)
        
        // グリッドから行データをクリア
        for (let offset = 0; offset < 12; offset++) {
          const targetRow = insertedRow + offset
          for (let col = 0; col < columnCount; col++) {
            setCellValue(targetRow, col, '')
            setCheckboxValue(targetRow, col, false)
          }
        }
        
        // rowToSlotMapから削除
        delete rowToSlotMap.value[insertedRow]
        delete sortOrders.value[insertedRow]
        break
        
      case 'row_delete_toggle':
        // 削除トグルを戻す（元の状態に戻す）
        const toggleSlotId = lastChange.data.slotId
        const wasDeleted = lastChange.data.wasDeleted
        
        if (wasDeleted) {
          // 元々削除状態だった → 削除状態に戻す
          deletedSlots.value.add(toggleSlotId)
        } else {
          // 元々削除状態ではなかった → 削除解除
          deletedSlots.value.delete(toggleSlotId)
        }
        break
        
      case 'row_drag':
        // ドラッグ移動を戻す（移動前の状態に復元）
        const beforeState = lastChange.data.beforeState
        
        // 全ての状態を復元
        cellData.value = JSON.parse(JSON.stringify(beforeState.cellData))
        checkboxData.value = JSON.parse(JSON.stringify(beforeState.checkboxData))
        collapsedRows.value = new Set(beforeState.collapsedRows)
        rowToSlotMap.value = { ...beforeState.rowToSlotMap }
        sortOrders.value = { ...beforeState.sortOrders }
        newSlots.value = new Set(beforeState.newSlots)
        dirtySlots.value = new Set(beforeState.dirtySlots)
      
        // 列2（複数選択チェックボックス）を全てfalseにする
        for (let r = 0; r < rowCount; r++) {
          const key = `${r},1`
          delete checkboxData.value[key]  // または checkboxData.value[key] = false
        }
        break
    }
  } finally {
    isUndoing = false
  }
  
  // IndexedDBに保存（saveDirtyStateを呼ばずに直接保存）
  saveDirtyState()
}

// 編集開始
function startEditing(row, col) {
  // 入力不可セルは編集できない
  if (isReadOnlyCell(row, col)) {
    return
  }
  // セレクトボックスのセルは編集できない（セレクトボックスとして動作）
  if (shouldShowSelect(row, col)) {
    return
  }
  editingCell.value = { row, col }
  
  // v-showに変更したため、即座にフォーカス可能
  nextTick(() => {
    // input要素のdata-r, data-c属性で直接検索
    const cellEl = gridContent.value?.querySelector(
      `.cell-input[data-r="${row}"][data-c="${col}"]`
    )
    if (cellEl) {
      cellEl.focus()
      // モバイル: カーソルを最後に移動
      if (isMobile.value) {
        const length = cellEl.value.length
        cellEl.setSelectionRange(length, length)
      }
    } else {
      console.warn(`⚠️ [startEditing] Cell input not found for row ${row}, col ${col}. Cell may be outside visible range.`)
    }
  })
}

// 編集終了
function finishEditing() {
  if (editingCell.value) {
    const editedRow = editingCell.value.row
    const editedCol = editingCell.value.col

    // 9列目（0-indexed: 8）の場合、ブラー/確定時に全角→半角へ正規化
    if (editedCol === 8) {
      const current = getCellValue(editedRow, editedCol)
      const normalized = normalizeQuantityInput(current)
      if (normalized !== current) {
        setCellValueWithDirty(editedRow, editedCol, normalized)
      }
    }
    
    // 編集終了時にダーティとしてマーク
    markSlotAsDirty(editedRow)
    
    // 編集状態を解除
    editingCell.value = null
    
    // セル選択状態に戻す（選択範囲も設定してコピー・切り取りを有効にする）
    selectedCell.value = { row: editedRow, col: editedCol }
    selectionStart.value = { row: editedRow, col: editedCol }
    selectionEnd.value = { row: editedRow, col: editedCol }
    
    // hiddenInputにフォーカスを戻す（IME入力とキーボードショートカットの両方に対応）
    nextTick(() => {
      focusHiddenInput()
    })
  }
}

// 9列目（数量）向け: 全角数字→半角数字、全角．/。→半角. に正規化
function normalizeQuantityInput(value) {
  if (value === null || value === undefined) return value
  let s = String(value)

  // 全角数字→半角数字（０-９ → 0-9）
  s = s.replace(/[０-９]/g, (ch) =>
    String.fromCharCode(ch.charCodeAt(0) - 0xFEE0)
  )

  // 全角のピリオド/句点→半角.
  s = s.replace(/[．。]/g, '.')

  // 最終的に半角数字と.以外は除去
  s = s.replace(/[^0-9.]/g, '')
  return s
}

// 入力イベント
function handleInput(event, row, col) {
