  setCellValueWithDirty(row, col, value)
}

// キープレスイベント（9列目の入力制限）
function handleInputKeyPress(event, row, col) {
  // 9列目（0-indexed: 8）の場合
  if (col === 8) {
    const char = event.key
    // 半角数字/./全角数字/全角．/。 以外は入力を防ぐ
    if (!/[0-9.０-９．。]/.test(char) && !event.ctrlKey && !event.metaKey) {
      event.preventDefault()
    }
  }
}

// ブラーイベント
function handleBlur() {
  // IME変換中でなければ編集終了
  if (!isComposing.value) {
    finishEditing()
  }
}

// IME変換開始
function handleCompositionStart() {
