// 入力中のキーイベント
function handleInputKeyDown(event, row, col) {
  // IME変換中はEnterを無視
  if (isComposing.value) {
    return
  }
  
  if (event.key === 'Enter') {
    event.preventDefault()
    event.stopPropagation()
    // 入力要素からフォーカスを外す前に編集終了
    finishEditing()
  } else if (event.key === 'Escape') {
    event.preventDefault()
    event.stopPropagation()
    finishEditing()
  }
}

// 次の表示可能な行を見つける（上方向）
function findPreviousVisibleRow(currentRow) {
  const visibleRowsList = visibleRows.value.map(r => r - 1) // 1-indexed → 0-indexed
  const currentIndex = visibleRowsList.indexOf(currentRow)
  if (currentIndex > 0) {
    return visibleRowsList[currentIndex - 1]
  }
  return currentRow
}

// 次の表示可能な行を見つける（下方向）
function findNextVisibleRow(currentRow) {
  const visibleRowsList = visibleRows.value.map(r => r - 1) // 1-indexed → 0-indexed
  const currentIndex = visibleRowsList.indexOf(currentRow)
  if (currentIndex >= 0 && currentIndex < visibleRowsList.length - 1) {
    return visibleRowsList[currentIndex + 1]
  }
  return currentRow
}

// 選択セルがグリッドコンテナ内で見えるようにスクロール
function ensureCellVisible(row, col) {
  const container = gridContainer.value || document.querySelector('.estimate-grid-container')
  if (!container) return

  const cell = container.querySelector(`td[data-r="${row}"][data-c="${col}"]`)
  if (!cell) return

  const containerRect = container.getBoundingClientRect()
  const cellRect = cell.getBoundingClientRect()

  const padding = 8
  let nextTop = container.scrollTop
  let nextLeft = container.scrollLeft

  // vertical
  if (cellRect.top < containerRect.top + padding) {
    nextTop -= (containerRect.top + padding) - cellRect.top
  } else if (cellRect.bottom > containerRect.bottom - padding) {
    nextTop += cellRect.bottom - (containerRect.bottom - padding)
  }

  // horizontal
  if (cellRect.left < containerRect.left + padding) {
    nextLeft -= (containerRect.left + padding) - cellRect.left
  } else if (cellRect.right > containerRect.right - padding) {
    nextLeft += cellRect.right - (containerRect.right - padding)
  }

  // clamp
  nextTop = Math.max(0, nextTop)
  nextLeft = Math.max(0, nextLeft)

  if (nextTop !== container.scrollTop || nextLeft !== container.scrollLeft) {
    container.scrollTo({ top: nextTop, left: nextLeft, behavior: 'auto' })
  }
}
// Delete処理の共通関数
function handleDeleteKey() {
  if (!selectedCell.value) return
  
  const { row, col } = selectedCell.value
  
  if (selectionStart.value && selectionEnd.value) {
    // 範囲選択がある場合 → バッチ処理
    const minRow = Math.min(selectionStart.value.row, selectionEnd.value.row)
    const maxRow = Math.max(selectionStart.value.row, selectionEnd.value.row)
    const minCol = Math.min(selectionStart.value.col, selectionEnd.value.col)
    const maxCol = Math.max(selectionStart.value.col, selectionEnd.value.col)
    
    // バッチUNDO開始
    startBatchUndo('範囲削除')
    
    try {
      for (let r = minRow; r <= maxRow; r++) {
        for (let c = minCol; c <= maxCol; c++) {
          setCellValueWithDirty(r, c, '')
        }
      }
    } finally {
      // バッチUNDO終了
      endBatchUndo()
    }
  } else {
    // 単一セルの場合 → 通常のUNDO
    setCellValueWithDirty(row, col, '')
  }
}

// Backspace処理の共通関数
function handleBackspaceKey() {
  if (!selectedCell.value) return
  
  const { row, col } = selectedCell.value
  
  if (selectionStart.value && selectionEnd.value) {
    // 範囲選択がある場合 → バッチ処理
    const minRow = Math.min(selectionStart.value.row, selectionEnd.value.row)
    const maxRow = Math.max(selectionStart.value.row, selectionEnd.value.row)
    const minCol = Math.min(selectionStart.value.col, selectionEnd.value.col)
    const maxCol = Math.max(selectionStart.value.col, selectionEnd.value.col)
    
    // バッチUNDO開始
    startBatchUndo('範囲削除（Backspace）')
    
    try {
      for (let r = minRow; r <= maxRow; r++) {
        for (let c = minCol; c <= maxCol; c++) {
          setCellValueWithDirty(r, c, '')
        }
      }
    } finally {
      // バッチUNDO終了
      endBatchUndo()
    }
    
    startEditing(minRow, minCol)
  } else {
    // 単一セルの場合 → 通常のUNDO
    setCellValueWithDirty(row, col, '')
    startEditing(row, col)
  }
}

// グリッド全体のキーイベント
function handleKeyDown(event) {
  // 編集中は処理しない
  if (editingCell.value) {
    return
  }
  
  if (!selectedCell.value) {
    return
  }
  
  const { row, col } = selectedCell.value
  
  // デバッグ: 選択セルの情報と入力不可判定をログ出力
  const isReadOnly = isReadOnlyCell(row, col)
  console.log('[handleKeyDown]', { key: event.key, row, col, isReadOnly, mod: getRowMod12(row) })
  
  // Enter: 編集開始
  if (event.key === 'Enter') {
    event.preventDefault()
    startEditing(row, col)
    return
  }
  
  // 印字可能文字（アルファベット、数字、記号など）が押された場合
  // IMEが有効な場合は、入力欄を開いてIME入力を開始
  if (event.key.length === 1 && !event.ctrlKey && !event.altKey && !event.metaKey) {
    event.preventDefault()
    // セルの内容をクリアして編集開始
    setCellValue(row, col, '')
    startEditingWithInitialInput(row, col, event.key)
    return
  }
  
  // Ctrl+C: コピー（編集中でない場合のみ）
  if ((event.ctrlKey || event.metaKey) && event.key === 'c') {
    event.preventDefault()
    handleSnippetCopy()
    return
  }
  
  // Ctrl+X: 切り取り（編集中でない場合のみ）
  if ((event.ctrlKey || event.metaKey) && event.key === 'x') {
    event.preventDefault()
    handleSnippetCut()
    return
  }
  
  // Ctrl+V: 貼り付け（編集中でない場合のみ）
  if ((event.ctrlKey || event.metaKey) && event.key === 'v') {
    event.preventDefault()
    handleGridPaste()
    return
  }
  
  if ((event.ctrlKey || event.metaKey) && event.key === 'z') {
      event.preventDefault()
      handleUndo()
      return
  }

  // Delete: 選択範囲の内容を消去
  if (event.key === 'Delete') {
    event.preventDefault()
    handleDeleteKey()
    return
  }
  
  // Backspace: 内容消去 + 編集開始
  if (event.key === 'Backspace') {
    event.preventDefault()
    handleBackspaceKey()
    return
  }
  
  // 矢印キー: セル選択の移動
  if (event.key === 'ArrowUp') {
    event.preventDefault()
    const prevRow = findPreviousVisibleRow(row)
    if (prevRow !== row) {
      selectedCell.value = { row: prevRow, col }
      if (event.shiftKey && selectionStart.value) {
        // Shiftキーが押されている場合は選択範囲を拡張
        selectionEnd.value = { row: prevRow, col }
      } else {
        // Shiftキーなしの場合は単一セル選択
        selectionStart.value = { row: prevRow, col }
        selectionEnd.value = { row: prevRow, col }
      }
      ensureCellVisible(prevRow, col)
      // hiddenInputにフォーカスを維持（IME入力とキーボードショートカット両対応）
      nextTick(() => {
        focusHiddenInput()
      })
    }
    return
  }
  
  if (event.key === 'ArrowDown') {
    event.preventDefault()
    const nextRow = findNextVisibleRow(row)
    if (nextRow !== row) {
      selectedCell.value = { row: nextRow, col }
      if (event.shiftKey && selectionStart.value) {
        // Shiftキーが押されている場合は選択範囲を拡張
        selectionEnd.value = { row: nextRow, col }
      } else {
        // Shiftキーなしの場合は単一セル選択
        selectionStart.value = { row: nextRow, col }
        selectionEnd.value = { row: nextRow, col }
      }
      ensureCellVisible(nextRow, col)
      // hiddenInputにフォーカスを維持（IME入力とキーボードショートカット両対応）
      nextTick(() => {
        focusHiddenInput()
      })
    }
    return
  }
  
  if (event.key === 'ArrowLeft') {
    event.preventDefault()
    if (col > 0) {
      selectedCell.value = { row, col: col - 1 }
      if (event.shiftKey && selectionStart.value) {
        // Shiftキーが押されている場合は選択範囲を拡張
        selectionEnd.value = { row, col: col - 1 }
      } else {
        // Shiftキーなしの場合は単一セル選択
        selectionStart.value = { row, col: col - 1 }
        selectionEnd.value = { row, col: col - 1 }
      }
      ensureCellVisible(row, col - 1)
      // hiddenInputにフォーカスを維持（IME入力とキーボードショートカット両対応）
      nextTick(() => {
        focusHiddenInput()
      })
    }
    return
  }
  
  if (event.key === 'ArrowRight') {
    event.preventDefault()
    if (col < columnCount - 1) {
      selectedCell.value = { row, col: col + 1 }
      if (event.shiftKey && selectionStart.value) {
        // Shiftキーが押されている場合は選択範囲を拡張
        selectionEnd.value = { row, col: col + 1 }
      } else {
        // Shiftキーなしの場合は単一セル選択
        selectionStart.value = { row, col: col + 1 }
        selectionEnd.value = { row, col: col + 1 }
      }
      ensureCellVisible(row, col + 1)
      // hiddenInputにフォーカスを維持（IME入力とキーボードショートカット両対応）
      nextTick(() => {
        focusHiddenInput()
      })
    }
    return
  }
}

// 初期入力付きで編集開始（IME対応）
function startEditingWithInitialInput(row, col, initialKey) {
  editingCell.value = { row, col }
  nextTick(() => {
    // 行番号と列番号から直接セル要素を取得（オプション1: セル要素の直接取得）
    // data-r と data-c 属性を使用して高速化
    const cellEl = gridContent.value?.querySelector(
      `td.cell[data-r="${row}"][data-c="${col}"] .cell-input`
    )
    if (cellEl) {
      const input = cellEl
      input.focus()
      
      // IMEが有効かどうかを判定するために、compositionstartイベントを待つ
      // しかし、キーイベントは既に発火済みなので、手動でキーイベントを再発火させる
      
      // inputイベントを使用して、IMEの入力を開始
      // ブラウザのIME処理に任せるため、何もしない
      // フォーカスを当てるだけで、次のキー入力がIME経由になる
    } else {
      // フォールバック: 表示範囲外のセルの場合（仮想スクロール化後の対応）
      console.warn(`⚠️ [startEditingWithInitialInput] Cell input not found for row ${row}, col ${col}. Cell may be outside visible range.`)
    }
  })
}

// 不可視inputにフォーカス
function focusHiddenInput() {
  if (gridViewTab.value !== 'originalGrid') {
    return
  }
  // タブレット原本タブでは hidden input を使わない
  if (isTabletOriginalDirectEditMode.value) {
    return
  }
  // 左パネル内の要素がアクティブな場合はフォーカスしない
  const activeElement = document.activeElement
  
  if (activeElement && activeElement.closest('.left-panel')) {
    return
  }
  // 写真タブ内の入力中は不可視 input へフォーカスを奪わない
  if (activeElement && (activeElement.closest('.photo-work-panel-host') || activeElement.closest('.photo-work-panel'))) {
    return
  }
  
  // モーダル内の要素がアクティブな場合はフォーカスしない
  if (activeElement && (activeElement.closest('.modal-overlay') || activeElement.closest('.modal-content'))) {
    return
  }
  
  // セレクトボックスがアクティブな場合はフォーカスしない
  if (activeElement && activeElement.tagName === 'SELECT') {
    return
  }
  
  // インプット要素がアクティブでモーダル内の場合はフォーカスしない
  if (activeElement && activeElement.tagName === 'INPUT' && activeElement.closest('.modal-content')) {
    return
  }
  
  // 選択中のセルがリードオンリーの場合はフォーカスしない
  if (isSelectedCellReadOnly.value) {
    return
  }
  
  if (!editingCell.value && hiddenInput.value) {
    nextTick(() => {
      hiddenInput.value.focus()
    })
  }
}

// グリッドコンテナのクリック処理（左パネルからのイベントは無視）
function handleGridContainerClick(event) {
  // モーダルのクリックかどうかをチェック
  const isModalClick = event.target.closest('.modal-overlay') || event.target.closest('.modal-content')
  if (isModalClick) {
    // モーダル内のクリックは無視
    return
  }
  
  // クリックされた要素が左パネル内かどうかをチェック
  const leftPanel = event.target.closest('.left-panel')
  
  if (leftPanel) {
    // 左パネル内のクリックは無視（ドラッグ&ドロップのため伝播は許可）
    return
  }
  // 写真タブ内のクリックでは hiddenInput にフォーカスを戻さない
  const isPhotoPanelClick = event.target.closest('.photo-work-panel-host') || event.target.closest('.photo-work-panel')
  if (isPhotoPanelClick) {
    return
  }
  
  // セレクトボックスのクリックかどうかをチェック
  const isSelectClick = event.target.tagName === 'SELECT' || event.target.closest('select')
  if (isSelectClick) {
    return
  }
  
  // グリッド内のクリックのみfocusHiddenInputを実行
  focusHiddenInput()
}

// 不可視inputのcompositionstart
function handleHiddenCompositionStart() {
  // リードオンリーセルの場合は処理をスキップ
  if (isSelectedCellReadOnly.value) {
    isHiddenComposing.value = false
    hiddenInputValue.value = ''
    return
  }
  
  isHiddenComposing.value = true
  
  // セルが選択されていれば、編集を開始
  if (selectedCell.value && !editingCell.value) {
    const { row, col } = selectedCell.value
    // セルの内容をクリア
    setCellValue(row, col, '')
    editingCell.value = { row, col }
  }
}

// 不可視inputのcompositionupdate
function handleHiddenCompositionUpdate(event) {
  // リードオンリーセルの場合は処理をスキップ
  if (isSelectedCellReadOnly.value) {
    return
  }
  
  // 変換中のテキストを取得
  if (editingCell.value) {
    const { row, col } = editingCell.value
    setCellValue(row, col, event.data || '')
  }
}

// 不可視inputのcompositionend
function handleHiddenCompositionEnd(event) {
  // リードオンリーセルの場合は処理をスキップ
  if (isSelectedCellReadOnly.value) {
    isHiddenComposing.value = false
    hiddenInputValue.value = ''
    return
  }
  
  isHiddenComposing.value = false
  
  // 確定したテキストをセルに設定
  if (editingCell.value) {
    const { row, col } = editingCell.value
    setCellValue(row, col, event.data || hiddenInputValue.value)
    
    // 入力をクリア
    hiddenInputValue.value = ''
    
    // 編集中状態を維持（次の入力に備える）
    nextTick(() => {
      const inputs = document.querySelectorAll('.cell-input')
      if (inputs.length > 0) {
        inputs[0].focus()
      }
    })
  }
}

// 不可視inputの入力
function handleHiddenInput(event) {
  // IME変換中でない場合の直接入力
  if (!isHiddenComposing.value && event.target.value) {
    if (selectedCell.value && !editingCell.value) {
      // リードオンリーセルの場合は入力を無視
      if (isSelectedCellReadOnly.value) {
        event.target.value = ''
        return
      }
      
      const { row, col } = selectedCell.value
      setCellValueWithDirty(row, col, '')  // 変更
      editingCell.value = { row, col }
    }
    
    if (editingCell.value) {
      const { row, col } = editingCell.value
      
      // 編集中セルがリードオンリーの場合は入力を無視
      if (isReadOnlyCell(row, col)) {
        event.target.value = ''
        return
      }
      
      setCellValueWithDirty(row, col, event.target.value)  // 変更
      
      // 編集モードに切り替え
      nextTick(() => {
        const inputs = document.querySelectorAll('.cell-input')
        if (inputs.length > 0) {
          const input = inputs[0]
          input.focus()
          // カーソルを末尾に移動
          input.setSelectionRange(input.value.length, input.value.length)
        }
        // 不可視inputをクリア
        hiddenInputValue.value = ''
      })
    }
  }
}

// 不可視inputのキーダウン
function handleHiddenKeyDown(event) {
  // Ctrl+Z: 元に戻す（編集中でも有効）
  if ((event.ctrlKey || event.metaKey) && event.key === 'z') {
    event.preventDefault()
    handleUndo()
    return
  }

  // 編集中でない場合のキー操作
  if (!editingCell.value && selectedCell.value) {
    const { row, col } = selectedCell.value
    
    // アローキーは常に許可（セル移動のため）
    const isArrowKey = event.key === 'ArrowUp' || event.key === 'ArrowDown' || 
                       event.key === 'ArrowLeft' || event.key === 'ArrowRight'
    
    // リードオンリーセルの場合、アローキー以外の入力を無視
    if (isSelectedCellReadOnly.value && !isArrowKey) {
      event.preventDefault()
      return
    }
    
    // Ctrl+C: コピー
    if ((event.ctrlKey || event.metaKey) && event.key === 'c') {
      event.preventDefault()
      handleSnippetCopy()
      return
    }
    
    // Ctrl+X: 切り取り
    if ((event.ctrlKey || event.metaKey) && event.key === 'x') {
      event.preventDefault()
      handleSnippetCut()
      return
    }
    
    // Ctrl+V: 貼り付け
    if ((event.ctrlKey || event.metaKey) && event.key === 'v') {
      event.preventDefault()
      handleGridPaste()
      return
    }

    // Enter: 編集開始
    if (event.key === 'Enter') {
      event.preventDefault()
      startEditing(row, col)
      return
    }
  
    // Delete: 選択範囲の内容を消去
    if (event.key === 'Delete') {
      event.preventDefault()
      handleDeleteKey()
      return
    }
    
    // Backspace: 内容消去 + 編集開始
    if (event.key === 'Backspace') {
      event.preventDefault()
      handleBackspaceKey()
      return
    }
    // 矢印キー
    if (event.key === 'ArrowUp') {
      event.preventDefault()
      const prevRow = findPreviousVisibleRow(row)
      if (prevRow !== row) {
        selectedCell.value = { row: prevRow, col }
        if (event.shiftKey && selectionStart.value) {
          // Shiftキーが押されている場合は選択範囲を拡張
          selectionEnd.value = { row: prevRow, col }
        } else {
          // Shiftキーなしの場合は単一セル選択
          selectionStart.value = { row: prevRow, col }
          selectionEnd.value = { row: prevRow, col }
        }
        ensureCellVisible(prevRow, col)
      }
      return
    }
    
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      const nextRow = findNextVisibleRow(row)
      if (nextRow !== row) {
        selectedCell.value = { row: nextRow, col }
        if (event.shiftKey && selectionStart.value) {
          // Shiftキーが押されている場合は選択範囲を拡張
          selectionEnd.value = { row: nextRow, col }
        } else {
          // Shiftキーなしの場合は単一セル選択
          selectionStart.value = { row: nextRow, col }
          selectionEnd.value = { row: nextRow, col }
        }
        ensureCellVisible(nextRow, col)
      }
      return
    }
    
    if (event.key === 'ArrowLeft') {
      event.preventDefault()
      if (col > 0) {
        const nextCol = getPrevEditableCol(col)
        selectedCell.value = { row, col: nextCol }
        if (event.shiftKey && selectionStart.value) {
          // Shiftキーが押されている場合は選択範囲を拡張
          selectionEnd.value = { row, col: nextCol }
        } else {
          // Shiftキーなしの場合は単一セル選択
          selectionStart.value = { row, col: nextCol }
          selectionEnd.value = { row, col: nextCol }
        }
        ensureCellVisible(row, nextCol)
      }
      return
    }
    
    if (event.key === 'ArrowRight') {
      event.preventDefault()
      if (col < columnCount - 1) {
        const nextCol = getNextEditableCol(col)
        selectedCell.value = { row, col: nextCol }
        if (event.shiftKey && selectionStart.value) {
          // Shiftキーが押されている場合は選択範囲を拡張
          selectionEnd.value = { row, col: nextCol }
        } else {
          // Shiftキーなしの場合は単一セル選択
          selectionStart.value = { row, col: nextCol }
          selectionEnd.value = { row, col: nextCol }
        }
        ensureCellVisible(row, nextCol)
      }
      return
    }
  }
}

// 不可視inputのblur
function handleHiddenBlur(event) {
  if (gridViewTab.value !== 'originalGrid') {
    return
  }
  if (isTabletOriginalDirectEditMode.value) {
    return
  }
  // 左パネル内の要素にフォーカスが移った場合は、フォーカスを戻さない
  if (event.relatedTarget) {
    const isLeftPanelElement = event.relatedTarget.closest('.left-panel')
    if (isLeftPanelElement) {
      return
    }
    // 写真タブ内へフォーカス遷移した場合は、フォーカスを戻さない
    const isPhotoPanelElement = event.relatedTarget.closest('.photo-work-panel-host') || event.relatedTarget.closest('.photo-work-panel')
    if (isPhotoPanelElement) {
      return
    }
    
    // モーダル内の要素にフォーカスが移った場合は、フォーカスを戻さない
    const isModalElement = event.relatedTarget.closest('.modal-overlay') || event.relatedTarget.closest('.modal-content')
    if (isModalElement) {
      return
    }
    
    // セレクトボックスにフォーカスが移った場合は、フォーカスを戻さない
    if (event.relatedTarget.tagName === 'SELECT') {
      return
    }
  }
  
  // 編集中でない場合は、すぐにフォーカスを戻す
  if (!editingCell.value) {
    setTimeout(() => {
      if (hiddenInput.value && !editingCell.value) {
        // 選択中のセルがリードオンリーの場合はフォーカスを戻さない
        if (isSelectedCellReadOnly.value) {
          return
        }
        
        // 再度チェック：フォーカスが左パネル内やモーダル内にない場合のみ
        const activeElement = document.activeElement
        
        // モーダル内の要素がアクティブな場合はフォーカスを戻さない
        if (activeElement && (activeElement.closest('.modal-overlay') || activeElement.closest('.modal-content'))) {
          return
        }
        
        // セレクトボックスがアクティブな場合はフォーカスを戻さない
        if (activeElement && activeElement.tagName === 'SELECT') {
          return
        }
        // 写真タブ内で操作中ならフォーカスを戻さない
        if (activeElement && (activeElement.closest('.photo-work-panel-host') || activeElement.closest('.photo-work-panel'))) {
          return
        }
        
        if (activeElement && !activeElement.closest('.left-panel')) {
          hiddenInput.value.focus()
        }
      }
    }, 0)
  }
}

// 親コンポーネントから呼び出せるようにexpose
defineExpose({
  loadEstimateSlots,
  loadContractors,
  hasUnsavedChanges: () => hasUnsavedChangesForToolbar.value,
  clearUnsavedChanges: async () => {
    // メモリ上の未保存変更をクリア
    dirtySlots.value.clear()
    newSlots.value.clear()
    deletedSlots.value.clear()
    
    // IndexedDBのダーティ情報を削除
    await clearDirtyState()
    
    // IndexedDBのestimate_slotsを削除
    if (props.workId) {
      await indexedDBService.deleteEstimateSlots(props.workId)
    }
    
    // グリッドをクリア
    cellData.value = {}
    checkboxData.value = {}
    estimateSlots.value = []
    rowToSlotMap.value = {}
    sortOrders.value = {}
  },
  reloadFromServer: async () => {
    if (!props.workId) {
      console.warn('⚠️ [reloadFromServer] workId is not provided')
      return
    }
    
    // ダーティ情報を全てクリア
    dirtySlots.value.clear()
    newSlots.value.clear()
    deletedSlots.value.clear()

    // IndexedDBのダーティ情報も削除
    await clearDirtyState()

    applyLightweightPanelResumeState()

    // 見積ボタン押下のたびに work / プライスリスト初期選択を更新
    await loadWorkData({ forceDefaultPriceList: true })

    await loadEstimateSlots(null, true)

    // 写真タブデータは更新ボタン時のみ明示リロード
    if (showPhotoWorkTab.value && photoWorkPanelRef.value?.reloadData) {
      await photoWorkPanelRef.value.reloadData()
    }
  },
  scrollPriceListToExternalCode,
  scrollPriceListToItemId
})

// ========== スニペット関連 ==========
// コンテキストメニューを表示
function handleContextMenu(event, inputElement) {
  event.preventDefault()
  
  // 選択範囲を保存
  if (inputElement) {
    snippetTargetInput.value = inputElement
    snippetSavedSelection.value = {
      start: inputElement.selectionStart,
      end: inputElement.selectionEnd
    }
  }
  
  // メニュー位置を計算（画面外に出ないように調整）
  const menuWidth = 220
  const menuHeight = 350
  let x = event.clientX
  let y = event.clientY
  
  if (x + menuWidth > window.innerWidth) {
    x = window.innerWidth - menuWidth - 10
  }
  if (y + menuHeight > window.innerHeight) {
    y = window.innerHeight - menuHeight - 10
  }
  
  snippetContextMenuPosition.value = { x, y }
  showSnippetContextMenu.value = true
}

// コピー（矩形範囲対応、表示行のみ）
async function handleSnippetCopy() {
  // セル選択中の場合
  if (selectionStart.value && selectionEnd.value) {
    // 矩形範囲を取得（0-indexed）
    const minRow = Math.min(selectionStart.value.row, selectionEnd.value.row)
    const maxRow = Math.max(selectionStart.value.row, selectionEnd.value.row)
    const minCol = Math.min(selectionStart.value.col, selectionEnd.value.col)
    const maxCol = Math.max(selectionStart.value.col, selectionEnd.value.col)
    
    // 表示中の行のリストを取得（visibleRowsは1-indexedなので0-indexedに変換）
    const displayedRows = visibleRows.value.map(r => r - 1)
    
    // 選択範囲内の表示中の行のみを抽出
    const rowsToCopy = displayedRows.filter(row => row >= minRow && row <= maxRow)
    
    // タブ区切り・改行区切りでテキストを構築（Excel形式）
    const rows = []
    for (const r of rowsToCopy) {
      const cols = []
      for (let c = minCol; c <= maxCol; c++) {
        // 入力不可セルは空白として扱う
        let value = ''
        if (!isReadOnlyCell(r, c)) {
          value = getCellValue(r, c) || ''
        }
        cols.push(value)
      }
      rows.push(cols.join('\t'))
    }
    const textToCopy = rows.join('\n')
    
    try {
      await navigator.clipboard.writeText(textToCopy)
    } catch (err) {
      console.error('コピーに失敗しました:', err)
    }
  }
  // 入力モード中でセル選択がない場合は、入力フィールドの選択範囲をコピー
  else if (editingCell.value && snippetTargetInput.value) {
    const input = snippetTargetInput.value
    const { start, end } = snippetSavedSelection.value
    const selectedText = (input.value || '').substring(start, end)
    
    try {
      await navigator.clipboard.writeText(selectedText)
    } catch (err) {
      console.error('コピーに失敗しました:', err)
    }
  }
  
  showSnippetContextMenu.value = false
}

// 切り取り（矩形範囲対応、表示行のみ）
async function handleSnippetCut() {
  // セル選択中の場合
  if (selectionStart.value && selectionEnd.value) {
    // 矩形範囲を取得（0-indexed）
    const minRow = Math.min(selectionStart.value.row, selectionEnd.value.row)
    const maxRow = Math.max(selectionStart.value.row, selectionEnd.value.row)
    const minCol = Math.min(selectionStart.value.col, selectionEnd.value.col)
    const maxCol = Math.max(selectionStart.value.col, selectionEnd.value.col)
    
    // 表示中の行のリストを取得（visibleRowsは1-indexedなので0-indexedに変換）
    const displayedRows = visibleRows.value.map(r => r - 1)
    
    // 選択範囲内の表示中の行のみを抽出
    const rowsToCut = displayedRows.filter(row => row >= minRow && row <= maxRow)
    
    // タブ区切り・改行区切りでテキストを構築（Excel形式）
    const rows = []
    for (const r of rowsToCut) {
      const cols = []
      for (let c = minCol; c <= maxCol; c++) {
        // 入力不可セルは空白として扱う
        let value = ''
        if (!isReadOnlyCell(r, c)) {
          value = getCellValue(r, c) || ''
        }
        cols.push(value)
      }
      rows.push(cols.join('\t'))
    }
    const textToCopy = rows.join('\n')
    
    try {
      await navigator.clipboard.writeText(textToCopy)
      
      // 選択範囲の値をクリア（表示中の行のみ、入力可能セルのみ）
      const affectedSlots = new Set()
      for (const r of rowsToCut) {
        for (let c = minCol; c <= maxCol; c++) {
          // 入力不可セルはクリアしない
          if (!isReadOnlyCell(r, c)) {
            setCellValue(r, c, '')
          }
        }
        affectedSlots.add(r)
      }
      
      // 各スロットをダーティとしてマーク
      affectedSlots.forEach(r => markSlotAsDirty(r))
    } catch (err) {
      console.error('切り取りに失敗しました:', err)
    }
  }
  // 入力モード中でセル選択がない場合は、入力フィールドの選択範囲を切り取り
  else if (editingCell.value && snippetTargetInput.value) {
    const input = snippetTargetInput.value
    const { start, end } = snippetSavedSelection.value
    const selectedText = (input.value || '').substring(start, end)
    
    try {
      await navigator.clipboard.writeText(selectedText)
      // 選択範囲がある場合のみ削除
      if (selectedText) {
        const currentValue = input.value || ''
        const newValue = currentValue.substring(0, start) + currentValue.substring(end)
        input.value = newValue
        input.dispatchEvent(new Event('input', { bubbles: true }))
      }
    } catch (err) {
      console.error('切り取りに失敗しました:', err)
    }
  }
  
  showSnippetContextMenu.value = false
}

// 貼り付け（右クリックメニュー用 - グリッド貼り付けに統一）
async function handleSnippetPaste() {
  // 編集モード中の場合は入力フィールドに貼り付け
  if (editingCell.value && snippetTargetInput.value) {
    const input = snippetTargetInput.value
    try {
      const clipboardText = await navigator.clipboard.readText()
      const { start, end } = snippetSavedSelection.value
      const currentValue = input.value || ''
      const newValue = currentValue.substring(0, start) + clipboardText + currentValue.substring(end)
      input.value = newValue
      input.dispatchEvent(new Event('input', { bubbles: true }))
    } catch (err) {
      console.error('貼り付けに失敗しました:', err)
    }
  }
  // それ以外はグリッドに貼り付け
  else {
    await handleGridPaste()
  }
  
  showSnippetContextMenu.value = false
}

// グリッド貼り付け（矩形範囲対応、Excel形式対応、表示行のみ、入力不可セルはスキップ）
async function handleGridPaste() {
  if (!selectedCell.value) {
    return
  }
  
  try {
    const clipboardText = await navigator.clipboard.readText()
    const rows = clipboardText.split(/\r?\n/)
    if (rows.length > 0 && rows[rows.length - 1] === '') {
      rows.pop()
    }
    const data = rows.map(row => row.split('\t'))
    
    const startRow = selectedCell.value.row
    const startCol = selectedCell.value.col
    const displayedRows = visibleRows.value.map(r => r - 1)
    const startIndex = displayedRows.indexOf(startRow)
    
    if (startIndex === -1) {
      return
    }
    
    let actualEndRow = startRow
    let actualEndCol = startCol
    
    // バッチUNDO開始
    startBatchUndo('貼り付け')
    
    try {
      for (let r = 0; r < data.length; r++) {
        const rowData = data[r]
        const targetIndex = startIndex + r
        
        if (targetIndex >= displayedRows.length) {
          break
        }
        
        const targetRow = displayedRows[targetIndex]
        actualEndRow = targetRow
        
        let rowMaxCol = startCol
        
        for (let c = 0; c < rowData.length; c++) {
          const targetCol = startCol + c
          
          if (targetCol < 0 || targetCol >= 12) continue
          if (isReadOnlyCell(targetRow, targetCol)) {
            continue
          }
          
          const value = rowData[c]
          setCellValueWithDirty(targetRow, targetCol, value)
          
          rowMaxCol = Math.max(rowMaxCol, targetCol)
        }
        
        actualEndCol = Math.max(actualEndCol, rowMaxCol)
      }
    } finally {
      // バッチUNDO終了
      endBatchUndo()
    }
    
    selectionStart.value = { row: startRow, col: startCol }
    selectionEnd.value = { row: actualEndRow, col: actualEndCol }
  } catch (err) {
    console.error('❌ [handleGridPaste] Paste failed:', err)
  }
}

