// テンプレート挿入確認（はい）
async function handleTemplateInsertConfirm(options = {}) {
  const { skipGridInitialization = false } = options
  if (!pendingTemplateData.value) return

  isInserting.value = true
  // 初期化中フラグをON（大量データ挿入中）
  isInitializing = true

  try {
    if (!skipGridInitialization) {
      await initializeEstimateGridForTemplateFlow()
    }

    const { templates: allTemplates, templateItems } = pendingTemplateData.value
    
    // template_mode = 'permanent'でフィルタリング
    const templates = allTemplates.filter(t => t.template_mode === 'permanent')
    
    if (templates.length === 0) {
      await dialog.alert('一時モードのテンプレートが見つかりません', { title: 'エラー' })
      return
    }
    
    // 現在の最後のスロットのsort_orderを取得
    let maxSortOrder = 0
    for (let i = 0; i < estimateSlots.value.length; i++) {
      const slot = estimateSlots.value[i]
      if (slot && slot.sort_order > maxSortOrder) {
        maxSortOrder = slot.sort_order
      }
    }
    
    // 新しいスロットの開始sort_order（最後のスロット + 10000）
    const startSortOrder = maxSortOrder + 10000

    // テンプレートからスロットを作成
    const createdSlots = []
    const newSlotIds = []
    
    for (let i = 0; i < templates.length; i++) {
      const template = templates[i]
      const newSlotId = `new_${Date.now()}_${i}`
      const newSortOrder = startSortOrder + (template.sort_order * 10000)
      
      const newSlot = {
        id: newSlotId,
        work_id: props.workId,
        price_code: template.price_code || '',
        instruction: template.instruction || '',
        contractor_id: template.contractor_id || null,
        quantity: template.quantity || null,
        sort_order: newSortOrder,
        key: template.key || null,
        is_item: template.is_item || false,
        is_index: template.is_index || false,
        is_quantity: template.is_quantity || false,
        is_unit: template.is_unit || false,
        is_item_location_category: template.is_item_location_category || false,
        is_item_instruction: template.is_item_instruction || false,
        is_item_quantity: template.is_item_quantity || false,
        unit: template.unit || null,
        deleted_at: null,
        items: []
      }
      
      // テンプレートアイテムを追加
      const slotItems = templateItems.filter(item => item.estimate_slot_template_id === template.id)
      if (slotItems.length > 0) {
        newSlot.items = slotItems.map((item, idx) => ({
          id: `new_item_${Date.now()}_${i}_${idx}`,
          estimate_slot_id: newSlotId,
          price_code: item.price_code || '',
          location_category: item.location_category || '',
          instruction: item.instruction || '',
          quantity: item.quantity || null,
          sort_order: item.sort_order
        }))
      }
      
      createdSlots.push(newSlot)
      newSlotIds.push(newSlotId)
    }
    
    // estimateSlotsに追加
    estimateSlots.value.push(...createdSlots)
    
    // スロットをsort_orderでソート
    estimateSlots.value.sort((a, b) => a.sort_order - b.sort_order)
    
    // グリッドを再構築: 追加したスロットをグリッドにマッピング
    const currentRowCount = Object.keys(rowToSlotMap.value).length
    const startBaseRow = Math.floor(currentRowCount / 12) * 12 // 次の12行ブロックの開始行
    
    // 新規スロットとしてマーク（行番号で管理）
    createdSlots.forEach((slot, index) => {
      const slotBaseRow = startBaseRow + (index * 12)
      newSlots.value.add(slotBaseRow)
    })
    
    createdSlots.forEach((slot, index) => {
      const slotBaseRow = startBaseRow + (index * 12)
      
      // この12行ブロックのすべての行にスロットIDとソートオーダーをマッピング
      for (let i = 0; i < 12; i++) {
        rowToSlotMap.value[slotBaseRow + i] = slot.id
        sortOrders.value[slotBaseRow + i] = slot.sort_order
      }
      
      // MOD12=1: スロットの基本情報
      setCellValue(slotBaseRow, 3, slot.price_code || '')
      if (slot.contractor_id) {
        setCellValue(slotBaseRow, 4, slot.contractor_id)
      }
      setCellValue(slotBaseRow, 5, slot.instruction || '')
      setCellValue(slotBaseRow, 8, slot.quantity || '')
      setCheckboxValue(slotBaseRow, 6, slot.is_unit || false)
      setCheckboxValue(slotBaseRow, 7, slot.is_quantity || false)
      
      // MOD12=2: スロットのフラグと詳細
      const mod2Row = slotBaseRow + 1
      setCheckboxValue(mod2Row, 1, slot.is_index || false)
      setCheckboxValue(mod2Row, 2, slot.is_item || false)
      setCellValue(mod2Row, 3, slot.key || '')
      setCellValue(mod2Row, 7, slot.unit || '')
      
      setCheckboxValue(slotBaseRow + 3, 2, slot.is_item_location_category || false)
      setCheckboxValue(slotBaseRow + 4, 2, slot.is_item_instruction || false)
      setCheckboxValue(slotBaseRow + 5, 2, slot.is_item_quantity || false)
      
      // MOD12=3～11: アイテム情報
      if (slot.items && slot.items.length > 0) {
        const sortedItems = [...slot.items].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0))
        
        sortedItems.forEach((item, itemIndex) => {
          const itemRow = slotBaseRow + 2 + itemIndex
          
          // 4列目: price_code
          setCellValue(itemRow, 3, item.price_code || '')
          // 5列目: location_category
          setCellValue(itemRow, 4, item.location_category || '')
          // 6列目: instruction
          setCellValue(itemRow, 5, item.instruction || '')
          // 9列目: quantity
          setCellValue(itemRow, 8, item.quantity || '')
        })
      }
    })
    
    await dialog.alert(`テンプレートを追加しました（${createdSlots.length}スロット）`, { title: '成功' })
    
  } catch (err) {
    console.error('❌ [AddTemplate] Failed to add template:', err)
    await dialog.alert(`テンプレート追加に失敗しました: ${err.message}`, { title: 'エラー' })
  } finally {
    isInitializing = false
    isInserting.value = false
    pendingTemplateData.value = null
  }
}

