// ========================================
// エクセル出力用ヘルパー関数
// ========================================

// 特殊予約文字を処理（*/と/*で囲まれた文字を空白に置換）
function removeCommentBlocks(text) {
  if (!text || typeof text !== 'string') return text
  // */と/*で囲まれた部分を空白に置換
  return text.replace(/\*\/.*?\/\*/g, '')
}

/**
 * Excel ペイロードの display 文字列（大型変更前＝写真スニペット追記前の仕様）
 *
 * 1) 起点: slotData.instruction（そのまま。removeCommentBlocks は付けない）
 * 2) 親の数量フラグ ON かつ quantity あり:
 *    - 単位も ON かつ unit あり → 半角スペース（必要時）＋「[数量 単位]」
 *    - 上記以外 → 半角スペース（必要時）＋「[x数量]」
 * 3) 単位: is_unit かつ unit ありで、かつ (2) で括弧に単位を入れていないときだけ
 *    → 半角スペース＋unit を末尾に付与
 * 4) 子アイテム is_item かつ数量が埋まっている行のみ:
 *    - 末尾に「 ( 」…各アイテムは半角スペースで連結…「 ) 」
 *    - 各アイテム: フラグに応じて location_category / instruction / is_item_quantity かつ数量ありなら「 x」+quantity
 * 5) 写真ドラフト由来のスニペット（aggregatePhotoSnippetsByNormCode）は付けない
 */
function generateDisplayText(slotData, items) {
  let display = slotData.instruction || ""

  if (slotData.is_quantity && slotData.quantity !== null && slotData.quantity !== undefined && slotData.quantity !== "") {
    // 数量ボタンON時:
    // - 単位あり: [数量 単位]
    // - 単位なし: [x数量]
    const hasUnit = slotData.is_unit && slotData.unit
    const bracket = hasUnit
      ? "[" + slotData.quantity + " " + String(slotData.unit) + "]"
      : "[x" + slotData.quantity + "]"
    display += (display ? " " : "") + bracket
  }

  if (slotData.is_unit && slotData.unit) {
    // 数量ボタンON時は単位を括弧内へ入れるため、ここでは追加しない
    if (!(slotData.is_quantity && slotData.quantity !== null && slotData.quantity !== undefined && slotData.quantity !== "")) {
      display += " " + slotData.unit
    }
  }

  if (slotData.is_item && items && items.length > 0) {
    const validItems = items.filter(item =>
      item.quantity !== null && item.quantity !== undefined && item.quantity !== ""
    )

    if (validItems.length > 0) {
      const itemTexts = validItems
        .map((item) => {
          let itemText = ""

          if (slotData.is_item_location_category) {
            const cat = String(item.location_category ?? '').trim()
            if (cat) itemText += cat
          }

          if (slotData.is_item_instruction) {
            const ins = String(item.instruction ?? '').trim()
            if (ins) {
              if (itemText) itemText += ' '
              itemText += ins
            }
          }

          if (
            slotData.is_item_quantity &&
            item.quantity !== null &&
            item.quantity !== undefined &&
            item.quantity !== ''
          ) {
            itemText += ' x' + item.quantity
          }

          return itemText.trim()
        })
        .filter((text) => text.length > 0)

      if (itemTexts.length > 0) {
        display += ' ( '
        display += itemTexts.join(' ')
        display += ' )'
      }
    }
  }

  return display
}

// 文字数をカウント（半角=1、全角=2）
function countCharacters(text) {
  if (!text) return 0
  let count = 0
  for (let i = 0; i < text.length; i++) {
    const char = text.charAt(i)
    // 半角英数字記号
    if (char.match(/[\x00-\x7F]/)) {
      count += 1
    } else {
      // 全角
      count += 2
    }
  }
  return count
}

/** def1/def2 の依頼先見出し行（def グループのデータ行・`{}` 分割続き行は false） */
function isExcelContractorLabelSlot(slot) {
  if (slot?.excel_display_continuation) return false
  return (
    slot?.font_style === 'bold' &&
    (slot.contractor_id == null || String(slot.contractor_id).trim() === '') &&
    (slot.price_code == null || String(slot.price_code).trim() === '') &&
    (slot.instruction == null || String(slot.instruction).trim() === '')
  )
}

function reassignExcelDefGroupSlots(payload, prefix, slotDataList) {
  Object.keys(payload)
    .filter((k) => k.startsWith(`${prefix}-`))
    .forEach((k) => {
      delete payload[k]
    })

  let newIndex = 1
  let isFirstContractor = true

  slotDataList.forEach((data) => {
    if (prefix === 'def') {
      payload[`${prefix}-${newIndex}`] = data
      newIndex++
      return
    }

    if (isExcelContractorLabelSlot(data)) {
      if (!isFirstContractor) {
        newIndex++
      }
      payload[`${prefix}-${newIndex}`] = data
      newIndex++
      isFirstContractor = false
    } else {
      payload[`${prefix}-${newIndex}`] = data
      newIndex++
    }
  })
}

/**
 * display 内の ` { ... }` を次行へ分割する。
 * 条件: 全体が wordCount+5 超 かつ `{...}`（括弧含む）が ceil(wordCount/2) 超
 * @returns {{ remainderDisplay: string, continuationDisplay: string } | null}
 */
function trySplitExcelDisplayBraceBlock(display, wordCountThreshold) {
  if (!wordCountThreshold || wordCountThreshold <= 0) return null
  const text = String(display ?? '')
  if (!text) return null

  const match = text.match(/\s(\{[^{}]*\})/)
  if (!match || match.index === undefined) return null

  const fullMatch = match[0]
  const braceBlock = match[1]
  const totalCount = countCharacters(text)
  const braceCount = countCharacters(braceBlock)

  if (totalCount <= wordCountThreshold + 5) return null
  if (braceCount <= Math.ceil(wordCountThreshold / 2)) return null

  const before = text.slice(0, match.index).trimEnd()
  const after = text.slice(match.index + fullMatch.length).trimStart()
  const remainderDisplay = [before, after].filter(Boolean).join(' ')
  const continuationDisplay = ` -${braceBlock}`

  return { remainderDisplay, continuationDisplay }
}

function buildExcelDisplayContinuationSlot(sourceSlot, continuationDisplay) {
  return {
    price_code: null,
    contractor_id: null,
    instruction: null,
    quantity: null,
    key: null,
    unit: null,
    sort_order: null,
    is_index: null,
    is_item: null,
    is_unit: null,
    is_quantity: null,
    is_item_location_category: null,
    is_item_instruction: null,
    is_item_quantity: null,
    is_highlight: Boolean(sourceSlot?.is_highlight),
    font_size: sourceSlot?.font_size ?? null,
    font_style: sourceSlot?.font_style ?? null,
    display: continuationDisplay,
    items: [],
    /** `{}` 分割の続き行。wordCount 結合（` / `）の対象外 */
    excel_display_continuation: true
  }
}

function isExcelDisplayContinuationSlot(slot) {
  return Boolean(slot?.excel_display_continuation)
}

function stripExcelPayloadInternalFlags(payload) {
  Object.values(payload || {}).forEach((slot) => {
    if (slot && typeof slot === 'object') {
      delete slot.excel_display_continuation
    }
  })
}

/** wordCount 設定時: `{...}` ブロックを次の display 行へ分割してから結合処理へ渡す */
function splitExcelPayloadDisplayBraceBlocks(payload, wordCount, highlightedWordCount) {
  if (!wordCount && !highlightedWordCount) return

  for (const prefix of ['def1', 'def2', 'def']) {
    const groupKeys = Object.keys(payload)
      .filter((k) => k.startsWith(`${prefix}-`))
      .sort((a, b) => {
        const numA = parseInt(a.split('-')[1], 10)
        const numB = parseInt(b.split('-')[1], 10)
        return numA - numB
      })

    const expanded = []
    for (const key of groupKeys) {
      const data = payload[key]
      if (prefix !== 'def' && isExcelContractorLabelSlot(data)) {
        expanded.push(data)
        continue
      }

      const threshold = data.is_highlight ? highlightedWordCount : wordCount
      const split = trySplitExcelDisplayBraceBlock(data.display, threshold)
      if (split) {
        expanded.push({ ...data, display: split.remainderDisplay })
        expanded.push(buildExcelDisplayContinuationSlot(data, split.continuationDisplay))
      } else {
        expanded.push(data)
      }
    }

    reassignExcelDefGroupSlots(payload, prefix, expanded)
  }
}

function normalizeContractorKeyForGrid(cid) {
  return cid != null && String(cid).trim() !== '' ? String(cid).trim() : ''
}

function isSpecialContractorId(cid) {
  const key = normalizeContractorKeyForGrid(cid)
  if (!key) return false
  const hit = contractors.value.find((c) => String(c.id) === key)
  return Boolean(hit?.is_special)
}

/**
 * 親 price_code または子アイテムの price_code が nk で、依頼先が一致するスロット。
 * 子一致時は itemIndex（0..9）を返し、数量は baseRow + 2 + itemIndex 行へ書く。
 */
function findGridSlotMatchForPhotoMerge(nk, contractorKey) {
  if (!nk) return null
  const ck = normalizeContractorKeyForGrid(contractorKey)
  const ordered = collectOrderedBaseRowsFromGrid()
  for (const baseRow of ordered) {
    const slotId = rowToSlotMap.value[baseRow]
    if (slotId && deletedSlots.value.has(slotId)) continue
    if (!slotId && deletedSlots.value.has(`new_${baseRow}`)) continue
    const rowCid = normalizeContractorKeyForGrid(getCellValue(baseRow, 4))
    if (rowCid !== ck) continue

    const headCode = normalizeExternalCode(getCellValue(baseRow, 3))
    if (headCode === nk) {
      return { baseRow, match: 'parent', itemIndex: null }
    }
    const items = getItemsDataFromGrid(baseRow)
    const itemIndex = items.findIndex((it) => normalizeExternalCode(it.price_code) === nk)
    if (itemIndex >= 0) {
      return { baseRow, match: 'item', itemIndex }
    }
  }
  return null
}

function sumPhotoMergeGroupQuantities(gRows) {
  let q = 0
  for (const r of gRows) {
    q = normalizeQuantityNumber(q + toNumberOrZero(r.quantity))
  }
  return q
}

/**
 * 写真ドラフトを同一正規化コード＋同一依頼先で集約し、見積グリッドへ反映する。
 * 子アイテム行: 5列目（場所）は原本のまま、6列目（内容）= 原本 { 写真集約 }（Excel 出力時のみ）。数量は9列目へ合算。
 * エクセル出力ではこの処理のあとペイロードを生成し、出力完了後に IndexedDB テンプレで再読込して画面を戻す。
 * 一致スロットがあれば上書き、なければ末尾に12行ブロックを挿入（依頼先不一致時もコードで原本6列目を引きマージ）。
 * display 生成はその後のグリッド読み取りに任せる。
 * 親の is_quantity・子の is_item_quantity など数量系チェックはグリッド上で変更しない（テンプレ／ユーザのまま）。
 */
function applyPhotoMergeInstructionTotalsToEstimateGrid() {
  if (!props.workId || !showPhotoWorkTab.value) return

  const links = getPhotoLinksByFileIdForMerge()
  const tmpl = collectFirstInstructionByCodeFromGrid(
    estimateSlots.value,
    rowToSlotMap.value,
    getCellValue,
    getRowMod12
  )
  const tmplGridInstructionOnly = collectFirstGridInstructionOnlyByCodeFromGrid(
    estimateSlots.value,
    rowToSlotMap.value,
    getCellValue,
    getRowMod12
  )
  const rows = buildInstructionMergeRows(
    links,
    [],
    tmpl,
    templateDisplayRankByNormCode.value,
    contractors.value
  )
  if (!rows.length) return

  const groups = new Map()
  const keyOrder = []
  for (const r of rows) {
    const nk = r.normCode || normalizeExternalCode(r.external_code)
    if (!nk) continue
    const cid =
      r.contractor_id != null && String(r.contractor_id).trim() !== ''
        ? String(r.contractor_id).trim()
        : null
    const contractorKey = cid ?? ''
    const gKey = `${nk}\u0000${contractorKey}`
    if (!groups.has(gKey)) {
      groups.set(gKey, [])
      keyOrder.push(gKey)
    }
    groups.get(gKey).push(r)
  }

  let insertBump = 0
  const maxSortOrder = () =>
    estimateSlots.value.length
      ? Math.max(...estimateSlots.value.map((s) => s.sort_order || 0))
      : 0

  for (const gKey of keyOrder) {
    const gRows = groups.get(gKey)
    const nk = gRows[0].normCode || normalizeExternalCode(gRows[0].external_code)
    const cid0 =
      gRows[0].contractor_id != null && String(gRows[0].contractor_id).trim() !== ''
        ? String(gRows[0].contractor_id).trim()
        : null

    // 特殊指示依頼先は Excel 用 payload を写真タブから直接組み立てる（原本グリッドへは反映しない）
    if (isSpecialContractorId(cid0)) continue

    const photoContent = buildPhotoContentFromMergeGroup(gRows)
    const qtySum = sumPhotoMergeGroupQuantities(gRows)
    const isQty = gRows.some((r) => Boolean(r.is_quantity))
    const codeRaw = String(gRows[0].external_code ?? '').trim()

    const slotMatch = findGridSlotMatchForPhotoMerge(nk, cid0)
    const qtyStr = isQty || qtySum !== 0 ? String(qtySum) : ''

    if (slotMatch != null) {
      const { baseRow, match, itemIndex } = slotMatch
      const slotId = rowToSlotMap.value[baseRow]
      const slot = estimateSlots.value.find((s) => s.id === slotId)

      if (match === 'parent') {
        const origInstr = String(getCellValue(baseRow, 5) ?? '').trim()
        const mergedInstr = mergeGridInstructionWithPhotoContentForExcel(origInstr, photoContent)
        if (codeRaw) setCellValueWithDirty(baseRow, 3, codeRaw)
        if (cid0) setCellValueWithDirty(baseRow, 4, cid0)
        else setCellValueWithDirty(baseRow, 4, '')
        setCellValueWithDirty(baseRow, 5, mergedInstr)
        setCellValueWithDirty(baseRow, 8, qtyStr)
        if (slot) {
          if (codeRaw) slot.price_code = codeRaw
          slot.instruction = mergedInstr
          slot.quantity = qtySum
          slot.contractor_id = cid0 || null
        }
      } else {
        const itemRow = baseRow + 2 + itemIndex
        const origInstr = String(getCellValue(itemRow, 5) ?? '').trim()
        const mergedInstr = mergeGridInstructionWithPhotoContentForExcel(origInstr, photoContent)
        if (codeRaw) setCellValueWithDirty(itemRow, 3, codeRaw)
        setCellValueWithDirty(itemRow, 5, mergedInstr)
        setCellValueWithDirty(itemRow, 8, qtyStr)
        if (slot?.items && slot.items[itemIndex]) {
          if (codeRaw) slot.items[itemIndex].price_code = codeRaw
          slot.items[itemIndex].instruction = mergedInstr
          slot.items[itemIndex].quantity = qtySum
        }
      }
    } else {
      const origInstr =
        tmplGridInstructionOnly instanceof Map
          ? String(tmplGridInstructionOnly.get(nk) ?? '').trim()
          : String(tmplGridInstructionOnly?.[nk] ?? '').trim()
      const mergedInstr = mergeGridInstructionWithPhotoContentForExcel(origInstr, photoContent)
      insertBump += 1
      const newSlotId = `new_${Date.now()}_${insertBump}_${Math.random().toString(36).slice(2, 9)}`
      const sortOrder = maxSortOrder() + 10000 + insertBump * 10
      const newSlot = {
        id: newSlotId,
        work_id: props.workId,
        price_code: codeRaw,
        instruction: mergedInstr,
        contractor_id: cid0 || null,
        quantity: qtySum,
        sort_order: sortOrder,
        key: null,
        is_item: false,
        is_index: false,
        is_quantity: false,
        is_unit: false,
        is_item_location_category: false,
        is_item_instruction: false,
        is_item_quantity: false,
        unit: null,
        deleted_at: null,
        items: []
      }
      estimateSlots.value.push(newSlot)

      const lastBase = getLastMappedBaseRow()
      const startBaseRow = lastBase < 0 ? 0 : lastBase + 12
      if (startBaseRow + 12 > rowCount) {
        estimateSlots.value.pop()
        continue
      }

      for (let i = 0; i < 12; i++) {
        rowToSlotMap.value[startBaseRow + i] = newSlotId
        sortOrders.value[startBaseRow + i] = sortOrder
      }
      newSlots.value.add(startBaseRow)

      setCellValueWithDirty(startBaseRow, 3, codeRaw)
      if (cid0) setCellValueWithDirty(startBaseRow, 4, cid0)
      else setCellValueWithDirty(startBaseRow, 4, '')
      setCellValueWithDirty(startBaseRow, 5, mergedInstr)
      setCellValueWithDirty(startBaseRow, 8, isQty || qtySum !== 0 ? String(qtySum) : '')
      setCheckboxValueWithDirty(startBaseRow, 6, false)
      setCheckboxValueWithDirty(startBaseRow, 7, false)
      setCheckboxValueWithDirty(startBaseRow, 9, false)

      const mod2 = startBaseRow + 1
      setCheckboxValueWithDirty(mod2, 1, false)
      setCheckboxValueWithDirty(mod2, 2, false)
      setCellValueWithDirty(mod2, 3, '')
      setCellValueWithDirty(mod2, 7, '')

      for (let i = 0; i < 10; i++) {
        const itemRow = startBaseRow + 2 + i
        setCheckboxValueWithDirty(itemRow, 2, false)
        setCellValueWithDirty(itemRow, 3, '')
        setCellValueWithDirty(itemRow, 4, '')
        setCellValueWithDirty(itemRow, 5, '')
        setCellValueWithDirty(itemRow, 8, '')
      }
    }
  }
}

/** 現在の estimateSlots からテンプレに存在する正規化コードの集合（親・子） */
function collectTemplateNormCodesFromEstimateSlots() {
  const set = new Set()
  for (const s of estimateSlots.value || []) {
    const nk = normalizeExternalCode(s?.price_code)
    if (nk) set.add(nk)
    for (const it of s?.items || []) {
      const nki = normalizeExternalCode(it?.price_code)
      if (nki) set.add(nki)
    }
  }
  return set
}

/** グリッド上の数量入力がある行のみ。依頼先 sort_order → 同一依頼先内は原本グリッド表示順（テンプレに無いコードは末尾） */
function collectExcelSlotEntriesFromGrid() {
  const contractorRank = new Map()
  contractors.value.forEach((c, i) => {
    contractorRank.set(String(c.id), c.sort_order ?? i)
  })
  const templateNormCodes = collectTemplateNormCodesFromEstimateSlots()
  const gridOrderRank = new Map()
  collectOrderedBaseRowsFromGrid().forEach((baseRow, i) => {
    gridOrderRank.set(baseRow, i)
  })

  function contractorSortMeta(cid) {
    if (cid == null || cid === '') {
      return { rank: 999999, id: '' }
    }
    const id = String(cid)
    const r = contractorRank.has(id) ? contractorRank.get(id) : 500000
    return { rank: r, id }
  }

  /** 親行＋子アイテム行の price_code を集める（is_item で親が空のとき用） */
  function collectNormCodesFromExcelSlot(slot) {
    const codes = []
    const parentNk = normalizeExternalCode(slot.slotData?.price_code)
    if (parentNk) codes.push(parentNk)
    for (const item of slot.items || []) {
      const nk = normalizeExternalCode(item?.price_code)
      if (nk) codes.push(nk)
    }
    return codes
  }

  /**
   * テンプレ一致の粗い段階（0=テンプレ内コードあり / 1=コードありだがテンプレ外 / 2=コードなし）
   * 親だけ空でも子アイテム行にコードがあれば 0 または 1 になる。
   */
  function templateMatchRank(slot) {
    const codes = collectNormCodesFromExcelSlot(slot)
    if (!codes.length) return 2
    if (codes.some((nk) => templateNormCodes.has(nk))) return 0
    return 1
  }

  function gridDisplayRank(slot) {
    if (gridOrderRank.has(slot.row)) return gridOrderRank.get(slot.row)
    return slot.sort_order || slot.row
  }

  const allSlots = []
  for (let row = 0; row < rowCount; row++) {
    if (getRowMod12(row) === 1) {
      const slotId = rowToSlotMap.value[row]
      if (slotId && deletedSlots.value.has(slotId)) continue
      if (!slotId && deletedSlots.value.has(`new_${row}`)) continue
      const slotData = getSlotDataFromGrid(row)
      const items = slotData.is_item ? getItemsDataFromGrid(row) : []
      allSlots.push({
        row,
        slotData,
        items,
        contractor_id: slotData.contractor_id,
        quantity: slotData.quantity,
        sort_order: slotData.sort_order || 0
      })
    }
  }
  const list = allSlots.filter(
    (slot) =>
      slot.quantity !== null && slot.quantity !== undefined && slot.quantity !== ''
  )

  list.sort((a, b) => {
    const ma = templateMatchRank(a)
    const mb = templateMatchRank(b)
    if (ma !== mb) return ma - mb

    const ca = contractorSortMeta(a.contractor_id)
    const cb = contractorSortMeta(b.contractor_id)
    if (ca.rank !== cb.rank) return ca.rank - cb.rank
    if (ca.id !== cb.id) return ca.id.localeCompare(cb.id)

    const ga = gridDisplayRank(a)
    const gb = gridDisplayRank(b)
    if (ga !== gb) return ga - gb
    return a.row - b.row
  })

  list.forEach((slot, i) => {
    slot.excelExportSeq = i
  })

  return list
}

/** 指示タブに表示されているコード（正規化済み）の集合 */
function collectInstructionNormCodesForExcelExport() {
  const set = new Set()
  for (const r of instructionMergeRows.value || []) {
    const nk = r?.normCode || normalizeExternalCode(r?.external_code)
    if (nk) set.add(nk)
  }
  return set
}

/**
 * エクセル出力前の確認対象:
 * is_item ON ＋ 親にコード ＋ そのコードが指示タブのコードに含まれる
 * @returns {{ code: string, content: string }[]}
 */
function collectIsItemInstructionCodeExcelExportMatches() {
  const instructionCodes = collectInstructionNormCodesForExcelExport()
  if (!instructionCodes.size) return []

  const matches = []
  for (let baseRow = 0; baseRow < rowCount; baseRow += 12) {
    if (isDeletedRow(baseRow)) continue
    if (!slotAggregatesItemQuantities(baseRow)) continue
    const codeRaw = String(getCellValue(baseRow, 3) || '').trim()
    const nk = normalizeExternalCode(codeRaw)
    if (!nk || !instructionCodes.has(nk)) continue

    const instruction = String(getCellValue(baseRow, 5) || '').trim()
    matches.push({
      code: codeRaw || nk,
      content: instruction || '—'
    })
  }
  return matches
}

function generateExcelPayload() {
  const validSlots = collectExcelSlotEntriesFromGrid()
  return buildExcelPayloadFromValidSlots(validSlots)
}

function buildExcelPayloadFromValidSlots(validSlots) {
  const contractorMap = new Map()
  contractors.value.forEach((c) => {
    contractorMap.set(String(c.id), {
      label: c.label,
      description: c.description || '',
      is_next: c.is_next || false,
      is_highlight: c.is_highlight || false,
      is_special: c.is_special || false,
      sort_order: c.sort_order || 0
    })
  })
  
  const def1Slots = []
  const def2Slots = []
  const defSlots = []
  const otherKeyGroups = {}
  
  validSlots.forEach(slot => {
    const key = slot.slotData.key?.trim() || ""
    
    if (key) {
      if (!otherKeyGroups[key]) otherKeyGroups[key] = []
      otherKeyGroups[key].push(slot)
    } else {
      if (slot.contractor_id) {
        const contractor = contractorMap.get(String(slot.contractor_id))
        if (contractor?.is_special) {
          return
        }
        if (contractor) {
          if (contractor.is_next) {
            def2Slots.push({ ...slot, contractor })
          } else {
            def1Slots.push({ ...slot, contractor })
          }
        } else {
          defSlots.push(slot)
        }
      } else {
        defSlots.push(slot)
      }
    }
  })
  
  const sortByContractorThenGrid = (a, b) => {
    const orderA = a.contractor?.sort_order || 0
    const orderB = b.contractor?.sort_order || 0
    if (orderA !== orderB) return orderA - orderB
    return (a.excelExportSeq ?? 0) - (b.excelExportSeq ?? 0)
  }

  def1Slots.sort(sortByContractorThenGrid)
  def2Slots.sort(sortByContractorThenGrid)
  defSlots.sort((a, b) => (a.excelExportSeq ?? 0) - (b.excelExportSeq ?? 0))
  
  Object.keys(otherKeyGroups).forEach(key => {
    otherKeyGroups[key].sort((a, b) => (a.excelExportSeq ?? 0) - (b.excelExportSeq ?? 0))
  })
  
  const payload = {}
  
  // def1グループ
  let def1Index = 1
  let lastContractorId1 = null
  let isFirstContractor1 = true
  
  def1Slots.forEach(slot => {
    if (slot.contractor_id !== lastContractorId1) {
      // 最初以外の依頼先では、空白のNを1つスキップ
      if (!isFirstContractor1) {
        def1Index++
      }
      
      // 依頼先ラベル（先頭に全角スペース2つ。PDF側で trim しない）
      let contractorLabel = slot.contractor.label
      contractorLabel = '　　' + contractorLabel
      
      payload[`def1-${def1Index}`] = {
        display: contractorLabel,
        is_contractor_label: true,
        is_highlight: slot.contractor.is_highlight,
        font_size: slot.contractor.is_highlight ? 'PLACEHOLDER' : null,
        font_style: 'bold',  // 依頼先ラベルは太字
        price_code: null, contractor_id: null, instruction: null, quantity: null,
        key: null, unit: null, sort_order: null, is_index: null, is_item: null,
        is_unit: null, is_quantity: null,
        is_item_location_category: null, is_item_instruction: null,
        is_item_quantity: null, items: []
      }
      def1Index++
      lastContractorId1 = slot.contractor_id
      isFirstContractor1 = false
    }
    
    payload[`def1-${def1Index}`] = {
      price_code: slot.slotData.price_code,
      contractor_id: slot.slotData.contractor_id,
      instruction: slot.slotData.instruction,
      quantity: slot.slotData.quantity,
      key: slot.slotData.key,
      unit: slot.slotData.unit,
      sort_order: slot.slotData.sort_order,
      is_index: slot.slotData.is_index,
      is_item: slot.slotData.is_item,
      is_unit: slot.slotData.is_unit,
      is_quantity: slot.slotData.is_quantity,
      is_item_location_category: slot.slotData.is_item_location_category,
      is_item_instruction: slot.slotData.is_item_instruction,
      is_item_quantity: slot.slotData.is_item_quantity,
      is_highlight: slot.contractor.is_highlight,
      font_size: slot.contractor.is_highlight ? 'PLACEHOLDER' : null,
      display: generateDisplayText(slot.slotData, slot.items),
      items: slot.items.map(item => ({
        price_code: item.price_code,
        location_category: item.location_category,
        instruction: item.instruction,
        quantity: item.quantity,
        sort_order: item.sort_order
      }))
    }
    def1Index++
  })
  
  // def2グループ
  let def2Index = 1
  let lastContractorId2 = null
  let isFirstContractor2 = true
  
  def2Slots.forEach(slot => {
    if (slot.contractor_id !== lastContractorId2) {
      // 最初以外の依頼先では、空白のNを1つスキップ
      if (!isFirstContractor2) {
        def2Index++
      }
      
      // 依頼先ラベル（先頭に全角スペース2つ。PDF側で trim しない）
      let contractorLabel = slot.contractor.label
      contractorLabel = '　　' + contractorLabel
      
      payload[`def2-${def2Index}`] = {
        display: contractorLabel,
        is_contractor_label: true,
        is_highlight: slot.contractor.is_highlight,
        font_size: slot.contractor.is_highlight ? 'PLACEHOLDER' : null,
        font_style: 'bold',  // 依頼先ラベルは太字
        price_code: null, contractor_id: null, instruction: null, quantity: null,
        key: null, unit: null, sort_order: null, is_index: null, is_item: null,
        is_unit: null, is_quantity: null,
        is_item_location_category: null, is_item_instruction: null,
        is_item_quantity: null, items: []
      }
      def2Index++
      lastContractorId2 = slot.contractor_id
      isFirstContractor2 = false
    }
    
    payload[`def2-${def2Index}`] = {
      price_code: slot.slotData.price_code,
      contractor_id: slot.slotData.contractor_id,
      instruction: slot.slotData.instruction,
      quantity: slot.slotData.quantity,
      key: slot.slotData.key,
      unit: slot.slotData.unit,
      sort_order: slot.slotData.sort_order,
      is_index: slot.slotData.is_index,
      is_item: slot.slotData.is_item,
      is_unit: slot.slotData.is_unit,
      is_quantity: slot.slotData.is_quantity,
      is_item_location_category: slot.slotData.is_item_location_category,
      is_item_instruction: slot.slotData.is_item_instruction,
      is_item_quantity: slot.slotData.is_item_quantity,
      is_highlight: slot.contractor.is_highlight,
      font_size: slot.contractor.is_highlight ? 'PLACEHOLDER' : null,
      display: generateDisplayText(slot.slotData, slot.items),
      items: slot.items.map(item => ({
        price_code: item.price_code,
        location_category: item.location_category,
        instruction: item.instruction,
        quantity: item.quantity,
        sort_order: item.sort_order
      }))
    }
    def2Index++
  })
  
  // defグループ
  let defIndex = 1
  defSlots.forEach(slot => {
    payload[`def-${defIndex}`] = {
      price_code: slot.slotData.price_code,
      contractor_id: slot.slotData.contractor_id,
      instruction: slot.slotData.instruction,
      quantity: slot.slotData.quantity,
      key: slot.slotData.key,
      unit: slot.slotData.unit,
      sort_order: slot.slotData.sort_order,
      is_index: slot.slotData.is_index,
      is_item: slot.slotData.is_item,
      is_unit: slot.slotData.is_unit,
      is_quantity: slot.slotData.is_quantity,
      is_item_location_category: slot.slotData.is_item_location_category,
      is_item_instruction: slot.slotData.is_item_instruction,
      is_item_quantity: slot.slotData.is_item_quantity,
