          quantity: item.quantity,
          sort_order: item.sort_order
        }))
      }
      keyIndex++
    })
  })
  
  // ルームラベル（sort_order 0-19）
  const roomlabels = []
  for (let i = 0; i < ROOM_LABEL_COUNT; i++) {
    const hit = roomLabels.value.find((l) => Number(l.sort_order) === i)
    roomlabels.push(removeCommentBlocks(hit?.label || ''))
  }
  payload.roomlabel = roomlabels

  appendSpecialContractorExcelPayload(payload)

  return payload
}

function buildSpecialContractorDisplay(entry, templateInstruction) {
  const tmpl = String(templateInstruction || '').trim()
  const content = String(entry?.content || '').trim()
  let contentPart = ''
  if (content) {
    if (entry.is_quantity) {
      const qtxt = formatPhotoQtyText(entry.quantity)
      contentPart = content + (qtxt ? `x${qtxt}` : '')
    } else {
      contentPart = content
    }
  } else if (entry.is_quantity) {
    const qtxt = formatPhotoQtyText(entry.quantity)
    if (qtxt) contentPart = `x${qtxt}`
  }
  // 特殊依頼先: 従来どおり半角ハイフンで結合
  if (!tmpl) return contentPart
  if (!contentPart) return tmpl
  if (tmpl === contentPart) return contentPart
  return `${tmpl}-${contentPart}`
}

function appendSpecialContractorExcelPayload(payload) {
  const fn = photoWorkPanelRef.value?.buildSpecialContractorExportEntries
  if (typeof fn !== 'function') return
  const entries = fn() || []
  if (!entries.length) return
  const tmplByCode = collectFirstInstructionByCodeFromGrid(
    estimateSlots.value,
    rowToSlotMap.value,
    getCellValue,
    getRowMod12
  )
  for (const entry of entries) {
    const nk = normalizeExternalCode(entry.external_code)
    // 特殊指示: 依頼先の一致/不一致に関わらず、コードに対する原本テキストを1回だけマージ
    const templateInstruction = tmplByCode instanceof Map ? (tmplByCode.get(nk) ?? '') : ''
    const display = buildSpecialContractorDisplay(entry, templateInstruction)
    payload[entry.payloadKey] = {
      price_code: entry.external_code,
      contractor_id: entry.contractor_id,
      instruction: display,
      quantity: entry.quantity,
      key: null,
      unit: null,
      sort_order: null,
      is_index: null,
      is_item: null,
      is_unit: null,
      is_quantity: null,
      is_item_location_category: null,
      is_item_instruction: null,
      is_item_quantity: null,
      is_highlight: entry.is_highlight,
      font_size: entry.is_highlight ? 'PLACEHOLDER' : null,
      display,
      items: []
    }
  }
}

async function prepareEstimateExportPayload() {
  applyPhotoMergeInstructionTotalsToEstimateGrid()
  await nextTick()
  recalculateAllSumQuantitiesBeforeSave()

  const excelTemplates = await indexedDBService.getTemplates('excel_templates')
  const estimateTemplate = excelTemplates.find((t) => t.is_estimate === true)
  const highlightedFontSize = estimateTemplate?.highlighted_font_size || null
  const wordCount = estimateTemplate?.word_count || null
  const highlightedWordCount = estimateTemplate?.highlighted_word_count || null

  let payload = generateExcelPayload()

  if (highlightedFontSize) {
    Object.keys(payload).forEach((key) => {
      if (payload[key] && typeof payload[key] === 'object') {
        if (payload[key].font_size === 'PLACEHOLDER') {
          payload[key].font_size = highlightedFontSize
        }
      }
    })
  }

  if (wordCount || highlightedWordCount) {
    splitExcelPayloadDisplayBraceBlocks(payload, wordCount, highlightedWordCount)
  }

  if (wordCount || highlightedWordCount) {
    const groupPrefixes = ['def1', 'def2', 'def']

    groupPrefixes.forEach((prefix) => {
      const groupKeys = Object.keys(payload)
        .filter((k) => k.startsWith(`${prefix}-`))
        .sort((a, b) => {
          const numA = parseInt(a.split('-')[1])
          const numB = parseInt(b.split('-')[1])
          return numA - numB
        })

      let i = 0
      while (i < groupKeys.length) {
        const currentKey = groupKeys[i]
        const currentSlot = payload[currentKey]

        if (prefix !== 'def' && isExcelContractorLabelSlot(currentSlot)) {
          i++
          continue
        }

        if (i + 1 < groupKeys.length) {
          const nextKey = groupKeys[i + 1]
          const nextSlot = payload[nextKey]

          if (prefix === 'def' || !isExcelContractorLabelSlot(nextSlot)) {
            if (isExcelDisplayContinuationSlot(currentSlot) || isExcelDisplayContinuationSlot(nextSlot)) {
              i++
              continue
            }

            const currentCount = countCharacters(currentSlot.display || '')
            const nextCount = countCharacters(nextSlot.display || '')
            const totalCount = currentCount + nextCount
            const threshold = currentSlot.is_highlight ? highlightedWordCount : wordCount

            if (threshold && totalCount <= threshold) {
              currentSlot.display = `${currentSlot.display} / ${nextSlot.display}`
              delete payload[nextKey]
              groupKeys.splice(i + 1, 1)
              continue
            }
          }
        }

        i++
      }

      const remainingSlots = []
      groupKeys.forEach((key) => {
        if (payload[key]) {
          remainingSlots.push(payload[key])
          delete payload[key]
        }
      })

      reassignExcelDefGroupSlots(payload, prefix, remainingSlots)
    })
  }

  stripExcelPayloadInternalFlags(payload)

  if (props.workId) {
    const [scheduleResult, statusOptions, scheduleTemplates] = await Promise.all([
      supabaseService.getWorkLargeSchedules(props.workId),
      supabaseService.getWorkScheduleStatuses(),
      supabaseService.getScheduleLabelTemplates(),
    ])
    let scheduleRows = scheduleResult.rows || []
    if (!scheduleRows.length) {
      scheduleRows = buildWorkLargeScheduleRowsFromTemplate(scheduleTemplates)
    } else {
      scheduleRows = padWorkLargeScheduleRows(scheduleRows)
    }
    Object.assign(payload, buildSchedulePdfPayloadFields(scheduleRows, statusOptions))
  }

  return payload
}

// PDF出力ハンドラー
async function handlePdfExport() {
  if (!props.workId) {
    await dialog.alert('Work IDが指定されていません', { title: 'エラー' })
    return
  }

  const pdfWindow = openPdfBlankTabForAsyncGenerate()
  const abortPdfTab = () => closePdfTab(pdfWindow)

  const templateMode = isTemporaryTemplatePreview.value ? 'temporary' : 'permanent'
  const templateRows = await indexedDBService.templates
    .where('table_name')
    .equals('estimate_slot_templates')
    .toArray()
  const templateCount = templateRows.filter((t) => (t.template_mode || 'permanent') === templateMode).length
  if (templateCount === 0) {
    abortPdfTab()
    await dialog.alert(
      templateMode === 'temporary'
        ? '一時テンプレートがありません。PDF出力できません。'
        : '通常テンプレートがありません。PDF出力できません。',
      { title: '中断' }
    )
    return
  }

  if (hasGridSlotDirty.value) {
    const ok = await dialog.confirm(
      '原本に未保存の変更があります。\nPDF出力後破棄されます。\n続行しますか？',
      { title: '確認' }
    )
    if (!ok) {
      abortPdfTab()
      return
    }
  }

  if (hasGridSlotDirty.value) {
    await clearOriginalGridSlotDirty()
  }

  const isItemExcelExportMatches = collectIsItemInstructionCodeExcelExportMatches()
  if (isItemExcelExportMatches.length) {
    const ok = await dialog.confirm(
      '上記の内容が反映されない可能性があります。\nPDF出力を続行しますか？\n※修正には、原本タブの▶展開後、\nその下の三本線ボタンをオフにしてください。',
      {
        title: '確認',
        confirmText: '続行',
        cancelText: 'キャンセル',
        bodyKind: 'gridContentList',
        preview: { rows: isItemExcelExportMatches }
      }
    )
    if (!ok) {
      abortPdfTab()
      return
    }
  }

  try {
    isExporting.value = true

    let payload = await prepareEstimateExportPayload()

    const overflowInfo = getEstimatePdfOverflowInfo(payload)
    if (overflowInfo.hasOverflow) {
      const ok = await dialog.confirm(
        `PDFの def 行数が上限（${ESTIMATE_PDF_DEF_MAX}行）を超えています。\n\n${buildEstimatePdfOverflowMessage(overflowInfo)}`,
        {
          title: '行数超過',
          confirmText: '出力',
          cancelText: 'キャンセル'
        }
      )
      if (!ok) {
        abortPdfTab()
        return
      }
      payload = capEstimatePdfDefPayload(payload)
    }

    const work = workData.value || currentWork.value
    const companyId = work?.company_id
    if (!companyId) {
      throw new Error('company_id が取得できません')
    }

    const pdfValues = convertEstimatePayloadToPdfValues(payload)

    let layoutData
    try {
      layoutData = await supabaseService.getPdfLayout(
        ESTIMATE_PDF_APPLICATIONS_CODES,
        props.workId,
        1,
        pdfValues,
        companyId
      )
    } catch (err) {
      if (err?.message?.includes('PDF_LAYOUT_NOT_CONFIGURED')) {
        throw new Error('PDF レイアウト未設定')
      }
      throw err
    }

    if (!layoutData?.layouts?.length) {
      throw new Error('PDF レイアウト未設定')
    }

    const pdfBytes = await generatePDFFromLayout(layoutData, pdfValues, {
      highResolutionPdf: false,
      embedScale: PDF_EMBED_DEFAULTS.embedScale,
      embedQuality: PDF_EMBED_DEFAULTS.embedQuality,
    })

    const fileName = buildEstimatePdfFileName(work)
    const blob = new Blob([pdfBytes], { type: 'application/pdf' })
    openGeneratedPdf(blob, { fileName, pdfWindow })
  } catch (error) {
    console.error('❌ PDF export failed:', error)
    abortPdfTab()
    await dialog.alert(`PDF出力に失敗しました: ${error.message}`, { title: 'エラー' })
  } finally {
    isExporting.value = false
    try {
      await reloadOriginalGridFromIndexedDbTemplate(templateMode)
      estimateSlotsLoadedWorkId = props.workId
    } catch (reloadErr) {
      console.error('❌ PDF export: template reload failed:', reloadErr)
    }
  }
}

