/* ========================================
   グリッド部分
======================================== */
.grid-wrapper {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: white;
  position: relative;
  z-index: 1;
  /* index-tabs の水平位置を grid-container の左パディングと同期 */
  --grid-container-padding-x: 1rem;
}

/* 付箋タブ（モバイル未満のフォールバック。901px以上は左端に上書き） */
.index-tabs {
  position: absolute;
  right: 0;
  top: calc(60px * var(--layout-scale, 1));
  width: var(--index-tab-width, calc(40px * var(--layout-scale, 1)));
  max-height: calc(100vh - 80px);
  overflow-y: auto;
  z-index: 100;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* PC・タブレット: 付箋タブ（位置・サイズ・色をタブレット版と統一） */
@media (min-width: 901px) {
  .estimate-grid-editor {
    --index-tab-width: calc(40px * 1.8 * 0.9);
  }
  .estimate-grid-editor .index-tabs {
    --layout-scale: 0.9;
    width: var(--index-tab-width);
    top: calc(60px * var(--layout-scale, 1) + 20px);
    left: calc(var(--grid-container-padding-x, 1rem) + 4px);
    right: auto;
    overflow-x: hidden;
    pointer-events: none;
    isolation: isolate;
  }

  .estimate-grid-editor .index-tab,
  .estimate-grid-editor .index-tab-toggle {
    pointer-events: auto;
    min-height: calc(52px * 9 / 10 * var(--layout-scale, 1));
    padding: calc(8px * 9 / 10 * var(--layout-scale, 1)) calc(3px * var(--layout-scale, 1));
    border-top-left-radius: 0;
    border-bottom-left-radius: 0;
    border-top-right-radius: 8px;
    border-bottom-right-radius: 8px;
    box-shadow: 2px 2px 6px rgba(0, 0, 0, 0.2);
    transition: none;
  }

  .estimate-grid-editor .index-tab {
    background: #fee2e2;
    color: #333;
  }

  .estimate-grid-editor .index-tab.active {
    background: #90ee90;
    color: #2d5016;
    font-weight: bold;
  }

  .estimate-grid-editor .index-tab-toggle {
    background: #ffe4e6;
    color: #111827;
  }

  .estimate-grid-editor .index-tab-toggle.active {
    background: #fda4af;
    color: #7f1d1d;
  }

  .estimate-grid-editor .index-tab:hover,
  .estimate-grid-editor .index-tab.active:hover {
    box-shadow: 3px 3px 8px rgba(0, 0, 0, 0.3);
    transform: none;
  }

  .estimate-grid-editor .index-tab-toggle:hover {
    transform: none;
  }

  .estimate-grid-editor .index-tab-number {
    font-size: calc(16px * 9 / 10 * var(--layout-scale, 1));
  }
}

.index-tab {
  background: linear-gradient(to right, #add8e6, #9ccad9); /* 不透明 */
  color: #333;
  padding: calc(8px * var(--layout-scale, 1)) calc(3px * var(--layout-scale, 1));
  cursor: pointer;
  border-top-left-radius: 8px;
  border-bottom-left-radius: 8px;
  box-shadow: -2px 2px 6px rgba(0, 0, 0, 0.2);
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: calc(60px * var(--layout-scale, 1));
  position: relative;
}

.index-tab-toggle {
  background: linear-gradient(to right, #d1d5db, #c4c9d0);
  color: #111827;
}

.index-tab-toggle.active {
  background: linear-gradient(to right, #60a5fa, #4f97ef);
  color: #1e3a8a;
}

.index-tab-toggle:hover {
  transform: translateX(-5px);
}

.index-tab.active {
  background: linear-gradient(to right, #90ee90, #7fdc7f); /* 不透明 */
  color: #2d5016;
  font-weight: bold;
}

.index-tab:hover {
  background: linear-gradient(to right, #b6deea, #a5d1df);
  box-shadow: -3px 3px 8px rgba(0, 0, 0, 0.3);
  transform: translateX(-5px);
}

.index-tab.active:hover {
  background: linear-gradient(to right, #9df39d, #8ce88c);
}

.index-tab-number {
  font-size: calc(16px * var(--layout-scale, 1));
  font-weight: bold;
}

