@media (max-width: 900px) {
  /* 上部：保存/Undo/ルーム/時計を表示（全開閉トグルは非表示） */
  .grid-header {
    padding: 0.5rem 0.75rem;
  }
  .grid-header-left {
    gap: 0;
  }
  /* ボタン同士/ボタンとタイトルの間隔をゼロにする */
  .grid-header-left > button,
  .grid-header-left > h2 {
    margin: 0 !important;
  }
  /* ルームボタンはデスクトップ用に margin-left があるのでモバイルでは無効化 */
  .grid-header-left > .room-label-button {
    margin-left: 0 !important;
  }
  /* いったん全部隠す */
  .grid-header-left > button {
    display: none;
  }
  /* 必要なボタンだけ出す */
  .grid-header-left > .save-button,
  .grid-header-left > .undo-button,
  .grid-header-left > .room-label-button,
  .grid-header-left > .clock-template-toggle,
  .grid-header-left > .excel-export-button,
  .grid-header-left > .schedule-calendar-btn--grid-header {
    display: flex;
    width: 30px;
    height: 30px;
    box-sizing: border-box;
  }
  .grid-header-right {
    gap: 0.25rem;
  }
  .grid-header-right .pw-feature-from-header {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    min-width: 30px;
    min-height: 30px;
    padding: 0;
    box-sizing: border-box;
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1;
    white-space: nowrap;
  }
  .grid-header-right .pw-feature-from-header--busy:disabled {
    gap: 0;
  }
  .grid-header-right .pw-feature-from-header .spinner-small {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
  }
  .grid-header-right > .master-template-reset-button {
    display: flex;
    width: 30px;
    height: 30px;
  }
  .grid-header h2 {
    font-size: 0.875rem;
    line-height: 1.2;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    /* 左側の5ボタン+余白ぶんを避ける（端末によって調整される） */
    max-width: 50vw;
  }
  /* 付箋タブ（スマホ・左端）
     - サイズ：幅=3/5、高さ=1/3（直前のモバイル基準: 幅60px・高さ78px から縮小）
     - 開始位置：挿入ボタン（40px）の高さ半分=20px 分だけ下にずらす */
  /* 原本タブ付箋: スマホでは左端 */
  .index-tabs {
    width: calc(120px * var(--layout-scale, 1)) !important; /* 現状の2倍幅 */
    top: calc(60px * var(--layout-scale, 1) + 20px) !important;
    left: 0 !important;
    right: auto !important;
    overflow-x: hidden !important;
  }
  .index-tab,
  .index-tab-toggle {
    border-top-left-radius: 0;
    border-bottom-left-radius: 0;
    border-top-right-radius: 8px;
    border-bottom-right-radius: 8px;
  }
  .index-tab {
    box-shadow: 2px 2px 6px rgba(0, 0, 0, 0.2);
  }
  .index-tab:hover,
  .index-tab.active:hover {
    box-shadow: 3px 3px 8px rgba(0, 0, 0, 0.3);
    transform: none;
  }
  .index-tab-toggle:hover {
    transform: none;
  }
  .index-tab {
    min-height: calc(72px * var(--layout-scale, 1));
    padding: calc(8px * var(--layout-scale, 1)) calc(3px * var(--layout-scale, 1));
    /* モバイル版: 薄い赤系（透過なし） */
    background: #fee2e2 !important;
  }
  .index-tab.active {
    background: #90ee90 !important;
    color: #2d5016;
  }
  .index-tab-toggle {
    background: #ffe4e6 !important;
  }
  .index-tab-toggle.active {
    background: #fda4af !important;
    color: #7f1d1d;
  }
  .index-tab-number {
    font-size: calc(32px * var(--layout-scale, 1));
  }

  /* 行番号（row-header）を非表示 */
  /* NOTE: display:none にすると列そのものが消えて colgroup が1列ずれてしまうため、
     “幅0のまま table-cell として残す” 方式にする */
  .row-header {
    display: table-cell;
    width: 0 !important;
    min-width: 0 !important;
    max-width: 0 !important;
    padding: 0 !important;
    border: none !important;
    color: transparent !important;
    background: transparent !important;
    overflow: hidden !important;
  }
  .col-row-header {
    width: 0 !important;
  }

  /* 列幅をcolgroupで効かせるため固定レイアウトに */
  .grid-table {
    table-layout: fixed;
    width: 100%;
  }
  .grid-table td.cell,
  .grid-table th.col-header {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* 下部バーからは重複ボタンを消す（上部に出すため） */
  .grid-mobile-actions .save-button,
  .grid-mobile-actions .room-label-button,
  .grid-mobile-actions .toggle-all-button,
  .grid-mobile-actions .add-template-button {
    display: none;
  }

  /* iPhone Safari の入力フォーカス時ズーム対策（font-size < 16px を避ける） */
  .estimate-grid-editor input,
  .estimate-grid-editor select,
  .estimate-grid-editor textarea,
  .estimate-grid-editor .cell-input,
  .estimate-grid-editor .cell-select,
  .estimate-grid-editor .search-input,
  .estimate-grid-editor .category-select,
  .estimate-grid-editor .pricelist-select,
  .estimate-grid-editor .comp-request-input {
    font-size: 16px !important;
  }

}

