  height: 32px;
  line-height: 32px;
  min-width: var(--index-tab-width, calc(40px * var(--layout-scale, 1)));
  width: var(--index-tab-width, calc(40px * var(--layout-scale, 1)));
  max-width: var(--index-tab-width, calc(40px * var(--layout-scale, 1)));
  position: sticky;
  left: 0;
  z-index: 2;
  overflow: hidden;
}

.row-header-dim {
  opacity: 0.4;
}

.col-header {
  top: 0;
  z-index: 1;
}

.row-header:first-child {
  z-index: 3;
}

.virtual-scroll-padding-row td {
  padding: 0 !important;
  border: none !important;
  line-height: 0;
  vertical-align: top;
}

.cell {
  border: 1px solid #e5e7eb;
  padding: 0;
  height: 32px;
  max-height: 32px;
  box-sizing: border-box;
  overflow: hidden;
  vertical-align: top;
  background: transparent; /* 透過して下のselection-overlayを見せる */
  cursor: cell;
  position: relative;
}

/* 全列を固定幅に設定 */
/* 1, 2, 3, 7, 8, 10, 11列目 = 67px */
.cell:nth-child(2),  /* 1列目 (0-indexed: 0) */
.cell:nth-child(3),  /* 2列目 (0-indexed: 1) */
.cell:nth-child(4),  /* 3列目 (0-indexed: 2) */
.cell:nth-child(8),  /* 7列目 (0-indexed: 6) */
.cell:nth-child(9),  /* 8列目 (0-indexed: 7) */
.cell:nth-child(11), /* 10列目 (0-indexed: 9) */
.cell:nth-child(12)  /* 11列目 (0-indexed: 10) */
{
  min-width: calc(67px * var(--layout-scale, 1));
  width: calc(67px * var(--layout-scale, 1));
  max-width: calc(67px * var(--layout-scale, 1));
}

/* 4列目 = 100px（デフォルト幅） */
.cell:nth-child(5)  /* 4列目 (0-indexed: 3) */
{
  min-width: calc(100px * var(--layout-scale, 1));
  width: calc(100px * var(--layout-scale, 1));
  max-width: calc(100px * var(--layout-scale, 1));
}

/* 5列目 = 200px */
.cell:nth-child(6)  /* 5列目 (0-indexed: 4) */
{
  min-width: calc(200px * var(--layout-scale, 1));
  width: calc(200px * var(--layout-scale, 1));
  max-width: calc(200px * var(--layout-scale, 1));
}

/* 6列目 = 550px */
.cell:nth-child(7)  /* 6列目 (0-indexed: 5) */
{
  min-width: calc(550px * var(--layout-scale, 1));
  width: calc(550px * var(--layout-scale, 1));
  max-width: calc(550px * var(--layout-scale, 1));
}

/* 数量列（0-indexed: 8）: 合計列削除分を加算 */
.estimate-grid-editor .grid-table td.cell[data-c="8"],
.estimate-grid-editor .grid-table th.col-header[data-c="8"] {
  min-width: calc(167px * var(--layout-scale, 1));
  width: calc(167px * var(--layout-scale, 1));
  max-width: calc(167px * var(--layout-scale, 1));
}

.estimate-grid-editor .grid-table td.cell[data-c="8"] .cell-display,
.estimate-grid-editor .grid-table td.cell[data-c="8"] .cell-input {
  text-align: left;
  justify-content: flex-start;
}

/* MOD12=1の9列目は右揃え */
.cell.align-right .cell-display,
.cell.align-right .cell-input {
  text-align: right;
  justify-content: flex-end;
}

.cell.selected {
  background: #dbeafe;
  border-color: #3b82f6;
  outline: 2px solid #3b82f6;
  outline-offset: -1px;
}

.cell.editing {
  background: white;
  position: relative;
}

/* 編集中のセルをオレンジ線で全周囲む */
.cell.editing::after {
  content: '';
  position: absolute;
  left: -3px;
  top: -3px;
  right: -3px;
  bottom: -3px;
  border: 3px solid #f59e0b;
  pointer-events: none;
  z-index: 100;
  box-sizing: border-box;
}

.cell.readonly {
  background: #f3f4f6;
  cursor: not-allowed;
}

.cell.readonly.selected {
  background: #e5e7eb;
}

/* 背景色：薄い緑 */
.cell.bg-green {
  background: #ecfdf5 !important;
}

.cell.bg-green.selected {
  background: #d1fae5 !important;
}

.cell.bg-green.editing {
  background: #ecfdf5 !important;
}

/* 背景色：入力不可時の薄いグレーっぽい緑 */
.cell.bg-green-disabled {
  background: #e8f5e9 !important;
  border: 2px solid #9ca3af !important;
}

.cell.bg-green-disabled.selected {
  background: #c8e6c9 !important;
  border: 2px solid #6b7280 !important;
}

.cell.bg-green-disabled.readonly {
  background: #e8f5e9 !important;
  border: 2px solid #9ca3af !important;
}

/* 原本タブ: コード列の帯・突合ヒント（薄い赤／薄い青） */
.cell.bg-code-rose {
  background: #ffe4e6 !important;
}
.cell.bg-code-rose.selected {
  background: #fecdd3 !important;
}
.cell.bg-code-rose.editing {
  background: #ffe4e6 !important;
}
.cell.bg-code-sky {
  background: #e0f2fe !important;
}
.cell.bg-code-sky.selected {
  background: #bae6fd !important;
}
.cell.bg-code-sky.editing {
  background: #e0f2fe !important;
}

/* 原本タブ: is_item ON かつ親行にコードあり */
.cell.bg-item-parent-code {
  background: #fef9c3 !important;
}
.cell.bg-item-parent-code.selected {
  background: #fef08a !important;
}
.cell.bg-item-parent-code.editing {
  background: #fef9c3 !important;
}
.estimate-grid-editor .grid-table tr.item-parent-with-code > td.row-header {
  background: #fef9c3 !important;
}

/* 原本タブ: 同一単価コードが複数ある行 */
.cell.bg-duplicate-code {
  background: #ffedd5 !important;
}
.cell.bg-duplicate-code.selected {
  background: #fed7aa !important;
}
.cell.bg-duplicate-code.editing {
  background: #ffedd5 !important;
}
.estimate-grid-editor .grid-table tr.duplicate-code-row > td.row-header {
  background: #ffedd5 !important;
}

.cell-display {
  padding: 0.375rem 0.5rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  height: 100%;
  display: flex;
  align-items: center;
}

.cell-display.price-description {
  font-size: 0.75rem;
  color: #6b7280;
}

.cell-input-wrapper {
  width: 100%;
  height: 100%;
}

.cell-input {
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  padding: 0.375rem 0.5rem;
  font-size: 0.875rem;
  font-family: inherit;
  background: white;
}

.cell-input:focus {
  outline: none;
}

/* ドラッグハンドル */
.drag-handle {
  cursor: grab;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: #6b7280; /* 既存スロット: 通常のグレー */
  user-select: none;
}

.drag-handle.new-slot {
  opacity: 0.3; /* 新規スロット: 薄いグレー */
}

.drag-handle.is-index {
  background: #fee2e2; /* is_indexがオンの時: 削除ボタンと同じ薄いピンク */
  color: #991b1b; /* アイコンの色: 削除ボタンと同じ濃い赤 */
}

.drag-handle:hover {
  color: #374151;
}

/* コピーボタン (MOD12=2, 列1) */
.copy-slot-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  border: none;
  background: transparent;
  color: #3b82f6; /* 青色 */
  cursor: pointer;
  padding: 0;
  transition: all 0.2s;
}

.copy-slot-button:hover {
  color: #1d4ed8; /* 濃い青 */
  background: #dbeafe; /* 薄い青背景 */
}

.copy-slot-button:disabled {
  color: #d1d5db; /* グレー */
  background: #f9fafb; /* 薄いグレー背景 */
  cursor: not-allowed;
  opacity: 1; /* opacityで透明にせず、色自体をグレーに */
}

.copy-slot-button:disabled:hover {
  color: #d1d5db;
  background: #f9fafb;
}

.copy-slot-button:disabled svg {
  stroke: #d1d5db; /* SVGアイコンもグレーに */
}

.drag-handle.is-index:hover {
  background: #fecaca; /* is_indexがオンの時のホバー: 削除ボタンのホバーと同じ */
  color: #7f1d1d; /* アイコンの色: 削除ボタンのホバーと同じ */
}

.drag-handle.new-slot:hover {
  opacity: 1.0;
}

.drag-handle:active {
  cursor: grabbing;
}

/* ドラッグ中の行 */
tr.dragging {
  opacity: 0.5;
  background: #dbeafe;
}

/* 削除対象の行 */
tr.deleted-row {
  background: #fee2e2 !important;
}

tr.deleted-row .cell {
  background: #fee2e2 !important;
}

tr.deleted-row .cell-display,
tr.deleted-row .cell-input {
  background: #fee2e2 !important;
}

/* ドロップ先の行 */
tr.drag-target {
  border-top: 3px solid #3b82f6;
}

/* トグルボタン */
.toggle-button {
  width: 100%;
  height: 100%;
  border: none;
  background: #3b82f6;
  color: white;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 600;
  transition: background 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.toggle-button.is-item {
  color: #fca5a5; /* is_itemがtrueの時: さらに濃いピンク */
}

.toggle-button:hover {
  background: #2563eb;
}

.toggle-button.collapsed {
  background: #9ca3af;
}

.toggle-button.collapsed.is-item {
  color: #fca5a5; /* 折りたたみ時もさらに濃いピンク */
}

.toggle-button.collapsed:hover {
  background: #6b7280;
}

/* 削除ボタン */
.delete-button {
  width: 100%;
  height: 100%;
  border: 1px solid #fca5a5;
  background: #fee2e2;
  color: #991b1b;
  cursor: pointer;
  font-size: 0.75rem;
  font-weight: 600;
