  color: #7f1d1d;
}

.delete-button.active {
  background: #ef4444;
  color: white;
  border-color: #ef4444;
}

.delete-button.active:hover {
  background: #dc2626;
  border-color: #dc2626;
}

/* 数量操作ボタン（C, -, +, U, N） */
.quantity-button {
  width: 100%;
  height: 100%;
  border: 1px solid #d1d5db;
  background: white;
  color: #6b7280;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.quantity-button:hover {
  background: #f3f4f6;
  border-color: #9ca3af;
}

.quantity-button:active {
  background: #e5e7eb;
}

.quantity-button:disabled,
.quantity-button.checked:disabled,
.quantity-button.expanded:disabled {
  background: #f9fafb !important;
  color: #d1d5db !important;
  border-color: #e5e7eb !important;
  cursor: not-allowed !important;
}

.quantity-button:disabled:hover,
.quantity-button.checked:disabled:hover,
.quantity-button.expanded:disabled:hover {
  background: #f9fafb !important;
  color: #d1d5db !important;
  border-color: #e5e7eb !important;
}

.quantity-button.checked {
  background: #dbeafe;
  color: #1e40af;
  border-color: #bfdbfe;
}

.quantity-button.checked:hover {
  background: #bfdbfe;
  border-color: #93c5fd;
}

.quantity-button.expanded {
  background: #fef3c7;
  color: #92400e;
  border-color: #fcd34d;
}

.quantity-button.expanded:hover {
  background: #fde68a;
  border-color: #fbbf24;
}

.quantity-button.expanded:active {
  background: #fcd34d;
}

/* MOD1 単位・数量・合計: OFF=単位系グレー ON=黄背景（従来 expanded に近い） */
.quantity-button.quantity-button--estimate-toggles {
  background: #ffffff;
  color: #6b7280;
  border: 1px solid #d1d5db;
}
.quantity-button.quantity-button--estimate-toggles.checked {
  background: #fef3c7;
  color: #92400e;
  border-color: #fcd34d;
}
.quantity-button.quantity-button--estimate-toggles:hover {
  background: #f3f4f6;
  border-color: #9ca3af;
}
.quantity-button.quantity-button--estimate-toggles.checked:hover {
  background: #fde68a;
  border-color: #fbbf24;
}
.quantity-button.quantity-button--estimate-toggles:active {
  background: #e5e7eb;
}
.quantity-button.quantity-button--estimate-toggles.checked:active {
  background: #fcd34d;
}

/* 原本タブ 数量列: 写真反映「→」ボタン */
.qty-cell-with-arrow {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.2rem;
  width: 100%;
}

.qty-cell-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  opacity: 0.9;
}

.qty-arrow-btn {
  border: 1px solid #d1d5db;
  background: #eff6ff;
  color: #1d4ed8;
  border-radius: 4px;
  width: 1.45rem;
  min-width: 1.45rem;
  height: 1.3rem;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
}

.qty-arrow-btn--full {
  position: relative;
  width: calc(100% + 2px);
  height: calc(100% + 2px);
  min-height: 100%;
  border-radius: 0;
  justify-content: center;
  padding: 0 0.2rem;
  border-color: #bfdbfe;
  margin: -1px;
}

.qty-arrow-btn--full .qty-cell-value {
  position: absolute;
  left: 0.2rem;
  right: 1rem;
  text-align: right;
}

.qty-arrow-btn:hover:not(:disabled) {
  background: #dbeafe;
  border-color: #93c5fd;
}

.qty-arrow-btn:disabled {
  background: #f9fafb;
  color: #d1d5db;
  border-color: #e5e7eb;
  cursor: not-allowed;
}

.qty-arrow-mark {
  flex: 0 0 auto;
  font-weight: 700;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) scaleX(1.55);
  transform-origin: center;
  font-size: 0.95rem;
  letter-spacing: 0.02em;
}

/* チェックボックスボタン */
.checkbox-button {
  width: 100%;
  height: 100%;
  border: 1px solid #d1d5db;
  background: white;
  color: #6b7280;
  cursor: pointer;
  font-size: 0.875rem;
  font-weight: 600;
