  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.checkbox-button:hover {
  background: #f3f4f6;
  border-color: #9ca3af;
}

/* チェックボックスボタンのオン時は薄い青 */
.checkbox-button.checked {
