import { ref, watch, nextTick } from 'vue'

/**
 * タッチのみ: 1 指ドラッグ + 2 指ピンチ。
 * boundsRef を渡すと左右はルート内にクランプ。上下はプレビュー枠 frameRef の内側にクランプ（はみ出し防止）。
 * @param {object} [transformOpts] - { minScale?, maxScale?, edgeMargin?, horizontalEdgeInset?, verticalEdgeInset?, verticalEdgeInsetTop?, verticalEdgeInsetBottom?, outerSize?, boardRotated90Ref?, disablePinch? }
 *   horizontalEdgeInset: プレビュー枠の左右だけクランプをこの px 分きつくする（短辺側の黒線対策）
 *   verticalEdgeInset: プレビュー枠の上下の既定インセット（上下個別が無いとき）
 *   verticalEdgeInsetTop / verticalEdgeInsetBottom: 上側・下側だけ別 px（下は操作ボタン帯用など）
 *   outerSize: 論理サイズ { width, height }、または () => { width, height }（プリセット切替時に再計算）
 *   boardRotated90Ref: inner を 90° 表示しているとき true の ref
 *   disablePinch: true のとき 2 指ピンチで拡縮しない
 */
export function useBoardOverlayTransform(
  frameRef,
  boardSizeRef,
  initialPosition,
  boundsRef = null,
  transformOpts = {}
) {
  const minScale = transformOpts.minScale ?? 0.45
  const maxScale = transformOpts.maxScale ?? 2.5
  const edgeMargin = transformOpts.edgeMargin ?? 1
  const horizontalEdgeInset = Math.max(0, Number(transformOpts.horizontalEdgeInset) || 0)
  const verticalEdgeInset = Math.max(0, Number(transformOpts.verticalEdgeInset) || 0)
  const verticalEdgeInsetTop = Math.max(
    0,
    transformOpts.verticalEdgeInsetTop != null
      ? Number(transformOpts.verticalEdgeInsetTop) || 0
      : verticalEdgeInset
  )
  const verticalEdgeInsetBottom = Math.max(
    0,
    transformOpts.verticalEdgeInsetBottom != null
      ? Number(transformOpts.verticalEdgeInsetBottom) || 0
      : verticalEdgeInset
  )
  const disablePinch = transformOpts.disablePinch === true
  const boardRotated90Ref = transformOpts.boardRotated90Ref ?? null

  function readOuterSize() {
    const o = transformOpts.outerSize
    if (typeof o === 'function') {
      const v = o()
      return v && typeof v.width === 'number' && typeof v.height === 'number'
        ? v
        : { width: 280, height: 200 }
    }
    return o && typeof o.width === 'number' && typeof o.height === 'number'
      ? o
      : { width: 280, height: 200 }
  }

  const x = ref(initialPosition?.x ?? 16)
  const y = ref(initialPosition?.y ?? 120)
  const scale = ref(initialPosition?.scale ?? 1)

  let dragging = false
  let pinch = false
  let startX = 0
  let startY = 0
  let startBoardX = 0
  let startBoardY = 0
  let startDist = 0
  let startScale = 1

  /** 枠ローカル: outer の translate(x,y) scale(s) origin top-left のあと、inner 90°(origin center) 時の見た目 AABB */
  function boardVisualAabbInFrame() {
    const { width: ow, height: oh } = readOuterSize()
    const s = scale.value
    const W = ow * s
    const H = oh * s
    const rotated = !!(boardRotated90Ref && boardRotated90Ref.value)
    if (!rotated) {
      return { left: x.value, top: y.value, width: W, height: H }
    }
    return {
      left: x.value + (W - H) / 2,
      top: y.value + (H - W) / 2,
      width: H,
      height: W
    }
  }

  function clampPosition() {
    const el = frameRef.value
    if (!el) return
    const margin = edgeMargin
    scale.value = Math.min(maxScale, Math.max(minScale, scale.value))

    const boundsEl = boundsRef?.value

    if (boundsEl) {
      const boundsRect = boundsEl.getBoundingClientRect()
      const frameRect = el.getBoundingClientRect()
      const maxW = Math.max(48, boundsRect.width - margin * 2)
      const maxH = Math.max(48, frameRect.height - margin * 2)

      for (let i = 0; i < 8; i++) {
        const a = boardVisualAabbInFrame()
        if (a.width <= maxW && a.height <= maxH) break
        const sx = maxW / a.width
        const sy = maxH / a.height
        scale.value *= Math.min(sx, sy, 1)
        scale.value = Math.min(maxScale, Math.max(minScale, scale.value))
      }

      const hi = horizontalEdgeInset
      const minLeft = boundsRect.left + margin + hi
      const maxRight = boundsRect.right - margin - hi
      const minTop = frameRect.top + margin + verticalEdgeInsetTop
      const maxBottom = frameRect.bottom - margin - verticalEdgeInsetBottom

      const aabb = boardVisualAabbInFrame()
      let clientLeft = frameRect.left + aabb.left
      let clientTop = frameRect.top + aabb.top
      const w2 = aabb.width
      const h2 = aabb.height
      const minL = minLeft
      const maxL = maxRight - w2
      const minT = minTop
      const maxT = maxBottom - h2
      const clampMaxL = Math.max(minL, maxL)
      const clampMaxT = Math.max(minT, maxT)
      clientLeft = Math.min(clampMaxL, Math.max(minL, clientLeft))
      clientTop = Math.min(clampMaxT, Math.max(minT, clientTop))

      const ax = clientLeft - frameRect.left
      const ay = clientTop - frameRect.top
      const rotated = !!(boardRotated90Ref && boardRotated90Ref.value)
      const { width: ow, height: oh } = readOuterSize()
      const W = ow * scale.value
      const H = oh * scale.value
      if (!rotated) {
        x.value = ax
        y.value = ay
      } else {
        x.value = ax - (W - H) / 2
        y.value = ay - (H - W) / 2
      }
    } else {
      const cw = el.clientWidth || 0
      const ch = el.clientHeight || 0
      const hi = horizontalEdgeInset
      const aabb = boardVisualAabbInFrame()
      const minAX = margin + hi - aabb.width
      const maxAX = cw - margin - hi - aabb.width
      const minAY = margin + verticalEdgeInsetTop - aabb.height
      const maxAY = ch - margin - verticalEdgeInsetBottom - aabb.height
      const clampMaxAX = Math.max(minAX, maxAX)
      const clampMaxAY = Math.max(minAY, maxAY)
      const ax = Math.min(clampMaxAX, Math.max(minAX, aabb.left))
      const ay = Math.min(clampMaxAY, Math.max(minAY, aabb.top))
      const rotated = !!(boardRotated90Ref && boardRotated90Ref.value)
      const { width: ow, height: oh } = readOuterSize()
      const W = ow * scale.value
      const H = oh * scale.value
      if (!rotated) {
        x.value = ax
        y.value = ay
      } else {
        x.value = ax - (W - H) / 2
        y.value = ay - (H - W) / 2
      }
    }

    scale.value = Math.min(maxScale, Math.max(minScale, scale.value))
  }

  watch(
    () => [frameRef.value?.clientWidth, frameRef.value?.clientHeight],
    () => clampPosition()
  )

  watch(
    () => [boardSizeRef.value?.width, boardSizeRef.value?.height],
    () => nextTick(() => clampPosition())
  )

  function distance(t1, t2) {
    const dx = t1.clientX - t2.clientX
    const dy = t1.clientY - t2.clientY
    return Math.hypot(dx, dy)
  }

  function onTouchStart(e) {
    if (e.touches.length === 1) {
      dragging = true
      pinch = false
      const t = e.touches[0]
      startX = t.clientX
      startY = t.clientY
      startBoardX = x.value
      startBoardY = y.value
    } else if (e.touches.length >= 2 && !disablePinch) {
      dragging = false
      pinch = true
      startDist = distance(e.touches[0], e.touches[1])
      startScale = scale.value
    } else if (e.touches.length >= 2 && disablePinch) {
      dragging = false
      pinch = false
    }
  }

  function onTouchMove(e) {
    if (!frameRef.value) return
    if (!disablePinch && pinch && e.touches.length >= 2) {
      e.preventDefault()
      const d = distance(e.touches[0], e.touches[1])
      if (startDist > 0) {
        scale.value = Math.min(maxScale, Math.max(minScale, (startScale * d) / startDist))
        clampPosition()
      }
      return
    }
    if (dragging && e.touches.length === 1) {
      e.preventDefault()
      const t = e.touches[0]
      const dx = t.clientX - startX
      const dy = t.clientY - startY
      x.value = startBoardX + dx
      y.value = startBoardY + dy
      clampPosition()
      // クランプ後の実座標と指位置を毎フレーム同期（境界付近で startBoardX+累積dx と実表示がずれてバグるのを防ぐ）
      startX = t.clientX
      startY = t.clientY
      startBoardX = x.value
      startBoardY = y.value
    }
  }

  function onTouchEnd(e) {
    if (e.touches.length === 0) {
      dragging = false
      pinch = false
    } else if (e.touches.length === 1 && pinch) {
      pinch = false
      dragging = true
      const t = e.touches[0]
      startX = t.clientX
      startY = t.clientY
      startBoardX = x.value
      startBoardY = y.value
    }
  }

  return {
    x,
    y,
    scale,
    clampPosition,
    onTouchStart,
    onTouchMove,
    onTouchEnd
  }
}
