<template>
  <div class="contractor-editor">
    <div class="editor-header">
      <div class="editor-header-left">
        <button 
          class="refresh-btn"
          @click="refreshContractors"
          :disabled="refreshing"
          title="サーバーから最新の依頼先を取得してIndexedDBを更新"
        >
          {{ refreshing ? '反映中' : '反映' }}
        </button>
        <h3>依頼先</h3>
      </div>
    </div>

    <div v-if="loading" class="loading-state">
      <span>読み込み中</span>
    </div>

    <div v-else-if="error" class="error-state">
      <span>{{ error }}</span>
      <button @click="loadContractors" class="retry-btn">再読み込み</button>
    </div>

    <div v-else class="contractors-list">
      <div 
        v-for="contractor in contractors" 
        :key="contractor.id"
        class="contractor-item"
        :class="{
          'is-dragging': draggingId === contractor.id,
          'drag-over': dragOverId === contractor.id,
          'is-hidden-from-select': !contractor.is_visible
        }"
        @dragend="handleDragEnd"
        @dragover.prevent="handleDragOver($event, contractor)"
        @dragleave="handleDragLeave"
        @drop.prevent="handleDrop($event, contractor)"
      >
        <div
          class="contractor-drag-handle"
          draggable="true"
          title="ドラッグして並べ替え"
          @dragstart.stop="handleDragStart($event, contractor)"
        >
          <span class="drag-icon">≡</span>
        </div>

        <div class="contractor-checkbox-with-label contractor-visible-toggle">
          <label :title="contractor.is_visible ? 'グリッドセレクトに表示' : 'グリッドセレクトから非表示'">
            <input
              type="checkbox"
              :checked="contractor.is_visible"
              @change="handleVisibilityChange(contractor, $event)"
            />
            <span class="checkbox-label">表示</span>
          </label>
        </div>

        <div class="contractor-checkbox-with-label">
          <label>
            <input 
              type="checkbox"
              :checked="contractor.is_next"
              @change="handleIsNextChange(contractor, $event)"
            />
            <span class="checkbox-label">次ページ</span>
          </label>
        </div>

        <div class="contractor-checkbox-with-label">
          <label>
            <input 
              type="checkbox"
              :checked="contractor.is_special"
              @change="handleIsSpecialChange(contractor, $event)"
            />
            <span class="checkbox-label">特殊指示</span>
          </label>
        </div>

        <div class="contractor-checkbox-with-label">
          <label>
            <input 
              type="checkbox"
              :checked="contractor.is_highlight"
              @change="handleIsHighlightChange(contractor, $event)"
            />
            <span class="checkbox-label">強調</span>
          </label>
        </div>

        <div class="contractor-fields">
          <input 
            type="text"
            class="contractor-label-input"
            :value="contractor.label"
            @blur="handleLabelChange(contractor, $event)"
            @keydown.enter="$event.target.blur()"
            placeholder="依頼先名を入力..."
          />
          <input 
            type="text"
            class="contractor-description-input"
            :value="contractor.description"
            @blur="handleDescriptionChange(contractor, $event)"
            @keydown.enter="$event.target.blur()"
            placeholder="説明（任意）"
          />
        </div>

        <button 
          class="delete-btn"
          @click="deleteContractor(contractor)"
          title="削除"
        >
          ✕
        </button>
      </div>

      <div v-if="contractors.length === 0" class="empty-state">
        <p>依頼先がありません</p>
      </div>

      <!-- 新規追加用の行 -->
      <div class="contractor-item add-new">
        <div class="contractor-drag-handle placeholder">
          <span class="drag-icon">≡</span>
        </div>
        <div class="contractor-checkbox-with-label contractor-visible-toggle placeholder">
          <label>
            <input type="checkbox" disabled />
            <span class="checkbox-label">表示</span>
          </label>
        </div>
        <div class="contractor-checkbox-with-label">
          <label>
            <input 
              type="checkbox"
              v-model="newContractorIsNext"
            />
            <span class="checkbox-label">次ページ</span>
          </label>
        </div>
        <div class="contractor-checkbox-with-label">
          <label>
            <input 
              type="checkbox"
              v-model="newContractorIsSpecial"
            />
            <span class="checkbox-label">特殊指示</span>
          </label>
        </div>
        <div class="contractor-checkbox-with-label">
          <label>
            <input 
              type="checkbox"
              v-model="newContractorIsHighlight"
            />
            <span class="checkbox-label">強調</span>
          </label>
        </div>
        <div class="contractor-fields">
          <input 
            type="text"
            class="contractor-label-input"
            v-model="newContractorLabel"
            @keydown.enter="addNewContractor"
            placeholder="新しい依頼先を追加..."
          />
          <input 
            type="text"
            class="contractor-description-input"
            v-model="newContractorDescription"
            @keydown.enter="addNewContractor"
            placeholder="説明（任意）"
          />
        </div>
        <button 
          class="add-btn"
          @click="addNewContractor"
          :disabled="!newContractorLabel.trim()"
          title="追加"
        >
          ＋
        </button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { supabaseService } from '../services/supabase'
import { useDialog } from '../composables/useDialog'

const emit = defineEmits(['refresh'])

const dialog = useDialog()

const contractors = ref([])
const selectedContractorIds = ref(new Set())
const loading = ref(true)
const error = ref(null)
const newContractorLabel = ref('')
const newContractorDescription = ref('')
const newContractorIsNext = ref(false)
const newContractorIsSpecial = ref(false)
const newContractorIsHighlight = ref(false)
const draggingId = ref(null)
const dragOverId = ref(null)
const refreshing = ref(false)

onMounted(() => {
  loadContractors()
})

async function loadContractors() {
  loading.value = true
  error.value = null
  try {
    const { contractors: list, contractorSelections } = await supabaseService.getContractors(true)
    selectedContractorIds.value = new Set(
      (contractorSelections || []).map(s => s.contractor_id)
    )
    contractors.value = list.map(c => ({
      ...c,
      is_visible: selectedContractorIds.value.has(c.id)
    }))
  } catch (err) {
    console.error('Failed to load contractors:', err)
    error.value = '依頼先の読み込みに失敗しました'
  } finally {
    loading.value = false
  }
}

async function refreshContractors() {
  refreshing.value = true
  try {
    const { contractors: list, contractorSelections } = await supabaseService.refreshContractors()
    selectedContractorIds.value = new Set(
      (contractorSelections || []).map(s => s.contractor_id)
    )
    contractors.value = list.map(c => ({
      ...c,
      is_visible: selectedContractorIds.value.has(c.id)
    }))
    
    // 親コンポーネントに通知
    emit('refresh')
  } catch (err) {
    console.error('Failed to refresh contractors:', err)
    await dialog.alert('依頼先の反映に失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    refreshing.value = false
  }
}

async function handleVisibilityChange(contractor, event) {
  const visible = event.target.checked
  if (visible === contractor.is_visible) return

  const oldVisible = contractor.is_visible
  contractor.is_visible = visible
  if (visible) {
    selectedContractorIds.value.add(contractor.id)
  } else {
    selectedContractorIds.value.delete(contractor.id)
  }

  try {
    await supabaseService.setContractorSelection(contractor.id, visible)

    const { indexedDBService } = await import('../utils/indexedDB')
    const profile = await supabaseService.getUserProfile()
    const userProfileId = profile?.user_profile_id
    if (userProfileId) {
      const compositeKey = `contractor_selections:${userProfileId}_${contractor.id}`
      if (visible) {
        await indexedDBService.templates.put({
          composite_key: compositeKey,
          table_name: 'contractor_selections',
          id: `${userProfileId}_${contractor.id}`,
          contractor_id: contractor.id,
          user_profile_id: userProfileId,
          updated_at: new Date().toISOString()
        })
      } else {
        await indexedDBService.templates.delete(compositeKey)
      }
    }
    emit('refresh')
  } catch (err) {
    console.error('Failed to update contractor visibility:', err)
    contractor.is_visible = oldVisible
    event.target.checked = oldVisible
    if (oldVisible) {
      selectedContractorIds.value.add(contractor.id)
    } else {
      selectedContractorIds.value.delete(contractor.id)
    }
  }
}

async function handleLabelChange(contractor, event) {
  const newLabel = event.target.value.trim()
  if (newLabel === contractor.label) return
  if (!newLabel) {
    event.target.value = contractor.label
    return
  }
  
  const isDuplicate = contractors.value.some(c => c.id !== contractor.id && c.label === newLabel)
  if (isDuplicate) {
    await dialog.alert('同じ名前の依頼先が既に存在します', { title: 'エラー' })
    event.target.value = contractor.label
    return
  }
  
  const oldLabel = contractor.label
  contractor.label = newLabel
  try {
    await supabaseService.updateContractor(contractor.id, { label: newLabel })
  } catch (err) {
    console.error('Failed to update label:', err)
    contractor.label = oldLabel
    event.target.value = oldLabel
    if (err.message.includes('既に存在')) {
      await dialog.alert('同じ名前の依頼先が既に存在します', { title: 'エラー' })
    }
  }
}

async function handleIsNextChange(contractor, event) {
  const newIsNext = event.target.checked
  if (newIsNext === contractor.is_next) return
  
  const oldIsNext = contractor.is_next
  contractor.is_next = newIsNext
  try {
    await supabaseService.updateContractor(contractor.id, { is_next: newIsNext })
  } catch (err) {
    console.error('Failed to update is_next:', err)
    contractor.is_next = oldIsNext
    event.target.checked = oldIsNext
  }
}

async function handleIsSpecialChange(contractor, event) {
  const newIsSpecial = event.target.checked
  if (newIsSpecial === contractor.is_special) return

  const oldIsSpecial = contractor.is_special
  contractor.is_special = newIsSpecial
  try {
    await supabaseService.updateContractor(contractor.id, { is_special: newIsSpecial })
  } catch (err) {
    console.error('Failed to update is_special:', err)
    contractor.is_special = oldIsSpecial
    event.target.checked = oldIsSpecial
  }
}

async function handleIsHighlightChange(contractor, event) {
  const newIsHighlight = event.target.checked
  if (newIsHighlight === contractor.is_highlight) return
  
  const oldIsHighlight = contractor.is_highlight
  contractor.is_highlight = newIsHighlight
  try {
    await supabaseService.updateContractor(contractor.id, { is_highlight: newIsHighlight })
  } catch (err) {
    console.error('Failed to update is_highlight:', err)
    contractor.is_highlight = oldIsHighlight
    event.target.checked = oldIsHighlight
  }
}

async function handleDescriptionChange(contractor, event) {
  const newDescription = event.target.value.trim()
  if (newDescription === contractor.description) return
  
  const oldDescription = contractor.description
  contractor.description = newDescription
  try {
    await supabaseService.updateContractor(contractor.id, { description: newDescription })
  } catch (err) {
    console.error('Failed to update description:', err)
    contractor.description = oldDescription
    event.target.value = oldDescription
  }
}

async function deleteContractor(contractor) {
  const ok = await dialog.confirm(`「${contractor.label}」を削除しますか？`, { title: '確認' })
  if (!ok) return
  
  const index = contractors.value.findIndex(c => c.id === contractor.id)
  const removed = contractors.value.splice(index, 1)[0]
  
  try {
    await supabaseService.deleteContractor(contractor.id)
  } catch (err) {
    console.error('Failed to delete contractor:', err)
    contractors.value.splice(index, 0, removed)
  }
}

async function addNewContractor() {
  const label = newContractorLabel.value.trim()
  if (!label) return
  
  const isDuplicate = contractors.value.some(c => c.label === label)
  if (isDuplicate) {
    await dialog.alert('同じ名前の依頼先が既に存在します', { title: 'エラー' })
    return
  }
  
  try {
    const newContractor = await supabaseService.addContractor(
      label, 
      newContractorDescription.value.trim(), 
      newContractorIsNext.value,
      newContractorIsHighlight.value,
      newContractorIsSpecial.value
    )
    contractors.value.push({
      ...newContractor,
      is_visible: false
    })
    newContractorLabel.value = ''
    newContractorDescription.value = ''
    newContractorIsNext.value = false
    newContractorIsSpecial.value = false
    newContractorIsHighlight.value = false
  } catch (err) {
    console.error('Failed to add contractor:', err)
    if (err.message.includes('既に存在')) {
      await dialog.alert('同じ名前の依頼先が既に存在します', { title: 'エラー' })
    } else {
      await dialog.alert('依頼先の追加に失敗しました', { title: 'エラー' })
    }
  }
}

function handleDragStart(event, contractor) {
  draggingId.value = contractor.id
  event.dataTransfer.effectAllowed = 'move'
  event.dataTransfer.setData('text/plain', contractor.id)
}

function handleDragEnd() {
  draggingId.value = null
  dragOverId.value = null
}

function handleDragOver(event, contractor) {
  if (draggingId.value && draggingId.value !== contractor.id) {
    dragOverId.value = contractor.id
  }
}

function handleDragLeave() {
  dragOverId.value = null
}

async function handleDrop(event, targetContractor) {
  const draggedId = draggingId.value
  if (!draggedId || draggedId === targetContractor.id) {
    dragOverId.value = null
    return
  }
  
  const draggedIndex = contractors.value.findIndex(c => c.id === draggedId)
  const targetIndex = contractors.value.findIndex(c => c.id === targetContractor.id)
  
  if (draggedIndex === -1 || targetIndex === -1) {
    dragOverId.value = null
    return
  }
  
  const [removed] = contractors.value.splice(draggedIndex, 1)
  contractors.value.splice(targetIndex, 0, removed)
  
  dragOverId.value = null
  
  await updateSortOrders()
}

async function updateSortOrders() {
  const updates = contractors.value.map((c, i) => ({
    id: c.id,
    sort_order: (i + 1) * 1000
  }))
  
  contractors.value.forEach((c, i) => {
    c.sort_order = (i + 1) * 1000
  })
  
  try {
    await supabaseService.reorderContractors(updates)
  } catch (err) {
    console.error('Failed to reorder contractors:', err)
    await loadContractors()
  }
}

defineExpose({
  loadContractors,
  loading
})
</script>

