import { renderBoardMasterCanvas, drawBoardMasterIntoDestination } from './boardTemplates.js'
import { resolveBoardDrawParts } from './boardTemplateConfig.js'

/** 旧メタの note を subject に連結してから描画（新形式は subject のみ） */
function normalizeBoardFieldsForDraw(raw) {
  const f = raw && typeof raw === 'object' ? { ...raw } : {}
  const sub = String(f.subject ?? '')
  const note = String(f.note ?? '').trim()
  if (note) {
    f.subject = sub ? `${sub}\n${note}` : note
  }
  delete f.note
  return f
}

/** 最終 JPEG（本番保存・黒板合成のみ）。一般アップロードの processImageForUpload とは別 */
const JPEG_QUALITY = 0.96
/** 保存画像は縦固定（3:4、長辺 1280）。一般アップロードの processImageForUpload と同じ基準 */
export const OUTPUT_PORTRAIT = { w: 960, h: 1280 }
/** 黒板「横向き」（rotateBoardCw90）のとき、縦合成後に 270° 回して横長（1280×960）で保存 */
export const OUTPUT_LANDSCAPE = { w: 1280, h: 960 }

/**
 * 固定サイズの枠内に video を object-fit: contain 相当で収める
 */
export function computeVideoContainInBox(boxW, boxH, vw, vh) {
  if (!vw || !vh || !boxW || !boxH) return null
  const scale = Math.min(boxW / vw, boxH / vh)
  const dispW = vw * scale
  const dispH = vh * scale
  const offsetX = (boxW - dispW) / 2
  const offsetY = (boxH - dispH) / 2
  return { offsetX, offsetY, dispW, dispH, boxW, boxH, vw, vh }
}

/**
 * 枠内に video を object-fit: cover 相当（狭い辺基準で拡大し、長辺方向は中央クロップ）
 * @returns {{ S: number, offsetX: number, offsetY: number, boxW: number, boxH: number, vw: number, vh: number } | null}
 */
export function computeVideoCoverInBox(boxW, boxH, vw, vh) {
  if (!vw || !vh || !boxW || !boxH) return null
  const S = Math.max(boxW / vw, boxH / vh)
  const dispW = vw * S
  const dispH = vh * S
  const offsetX = (boxW - dispW) / 2
  const offsetY = (boxH - dispH) / 2
  return { S, dispW, dispH, offsetX, offsetY, boxW, boxH, vw, vh }
}

/**
 * 枠ローカル座標の矩形を出力キャンバス座標へ
 */
export function frameRectToOutputRect(localRect, boxW, boxH, outW, outH) {
  return {
    x: (localRect.left * outW) / boxW,
    y: (localRect.top * outH) / boxH,
    width: (localRect.width * outW) / boxW,
    height: (localRect.height * outH) / boxH
  }
}

/**
 * プレビュー枠のコンテンツ幅・高さ（border 内＝ video object-fit: contain の基準と一致）。
 * getBoundingClientRect().width はボーダー込みのため、プレビュー側の clientWidth 基準とズレる。
 */
export function getFrameContentBox(frameEl) {
  const boxW = frameEl?.clientWidth
  const boxH = frameEl?.clientHeight
  if (!boxW || !boxH) return null
  return { boxW, boxH }
}

/**
 * ビューポート座標の矩形（getBoundingClientRect 等）を、枠コンテンツ左上原点のローカル座標へ
 */
export function viewportRectToFrameContentLocal(frameEl, viewportRect) {
  if (!frameEl || !viewportRect) {
    return { left: 0, top: 0, width: 1, height: 1 }
  }
  const fr = frameEl.getBoundingClientRect()
  const cs = getComputedStyle(frameEl)
  const bl = parseFloat(cs.borderLeftWidth) || 0
  const bt = parseFloat(cs.borderTopWidth) || 0
  return {
    left: viewportRect.left - fr.left - bl,
    top: viewportRect.top - fr.top - bt,
    width: viewportRect.width,
    height: viewportRect.height
  }
}

function resolveFrameSourceDimensions(frameSource) {
  if (!frameSource) return { el: null, vw: 0, vh: 0 }
  if (frameSource instanceof HTMLVideoElement) {
    return { el: frameSource, vw: frameSource.videoWidth, vh: frameSource.videoHeight }
  }
  const vw = frameSource.width ?? frameSource.naturalWidth ?? 0
  const vh = frameSource.height ?? frameSource.naturalHeight ?? 0
  return { el: frameSource, vw, vh }
}

/**
 * プレビュー枠（縦 3:4）と同一の contain（レターボックス可）で合成し、最初から 960×1280 に描く（中間解像度でのぼけを避ける）
 * @param {HTMLVideoElement | ImageBitmap | HTMLImageElement} frameSource
 * @param {HTMLElement} frameEl
 * @param {{ left: number, top: number, width: number, height: number }} boardRectRelativeToFrame
 * @param {Object} board
 * @param {boolean} includeBoard
 */
export async function compositeVideoFrameWithBoard(
  frameSource,
  frameEl,
  boardRectRelativeToFrame,
  board,
  includeBoard = true
) {
  const { el: drawable, vw, vh } = resolveFrameSourceDimensions(frameSource)
  if (!drawable) {
    throw new Error('撮影フレームが無効です')
  }
  if (!vw || !vh) {
    throw new Error('動画フレームが未取得です')
  }

  const contentBox = getFrameContentBox(frameEl)
  if (!contentBox) {
    throw new Error('プレビュー枠のサイズが無効です')
  }
  const { boxW, boxH } = contentBox

  const outW = OUTPUT_PORTRAIT.w
  const outH = OUTPUT_PORTRAIT.h

  const geom = computeVideoContainInBox(boxW, boxH, vw, vh)
  if (!geom) {
    throw new Error('プレビュー枠のサイズが無効です')
  }
  const kx = outW / boxW
  const ky = outH / boxH
  let sx = kx * geom.offsetX
  let sy = ky * geom.offsetY
  let sdw = kx * geom.dispW
  let sdh = ky * geom.dispH

  /**
   * プレビュー枠内で映像がほぼ全面に近いのに、出力マッピングで左右（または上下）に数 px の黒が残るのを防ぐ
   * （contain の理論上の余白が枠ピクセルでごく小さいときだけ全幅・全高に伸ばす）
   */
  const nearFullBleedMaxGapPx = 8
  const horizGapBox = geom.boxW - geom.dispW
  const vertGapBox = geom.boxH - geom.dispH
  if (horizGapBox >= 0 && horizGapBox <= nearFullBleedMaxGapPx) {
    sx = 0
    sdw = outW
  }
  if (vertGapBox >= 0 && vertGapBox <= nearFullBleedMaxGapPx) {
    sy = 0
    sdh = outH
  }

  /** 小数マッピングで左右上下に数 px の黒隙間が出るのを吸収（映像をわずかに拡げて塗りつぶす） */
  function expandVideoDestToRemoveEdgeGutters() {
    const maxGap = 5
    if (sx > 0 && sx <= maxGap) {
      sdw += sx
      sx = 0
    }
    let gapR = outW - (sx + sdw)
    if (gapR > 0 && gapR <= maxGap) {
      sdw = outW - sx
    }
    if (sy > 0 && sy <= maxGap) {
      sdh += sy
      sy = 0
    }
    let gapB = outH - (sy + sdh)
    if (gapB > 0 && gapB <= maxGap) {
      sdh = outH - sy
    }
    sx = Math.max(0, sx)
    sy = Math.max(0, sy)
    sdw = Math.min(sdw, outW - sx)
    sdh = Math.min(sdh, outH - sy)
  }
  expandVideoDestToRemoveEdgeGutters()

  const canvas = document.createElement('canvas')
  canvas.width = outW
  canvas.height = outH
  const ctx = canvas.getContext('2d')
  if (!ctx) {
    throw new Error('Canvas 2D が利用できません')
  }
  ctx.imageSmoothingEnabled = true
  ctx.imageSmoothingQuality = 'high'

  ctx.fillStyle = '#000000'
  ctx.fillRect(0, 0, outW, outH)

  ctx.drawImage(drawable, 0, 0, vw, vh, sx, sy, sdw, sdh)

  const br = boardRectRelativeToFrame
  const layoutW0 =
    typeof board?.layoutWidth === 'number' && board.layoutWidth > 0 ? board.layoutWidth : br.width
  const layoutH0 =
    typeof board?.layoutHeight === 'number' && board.layoutHeight > 0 ? board.layoutHeight : br.height
  const canvasRect = frameRectToOutputRect(
    { left: br.left, top: br.top, width: layoutW0, height: layoutH0 },
    boxW,
    boxH,
    outW,
    outH
  )

  if (includeBoard) {
    const drawParts = resolveBoardDrawParts(board)
    const drawOpts = {
      fieldLayout: drawParts.fieldLayout,
      fixedTexts: drawParts.fixedTexts,
      templatePublicFile: drawParts.templatePublicFile,
      templateRef: drawParts.templateRef
    }
    const fields = normalizeBoardFieldsForDraw(board?.fields)
    const master = await renderBoardMasterCanvas(fields, board.templateId || 'default', drawOpts)
    const rotateCw90 = !!(board && board.rotateBoardCw90)
    const layoutW = board?.layoutWidth
    const layoutH = board?.layoutHeight
    const bScale = board?.scale
    if (
      rotateCw90 &&
      typeof layoutW === 'number' &&
      typeof layoutH === 'number' &&
      typeof bScale === 'number' &&
      layoutW > 0 &&
      layoutH > 0
    ) {
      /** プレビューと同じ論理サイズへ。kx≠ky のわずかな差で黒板だけ縦横比が崩れないよう等方スケール */
      const kBoard = (kx + ky) / 2
      const outCardW = layoutW * bScale * kBoard
      const outCardH = layoutH * bScale * kBoard
      const cx = ((br.left + br.width / 2) / boxW) * outW
      const cy = ((br.top + br.height / 2) / boxH) * outH
      ctx.save()
      ctx.translate(cx, cy)
      ctx.rotate(Math.PI / 2)
      drawBoardMasterIntoDestination(
        ctx,
        master,
        -outCardW / 2,
        -outCardH / 2,
        Math.max(1, outCardW),
        Math.max(1, outCardH)
      )
      ctx.restore()
    } else {
      drawBoardMasterIntoDestination(
        ctx,
        master,
        canvasRect.x,
        canvasRect.y,
        Math.max(1, canvasRect.width),
        Math.max(1, canvasRect.height)
      )
    }
  }

/** 回転前（縦 960×1280）の JPEG。確認プレビュー用 */
  const portraitBlob = await canvasToJpegBlob(canvas, JPEG_QUALITY)

  /** 黒板向きボタン ON（横向き撮影）→ 1280×960・rotation 0 / OFF → 960×1280・rotation 270 */
  const exportLandscape = !!(board && board.rotateBoardCw90)
  let exportCanvas = canvas
  let exportW = outW
  let exportH = outH
  if (exportLandscape) {
    exportCanvas = rotateComposite270CwToLandscape(canvas, outW, outH)
    exportW = OUTPUT_LANDSCAPE.w
    exportH = OUTPUT_LANDSCAPE.h
  }

  /** 縦は同じキャンバスを二重に JPEG 化しない。横のみ回転後キャンバスを別エンコード */
  const blob = exportLandscape
    ? await canvasToJpegBlob(exportCanvas, JPEG_QUALITY)
    : portraitBlob

  return {
    blob,
    width: exportW,
    height: exportH,
    /** @deprecated 互換用。`exportLandscape` と同じ */
    isLandscapeSource: exportLandscape,
    exportLandscape,
    portraitBlob,
    portraitWidth: outW,
    portraitHeight: outH
  }
}

/**
 * 960×1280 の縦合成結果を、キャンバス上で 270°（時計回り）回転相当し 1280×960 にする
 * @param {HTMLCanvasElement} src 幅 sw・高さ sh
 */
function rotateComposite270CwToLandscape(src, sw, sh) {
  const dw = sh
  const dh = sw
  const out = document.createElement('canvas')
  out.width = dw
  out.height = dh
  const octx = out.getContext('2d')
  if (octx) {
    octx.imageSmoothingEnabled = true
    octx.imageSmoothingQuality = 'high'
  }
  octx.fillStyle = '#000000'
  octx.fillRect(0, 0, dw, dh)
  octx.translate(0, dh)
  octx.rotate(-Math.PI / 2)
  /** 描画先をごくわずかに拡げ、回転クリップ後の長辺付近の 1px 級の黒を抑える */
  const pad = 1
  octx.drawImage(src, 0, 0, sw, sh, -pad, -pad, sw + pad * 2, sh + pad * 2)
  return out
}

function canvasToJpegBlob(canvas, quality) {
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error('JPEG の生成に失敗しました'))),
      'image/jpeg',
      quality
    )
  })
}
