  snippetItemsByGroup: {
    type: Object,
    default: () => ({})
  },
  isSlotHeightExtended: {
    type: Boolean,
    default: false
  },
  isInstructionMode: {
    type: Boolean,
    default: false
  },
  instructionType: {
    type: String,
    default: 'number' // 'number' or 'content'
  },
  billingItems: {
    type: Array,
    default: () => []
  },
  isMobile: {
    type: Boolean,
    default: false
  },
  slotItemIsMobile: {
    type: Boolean,
    default: true
  },
  hideMoveSimilarButtons: {
    type: Boolean,
    default: false
  },
  hideRowInsertColumnDeleteButtons: {
    type: Boolean,
    default: false
  },
  hideSlotActionMenu: {
    type: Boolean,
    default: false
  },
  assignModeFileId: {
    type: String,
    default: null
  },
  reverseAssignModeSlotId: {
    type: [String, Number],
    default: null
  },
  reverseCompareAssignZone: {
    type: String,
    default: null
  },
  similarEmbeddingStatusByFileId: {
    type: Object,
    default: () => ({})
  },
  similarActionBusy: {
    type: Boolean,
    default: false
  },
  beforeAfterCompareMode: {
    type: Boolean,
    default: false
  },
  photoWorkLinksByFileId: {
    type: Object,
    default: () => ({})
  },
  compareAfterFileByRowId: {
    type: Object,
    default: () => ({})
  },
  compareBillingDroppedByRowId: {
    type: Object,
    default: () => ({})
  },
  compareBeforeFolderId: {
    type: String,
    default: null
  },
  compareAfterFolderId: {
    type: String,
    default: null
  },
  bacmpRoomLabelSelectOptions: {
    type: Array,
    default: () => []
  },
  compareRoomOrderByRowId: {
    type: Object,
    default: () => ({})
  },
  bacmpFilterMissingAfterOnly: {
    type: Boolean,
    default: false
