})

const emit = defineEmits([
  'reorder',
  'assign',
  'unassign',
  'upload',
  'update',
  'insert',
  'copy',
  'delete',
  'column-delete',
  'delete-page',
  'file-click',
  'slot-move',
  'slot-swap',
  'slot-copy',
  'row-insert',
  'file-swap',
  'file-copy',
  'page-reorder',
  'slot-drag-start',
  'slot-drag-end',
  'add-template',
  'create-template',
  'update-template',
  'delete-template',
  'show-snippet-list',
  'selection-change',
  'start-assign-from-slot',
  'open-similar-tab',
  'generate-similar-embedding',
  'compare-set-after-file',
  'compare-clear-after-file',
  'compare-clear-before-file',
  'compare-set-before-file',
  'compare-append-billing-line',
  'compare-delete-row',
  'compare-insert-after-row',
  'compare-add-row',
  'compare-room-label-order-change',
  'open-bacmp-comparison',
  'note-clipboard-action',
  'slot-note-edit',
  'slot-template-insert'
])

/** PC・タブレット・スマホ: スロット画像を1回目で選択（解除✕表示）、2回目で詳細モーダル */
const slotImageTwoClickSlotId = ref(null)
provide('slotGridSlotImageTwoClickSlotId', slotImageTwoClickSlotId)

const selectedTemplateIdForPage = ref({})
const showCreateTemplateModal = ref(false)
const templateLabel = ref('')
const currentGroupIndexForTemplate = ref(null)
const showEditTemplateModal = ref(false)
const editTemplateLabel = ref('')
const currentEditTemplateId = ref(null)
const currentEditGroupIndex = ref(null)
const collapsedPages = ref(new Set()) // 折りたたまれたページのページ開始スロットIDを保持
const selectedSlots = ref(new Set()) // 複数選択されたスロットIDを保持
const glowingSlots = ref(new Set()) // 光っているスロットIDを保持
const suppressNextDropGlow = ref(false) // 次回drop-completedの点滅を抑止
const slotItemRefs = ref({}) // 各SlotItemのref（単価コード変換適用用）

function setSlotItemRef(slotId, el) {
  if (el) slotItemRefs.value[slotId] = el
}

const gridGroups = computed(() => {
  return groupSlotsForGrid(props.slots)
})

const effectiveGridGroups = computed(() => {
  if (!props.beforeAfterCompareMode) return gridGroups.value
  const base = (props.slots || []).map((slot) => ({
    left: [slot],
    right: [],
    hasBreakBefore: false
  }))
  if (!props.bacmpFilterMissingAfterOnly) return base
  const af = props.compareAfterFileByRowId || {}
  return base.filter((g) => {
    const slot = g.left?.[0]
    if (!slot) return false
    const fid = af[slot.id]
    return fid == null || fid === ''
  })
})

// 区切り線を表示するかどうかを判定（すべてのページ先頭で表示）
function shouldShowBreakLine(group, groupIndex) {
  // すべてのグループで区切り線を表示
  return true
}

function handleAssign(slotId, fileId) {
  if (props.beforeAfterCompareMode) return
  emit('assign', slotId, fileId)
}

function handleStartAssignFromSlot(...args) {
  emit('start-assign-from-slot', ...args)
}

function handleOpenSimilarTab(payload) {
  emit('open-similar-tab', payload)
}

