// 単価コード変換を適用（変換後と内容が異なるスロットのみ上書きしてダーティ更新）
function applyInstructionConversion() {
  for (const [slotId, comp] of Object.entries(slotItemRefs.value)) {
    if (comp?.getConvertedNote && comp?.getCurrentNote) {
      const convertedNote = comp.getConvertedNote()
      const currentNote = comp.getCurrentNote()
      if (convertedNote !== (currentNote ?? '')) {
        handleUpdate(slotId, { note: convertedNote })
      }
    }
  }
}

