// ページにスクロール
// ページ1: save-button has-changes要素にスクロール
// ページ2以降: 前のページの最後のスロットの下端
function scrollToPage(groupIndex) {
  const pageStartSlotId = getPageStartSlotId(groupIndex)
  if (!pageStartSlotId) return

  activePageIndex.value = groupIndex

  // 全てのページでページヘッダーにスクロール
  const pageHeaderElement = document.querySelector(`[data-page-start="${pageStartSlotId}"]`)
  if (pageHeaderElement) {
    pageHeaderElement.scrollIntoView({ behavior: 'auto', block: 'start', inline: 'nearest' })
    return
  }

  // フォールバック: ページヘッダーが見つからない場合は最初のスロットにスクロール
  const slotElement = document.querySelector(`[data-slot-id="${pageStartSlotId}"]`)
  if (slotElement) {
    slotElement.scrollIntoView({ behavior: 'auto', block: 'start', inline: 'nearest' })
  }
}

/** 指定スロットがビューポート内に見えるようスクロール（タブレット左パネル展開時など） */
function scrollToSlot(slotId, options = {}) {
  const id = String(slotId ?? '')
  if (!id) return
  const behavior = options.behavior === 'auto' ? 'auto' : 'smooth'
  let slotElement = null
  try {
    slotElement = document.querySelector(`[data-slot-id="${CSS.escape(id)}"]`)
  } catch {
    slotElement = document.querySelector(`[data-slot-id="${id}"]`)
  }
  if (slotElement) {
    slotElement.scrollIntoView({ behavior, block: 'center', inline: 'nearest' })
  }
}

// 前のページの最後のスロットを取得
function getLastSlotInPreviousPage(groupIndex) {
  // 現在のページより前のグループを探索
  let previousPageLastGroupIndex = -1
  
  // 前のページの開始位置を探す
  for (let i = groupIndex - 1; i >= 0; i--) {
    if (gridGroups.value[i].hasBreakBefore) {
      // 前のページの開始位置が見つかった
      // その直前のグループが前のページの最後
      previousPageLastGroupIndex = i - 1
      break
    }
  }
  
  // 前のページの開始が見つからない場合（2ページ目の場合）
  if (previousPageLastGroupIndex < 0) {
    // groupIndex - 1 が1ページ目の最後のグループ
    previousPageLastGroupIndex = groupIndex - 1
  }
  
  if (previousPageLastGroupIndex < 0 || previousPageLastGroupIndex >= gridGroups.value.length) {
    return null
  }
  
  const lastGroup = gridGroups.value[previousPageLastGroupIndex]
  
  // 右側のスロットがあればそれを、なければ左側のスロットを返す
  if (lastGroup.right.length > 0) {
    return lastGroup.right[lastGroup.right.length - 1]
  } else if (lastGroup.left.length > 0) {
    return lastGroup.left[lastGroup.left.length - 1]
  }
  
  return null
}

// 現在表示中のページを判定（スクロール監視）
const activePageIndex = ref(0)

function isPageActive(groupIndex) {
  return activePageIndex.value === groupIndex
}

// スクロール位置を監視して、インデックスタブのアクティブページを更新
function updateActivePageOnScroll() {
  let currentPageIndex = 0
  let closestDistance = Infinity
  
  // 各ページの開始グループの位置を確認
  for (let i = 0; i < gridGroups.value.length; i++) {
    if (!gridGroups.value[i].hasBreakBefore) continue
    
    const pageStartSlotId = getPageStartSlotId(i)
    if (!pageStartSlotId) continue
    
    // ページヘッダーまたはスロット要素を探す
    let targetElement = document.querySelector(`[data-page-start="${pageStartSlotId}"]`)
    if (!targetElement) {
      targetElement = document.querySelector(`[data-slot-id="${pageStartSlotId}"]`)
    }
    if (!targetElement) continue
    
    const rect = targetElement.getBoundingClientRect()
    // ビューポート上端からの距離を計算
    const distance = Math.abs(rect.top)
    
    // ビューポート内、または最も近い位置にあるページをアクティブとする
    if (rect.top <= 100 && distance < closestDistance) {
      closestDistance = distance
      currentPageIndex = i
    }
  }
  
  activePageIndex.value = currentPageIndex
}

