}

// ページタブへのドロップ
function handlePageTabDrop(event, groupIndex) {
  event.currentTarget.classList.remove('drag-over')
  
  console.log('[handlePageTabDrop] Drop event triggered', { groupIndex, types: event.dataTransfer.types })
  
  // ページタブ自体のドラッグか、スロットのドラッグかを判定
  const isPageTabDrag = event.dataTransfer.types.includes('application/x-page-tab')
  
  console.log('[handlePageTabDrop] isPageTabDrag:', isPageTabDrag)
  
  if (isPageTabDrag) {
    // ページ並び替え処理
    handlePageReorder(event, groupIndex)
  } else {
    // スロット移動処理
    console.log('[handlePageTabDrop] Calling handleSlotDropOnPageTab')
    handleSlotDropOnPageTab(event, groupIndex)
  }
}

// ページ並び替え処理
function handlePageReorder(event, targetGroupIndex) {
  const sourceGroupIndexStr = event.dataTransfer.getData('application/x-page-tab')
  const sourceGroupIndex = parseInt(sourceGroupIndexStr, 10)
  
  if (isNaN(sourceGroupIndex) || sourceGroupIndex === targetGroupIndex) {
    return
  }
  
  const sourcePageNumber = getPageNumber(sourceGroupIndex)
  const targetPageNumber = getPageNumber(targetGroupIndex)

  // ドラッグ元のページの全スロットを取得
  const sourcePage = getAllSlotsInPage(sourceGroupIndex)
  if (sourcePage.length === 0) {
    console.warn('[PageReorder] No slots in source page')
    return
  }
  
  // ページ番号2→3（上から下）: ドラッグ先の最後尾のスロットとドラッグ先の次のページの先頭スロットの間
  if (sourcePageNumber < targetPageNumber) {
    // ドラッグ先の最後尾スロットを取得
    const targetLastSlot = getLastSlotInPage(targetGroupIndex)
    // ドラッグ先のページ+1の先頭スロットを取得
    const nextPageFirstSlot = getFirstSlotInNextPage(targetGroupIndex)
    
    // ドラッグ先の最後尾スロットの下に移動（次のページの先頭の前）
    if (targetLastSlot) {
      emit('page-reorder', {
        sourceSlots: sourcePage,
        targetSlotId: targetLastSlot.id,
        position: 'below'
      })
    }
  } else {
    // ページ番号3→2（下から上）: ドラッグ先の先頭スロットとドラッグ先の前のページの最後尾のスロットの間
    // ドラッグ先の先頭スロットを取得
    const targetFirstSlot = getFirstSlotInPage(targetGroupIndex)
    // ドラッグ先のページ-1の最後尾スロットを取得
    const prevPageLastSlot = getLastSlotInPreviousPage(targetGroupIndex)
    
    // ドラッグ先の先頭スロットの上に移動（前のページの最後尾の後）
    if (targetFirstSlot) {
      emit('page-reorder', {
        sourceSlots: sourcePage,
        targetSlotId: targetFirstSlot.id,
        position: 'above'
      })
    }
  }
}

// スロット移動処理（ページタブへのスロットドロップ）
function handleSlotDropOnPageTab(event, groupIndex) {
  console.log('[handleSlotDropOnPageTab] Started', { groupIndex })
  
  // ドラッグされているデータを取得
  let dragData
  try {
    const dataStr = event.dataTransfer.getData('text/plain')
    console.log('[handleSlotDropOnPageTab] Drag data:', dataStr)
    dragData = JSON.parse(dataStr)
  } catch (e) {
    console.warn('[handleSlotDropOnPageTab] Failed to parse drag data:', e)
    return
  }
  
  // スロットドラッグでない場合は処理しない
  if (dragData.type !== 'slot' || !dragData.slotId) {
    console.warn('[handleSlotDropOnPageTab] Not a slot drag:', dragData)
    return
  }
  
  const sourceSlotId = dragData.slotId
  console.log('[handleSlotDropOnPageTab] Source slot ID:', sourceSlotId)
  
  // ドロップ先ページの最後のスロットを取得
  const lastSlotInPage = getLastSlotInPage(groupIndex)
  if (!lastSlotInPage) {
    console.warn('[handleSlotDropOnPageTab] Last slot in page not found')
    return
  }
  
  console.log('[handleSlotDropOnPageTab] Last slot in page:', lastSlotInPage.id)
  console.log('[handleSlotDropOnPageTab] Selected slots:', Array.from(selectedSlots.value))
  
  // ↓移動の処理を実行（targetSlotIdは最後のスロット、position='below'）
  const selectedSlotIds = Array.from(selectedSlots.value)
  emit('slot-move', sourceSlotId, lastSlotInPage.id, 'below', selectedSlotIds)
  
  // 光らせる処理
  const hasMultipleSelection = selectedSlots.value.size > 0
  
  if (hasMultipleSelection) {
    // 複数選択時：チェックが入っていたスロット + ドロップで落としたスロット（ソース）を光らせる
    selectedSlots.value.forEach(id => {
      glowingSlots.value.add(id)
    })
    glowingSlots.value.add(sourceSlotId)
  } else {
    // 単一ドロップ時：移動なのでドロップしたスロット（ソース）のみ光らせる
    glowingSlots.value.add(sourceSlotId)
  }
  
  // 複数選択を解除
  selectedSlots.value.clear()
  emit('selection-change', Array.from(selectedSlots.value))
  
  // 1.5秒後に光る効果を解除
  setTimeout(() => {
    glowingSlots.value.clear()
  }, 1500)
}

// 次のページの最初のスロットを取得
function getFirstSlotInNextPage(groupIndex) {
  // 次のページの開始位置を探す
  let nextPageIndex = -1
  for (let i = groupIndex + 1; i < gridGroups.value.length; i++) {
    if (gridGroups.value[i].hasBreakBefore) {
      nextPageIndex = i
      break
    }
  }
  
  // 次のページが見つからない場合（最後のページ）
  if (nextPageIndex === -1) {
    return null
  }
  
  const nextPageGroup = gridGroups.value[nextPageIndex]
  
  // 左側のスロットがあればそれを、なければ右側のスロットを返す
  if (nextPageGroup.left.length > 0) {
    return nextPageGroup.left[0]
  } else if (nextPageGroup.right.length > 0) {
    return nextPageGroup.right[0]
  }
  
  return null
}

// ページの最後のスロットを取得
function getLastSlotInPage(groupIndex) {
  // 次のページの開始位置を探す
  let nextPageIndex = -1
  for (let i = groupIndex + 1; i < gridGroups.value.length; i++) {
    if (gridGroups.value[i].hasBreakBefore) {
      nextPageIndex = i
      break
    }
  }
  
  // 最後のページの場合
  if (nextPageIndex === -1) {
    const lastGroup = gridGroups.value[gridGroups.value.length - 1]
    if (lastGroup.right.length > 0) {
      return lastGroup.right[lastGroup.right.length - 1]
    } else if (lastGroup.left.length > 0) {
      return lastGroup.left[lastGroup.left.length - 1]
    }
  } else {
    // 次のページの直前のグループの最後のスロット
    const lastGroupInPage = gridGroups.value[nextPageIndex - 1]
    if (lastGroupInPage.right.length > 0) {
      return lastGroupInPage.right[lastGroupInPage.right.length - 1]
    } else if (lastGroupInPage.left.length > 0) {
      return lastGroupInPage.left[lastGroupInPage.left.length - 1]
    }
  }
  
  return null
}

// ページ内の全スロットを取得
function getAllSlotsInPage(groupIndex) {
  const allSlots = []
  
  // ページの開始インデックスを取得
  const pageStartIndex = findFirstGroupIndexInPage(groupIndex)
  
  // 次のページの開始インデックスを取得
  let nextPageIndex = -1
  for (let i = groupIndex + 1; i < gridGroups.value.length; i++) {
    if (gridGroups.value[i].hasBreakBefore) {
      nextPageIndex = i
      break
    }
  }
  
  // ページの終了インデックスを決定
  const pageEndIndex = nextPageIndex === -1 ? gridGroups.value.length - 1 : nextPageIndex - 1
  
  // ページ内のすべてのグループからスロットを収集
  for (let i = pageStartIndex; i <= pageEndIndex; i++) {
    const group = gridGroups.value[i]
    if (group) {
      allSlots.push(...group.left, ...group.right)
    }
  }
  
  return allSlots
}

// ページの最初のスロットを取得
function getFirstSlotInPage(groupIndex) {
  const firstGroupIndex = findFirstGroupIndexInPage(groupIndex)
  const firstGroup = gridGroups.value[firstGroupIndex]
  
  if (!firstGroup) return null
  
  // 左側のスロットがあればそれを、なければ右側のスロットを返す
  if (firstGroup.left.length > 0) {
    return firstGroup.left[0]
  } else if (firstGroup.right.length > 0) {
    return firstGroup.right[0]
  }
  
  return null
}

// ページ開始スロットのIDを取得（break_beforeがtrueのスロット、または最初のページの最初のスロット）
function getPageStartSlotId(groupIndex) {
  const firstGroupIndex = findFirstGroupIndexInPage(groupIndex)
  const firstGroup = gridGroups.value[firstGroupIndex]
  
  if (!firstGroup) return null
  
  // 最初のグループの最初のスロット（左側または右側）を取得
  let firstSlot = null
  if (firstGroup.left.length > 0) {
    firstSlot = firstGroup.left[0]
  } else if (firstGroup.right.length > 0) {
    firstSlot = firstGroup.right[0]
  }
  
  if (!firstSlot) return null
  
  // 最初のページの場合、最初のスロットをページ開始スロットとして扱う
  if (firstGroupIndex === 0) {
    return firstSlot.id
  }
  
  // 最初のページ以外の場合、最初のグループ内でbreak_beforeがtrueのスロットを探す
  // groupSlotsForGridのロジック上、break_beforeがtrueのスロットでページが区切られるため、
  // 最初のグループの最初のスロットがページ開始スロットのはず
  // 念のため、最初のグループ内のすべてのスロットを確認
  const allSlotsInFirstGroup = [...firstGroup.left, ...firstGroup.right]
  for (const slot of allSlotsInFirstGroup) {
    const slotObj = props.slots.find(s => s.id === slot.id)
    if (slotObj && slotObj.break_before) {
      return slot.id
    }
  }
  
  // break_beforeがtrueのスロットが見つからない場合、最初のスロットをページ開始として扱う
  // （これは通常発生しないはずだが、念のため）
  return firstSlot.id
}

// ページが折りたたまれているかどうかを判定
function isPageCollapsed(groupIndex) {
  const pageStartSlotId = getPageStartSlotId(groupIndex)
  if (!pageStartSlotId) return false
  
  // ページ開始スロットIDで折りたたみ状態を確認
  // デフォルトでは展開状態（false）なので、Setに含まれていれば折りたたまれている
  return collapsedPages.value.has(pageStartSlotId)
}

// ページの折りたたみをトグル
function togglePage(groupIndex) {
  const pageStartSlotId = getPageStartSlotId(groupIndex)
  if (!pageStartSlotId) return
  
  if (collapsedPages.value.has(pageStartSlotId)) {
    collapsedPages.value.delete(pageStartSlotId)
  } else {
    collapsedPages.value.add(pageStartSlotId)
  }
}

// すべてのページをトグル
function toggleAllPages() {
  // 一つでもページが展開されていれば、すべて折りたたむ
  // すべて折りたたまれていれば、すべて展開する
  const shouldCollapse = isAnyPageExpanded()
  
  if (shouldCollapse) {
    // すべて折りたたむ
    for (let i = 0; i < gridGroups.value.length; i++) {
      if (gridGroups.value[i].hasBreakBefore) {
        const pageStartSlotId = getPageStartSlotId(i)
        if (pageStartSlotId) {
          collapsedPages.value.add(pageStartSlotId)
        }
      }
    }
  } else {
    // すべて展開する
    collapsedPages.value.clear()
  }
}

// 一つでもページが展開されているかどうかを判定
function isAnyPageExpanded() {
  // すべてのページのページ開始スロットIDを取得
  const allPageStartSlotIds = []
  for (let i = 0; i < gridGroups.value.length; i++) {
    if (gridGroups.value[i].hasBreakBefore) {
      const pageStartSlotId = getPageStartSlotId(i)
      if (pageStartSlotId) {
        allPageStartSlotIds.push(pageStartSlotId)
      }
    }
  }
  
  // 一つでも折りたたまれていないページがあれば true
  return allPageStartSlotIds.some(id => !collapsedPages.value.has(id))
}

function triggerMoveGlow(slotIds = []) {
  if (!Array.isArray(slotIds) || slotIds.length === 0) return
  slotIds.forEach((id) => {
    if (id) glowingSlots.value.add(id)
  })
  setTimeout(() => {
    glowingSlots.value.clear()
  }, 1500)
}

function setSuppressNextDropGlow(flag = true) {
  suppressNextDropGlow.value = !!flag
}

function ensurePageExpandedForSlot(slotId) {
  const id = String(slotId ?? '')
  if (!id) return

  for (let gi = 0; gi < gridGroups.value.length; gi++) {
    const group = gridGroups.value[gi]
    const inGroup =
      group.left.some((s) => String(s.id) === id) ||
      group.right.some((s) => String(s.id) === id)
    if (!inGroup) continue

    let pageGroupIndex = gi
    while (pageGroupIndex > 0 && !gridGroups.value[pageGroupIndex].hasBreakBefore) {
      pageGroupIndex--
    }
    const pageStartSlotId = getPageStartSlotId(pageGroupIndex)
    if (pageStartSlotId && collapsedPages.value.has(pageStartSlotId)) {
      collapsedPages.value.delete(pageStartSlotId)
    }
    return
  }
}

// 親コンポーネントから呼び出されるメソッドを公開
defineExpose({
  toggleAllPages,
  isAnyPageExpanded,
  applyInstructionConversion,
  triggerMoveGlow,
  setSuppressNextDropGlow,
  scrollToSlot,
  ensurePageExpandedForSlot
})

// スロット行を表示するかどうかを判定
function shouldShowSlotRow(groupIndex) {
  if (props.beforeAfterCompareMode) return true
