/** ⋯メニュー: ドロップの左/中央/右と同じ emit 経路 */
function handleSlotActionMenu({ action, targetSlotId }) {
  if (props.isMobile) return

  if (action === 'note-edit') {
    emit('slot-note-edit', targetSlotId)
    return
  }
  if (action === 'template-insert') {
    emit('slot-template-insert', targetSlotId)
    return
  }
  if (action === 'row-insert') {
    handleRowInsert(targetSlotId)
    return
  }
  if (action === 'column-delete') {
    handleColumnDelete(targetSlotId)
    return
  }

  const selectedSlotIds = Array.from(selectedSlots.value)
  if (selectedSlotIds.length === 0) return
  const fromSlotId = pickFromSlotIdForMenu(selectedSlotIds)

  if (action === 'move-up') {
    emit('slot-move', fromSlotId, targetSlotId, 'left', selectedSlotIds)
    handleDropCompleted({ targetSlotId, operationType: 'move', sourceSlotId: fromSlotId })
  } else if (action === 'move-down') {
    emit('slot-swap', fromSlotId, targetSlotId, selectedSlotIds)
    handleDropCompleted({ targetSlotId, operationType: 'move', sourceSlotId: fromSlotId })
  } else if (action === 'copy') {
    emit('slot-copy', fromSlotId, targetSlotId, selectedSlotIds)
    handleDropCompleted({ targetSlotId, operationType: 'copy', sourceSlotId: fromSlotId })
  }
}

