// ドロップ完了時の処理
function handleDropCompleted(dropData) {
  // ドロップ完了時はドラッグ監視を完全停止して内部状態をリセットする
  stopGlobalDragListener()
  // DOM更新タイミングによってdragendが欠落するケースがあるため、明示的に終了を通知
  if (props.isSlotDragging) {
    emit('slot-drag-end')
  }
  
  const { targetSlotId, operationType, sourceSlotId } = dropData
  const shouldSkipGlow = suppressNextDropGlow.value
  suppressNextDropGlow.value = false
  
  // 複数選択されているかどうか
  const hasMultipleSelection = selectedSlots.value.size > 0
  
  if (!shouldSkipGlow && hasMultipleSelection) {
    // 複数選択時：チェックが入っていたスロット + ドロップで落としたスロット（ソース）を光らせる
    selectedSlots.value.forEach(id => {
      glowingSlots.value.add(id)
    })
    if (sourceSlotId) {
      glowingSlots.value.add(sourceSlotId)
    }
  } else if (!shouldSkipGlow) {
    // 単一ドロップ時
    if (operationType === 'copy') {
      // コピー：ドロップ先のスロットを光らせる
      glowingSlots.value.add(targetSlotId)
    } else if (operationType === 'move') {
      // 移動：ドロップしたスロット（ソース）を光らせる
      if (sourceSlotId) {
        glowingSlots.value.add(sourceSlotId)
      }
    } else {
      // その他（upload, assign, billing, file-swap, file-copy）：ターゲットを光らせる
      glowingSlots.value.add(targetSlotId)
    }
  }
  
  // チェックボックスを全てオフにする
  selectedSlots.value.clear()
  emit('selection-change', Array.from(selectedSlots.value))
  
  // 1.5秒後に光る効果を解除（アニメーションの長さに合わせる）
  if (!shouldSkipGlow) {
    setTimeout(() => {
      glowingSlots.value.clear()
    }, 1500)
  }
}

function handleCreateTemplateClick(groupIndex) {
  currentGroupIndexForTemplate.value = groupIndex
  templateLabel.value = ''
  showCreateTemplateModal.value = true
}

function closeCreateTemplateModal() {
  showCreateTemplateModal.value = false
  templateLabel.value = ''
  currentGroupIndexForTemplate.value = null
}

function handleCreateTemplate() {
  if (!templateLabel.value || templateLabel.value.trim() === '') {
    return
  }
  
  // ラベルの重複チェック
  const trimmedLabel = templateLabel.value.trim()
  const duplicateTemplate = props.slotTemplates.find(t => t.label === trimmedLabel)
  if (duplicateTemplate) {
    void dialog.alert(`テンプレート名「${trimmedLabel}」は既に存在します。別の名前を入力してください。`, { title: 'エラー' })
    return
  }
  
  const groupIndex = currentGroupIndexForTemplate.value
  if (groupIndex === null || groupIndex === undefined) {
    return
  }
  
  // ページの最初のグループインデックスを取得
  const firstGroupIndex = findFirstGroupIndexInPage(groupIndex)
  
  // ページ内のすべてのグループからスロットIDを取得
  const slotIds = []
  let currentIndex = firstGroupIndex
  
  // 次のページ開始（hasBreakBeforeがtrue）まで、または最後までスロットを収集
  while (currentIndex < gridGroups.value.length) {
    const group = gridGroups.value[currentIndex]
    if (!group) break
    
    // 次のページ開始に到達したら終了（最初のグループ以外でhasBreakBeforeがtrue）
    if (currentIndex > firstGroupIndex && group.hasBreakBefore) {
      break
    }
    
    // 左側のスロット
    group.left.forEach(slot => {
      if (slot && slot.id) {
        slotIds.push(slot.id)
      }
    })
    // 右側のスロット
    group.right.forEach(slot => {
      if (slot && slot.id) {
        slotIds.push(slot.id)
      }
    })
    
    currentIndex++
  }
  
  if (slotIds.length === 0) {
    closeCreateTemplateModal()
    return
  }
  
  emit('create-template', {
    label: templateLabel.value.trim(),
    slotIds: slotIds,
    groupIndex: firstGroupIndex
  })
  
  closeCreateTemplateModal()
}

