export function keihiSelectToHasExpenses(value) {
  if (value === '1') return true
  if (value === '2') return false
  return null
}

export function hasExpensesToKeihiSelect(hasExpenses) {
  if (hasExpenses === true) return '1'
  if (hasExpenses === false) return '2'
  return ''
}
